  ["42:41a1"] = "柱子摇晃得很微妙吧？\n上面有很多和尚\011在进行修行哦。",
  ["42:41da"] = "安放着宝可梦雕像……\n有一种神圣的感觉。",
  ["42:42ad"] = "就算我们大闹一场\n这座塔也纹丝不动！",
  ["42:42e3"] = "我这人雷声大雨点小……！",
  ["42:4303"] = "即使发生了大地震，\n只要有这根柱子在，\011这座塔就不会塌……！",
  ["42:4345"] = "如同在风中\n飘摇的落叶……",
  ["42:4365"] = "我真是软弱无力——！",
  ["42:4373"] = "虽然我的战斗方式借鉴了\n喇叭芽优雅的身姿。\011但修为似乎不够啊。",
  ["42:43cc"] = "安放着宝可梦雕像……\n有一种神圣的感觉。",
  ["42:452b"] = "长老：这位施主\n确有真才实学。\012按照约定，这个\n秘传学习器就是施主的了。\012不过，施主应该\n对宝可梦好一点啊。\012施主的战斗方式太严苛了，\n宝可梦并非是\011用来对战的道具……",
  ["42:45f0"] = "…… …… ……\012……哼！\n虽然被别人叫作长老，\011但也没多了不起嘛。\012……这也难怪。\n我怎么可能输给\011像他这样天真地说出\011“善待宝可梦”的人！\012我只看得上\n战无不胜的宝可梦。\012其他的宝可梦\n爱怎么样怎么样！",
  ["42:46cc"] = "{RIVAL}使用了\n离洞绳！",
  ["42:46e4"] = "施主竟然能来到这里！\012在这座喇叭芽之塔，\n通过修行来确认\011人与宝可梦能否\011通往光明的未来。\012接下来，最后的考验\n便是贫僧了。\012那么就让贫僧确认一下\n施主和宝可梦的牵绊！",
  ["42:47b6"] = "嗯，\n善哉善哉。",
  ["42:47c6"] = "施主和施主的宝可梦\n应该可以妥善运用\011这个秘传吧。\012就请施主带走\n秘传学习器——闪光！",
  ["42:4817"] = "学会了闪光之后，\n不论多么晦暗的地方，\011都可以用它照亮！\012不过，战斗之外使用时，\n必须先持有\011桔梗道馆授予的徽章。",
  ["42:488c"] = "愿施主在旅途中\n能得到诸多收获。",
  ["42:48ba"] = "我的修行能让\n宝可梦之道登峰造极！",
  ["42:48e2"] = "男孩输给了男孩……",
  ["42:48fb"] = "宝可梦变强的同时，\n训练家也会一起变强。\012不，应该说训练家变强了，\n宝可梦才会变强。",
  ["42:4961"] = "你究竟对宝可梦\n有多少信赖呢？\011就让我来确认一下！",
  ["42:498b"] = "嗯！\n充满信赖！",
  ["42:49a5"] = "马上就能到长老\n的身边了！",
  ["42:49c2"] = "长老所赐予的秘传学习器\n可以照亮一切黑暗。",
  ["42:49f4"] = "在发光的\n是我的脑袋——！",
  ["42:4a13"] = "愿你的前路\n一片光明。",
  ["42:4a38"] = "用强而有力的笔触\n画出来的喇叭芽……",
  ["42:4a62"] = "安放着宝可梦雕像……\n有一种神圣的感觉。",
  ["42:4b20"] = "据说传说的宝可梦\n会在这里降临，\011而我一直在追寻它的秘密。\012西侧的塔烧毁之后，\n曾经待在这里的宝可梦\011一直在天空中盘旋。\012按我的推测，\n只要带着来自空中那只\011宝可梦的某种物品\011应该就能把它被吸引过来！\012如果没猜错，那个物品……\012就是虹色之羽！\012但是要去哪里\n才能找到这种东西呢？",
  ["42:4f24"] = "…… …… ……\012……怎么又是你？\012我猜是因为大家都说\n传说的宝可梦沉睡在这里，\011你想稍微再变强一点，\011所以就想来找它们，对吧。\012但是那根本不现实啊。\012能捉到传说的宝可梦的人\n一定会是我……\012毕竟我将会成为\n最强的训练家，\011传说的宝可梦才配上我嘛。\012……至于你，明明这么弱，\n还天天东跑西跑的\011真的很碍眼啊。",
  ["42:5093"] = "……哼！\012所以我才讨厌\n和废物进行对战！\011一不小心就玩过头了。",
  ["42:50da"] = "……切，算了。\012反正你这样的人\n根本就不可能\011捉到传说的宝可梦！",
  ["42:5124"] = "……哼！\012所以我才讨厌\n和废物进行对战！\011根本就是浪费时间！",
  ["42:516d"] = "被你看到我在这里偷偷练习\n太难为情啦——！",
  ["42:51ac"] = "燃烧殆尽了……\n只剩一片灰白……",
  ["42:51cb"] = "太专注于练习，\n不小心掉进洞里了，哇哈哈",
  ["42:5202"] = "我的灵魂正在燃烧，\n你也感受一下这份炽热！",
  ["42:5236"] = "温度还不够高吗？",
  ["42:524d"] = "据说在过去，\n会有一些宝可梦\011以惊人的速度游走于各地。\012它们快得像一阵风，\n即使碰巧在草丛中遇到，\011它们也会立刻逃走！",
  ["42:552a"] = "之前有很多地鼠\n从地底扑了过来！\011啊——吓死了——！",
  ["42:562d"] = "…… …… ……\012久违了，{PLAYER}。\012……我输给你之后，\n一直都在和我的宝可梦\011一起探讨我到底\011有什么不足……\012然后我终于找到答案了，\n{PLAYER}！\011你就好好看着吧！",
  ["42:56c5"] = "…… …… ……\012还以为我的培育方式\n可以最大限度地发挥\011宝可梦的潜力……\012……还是不够吗。",
  ["42:5722"] = "…… …… ……\012……确实是我输了。\012这次我就认输吧。\n但绝不会到此为止！\012我总有一天会成为\n最强的宝可梦训练家！\012……因为有\n宝可梦们跟着我。\012……听好了，{PLAYER}，\n总有一天我会打倒你，\011让你深切体会我的实力！",
  ["42:5808"] = "…… …… ……\012这样就算清帐了。\012……下次我要和宝可梦们\n一起打倒冠军，\011然后成为世界上\011最强的宝可梦训练家。",
  ["42:5a87"] = "慢着！\012……接下来要去挑战\n宝可梦联盟吗？\012……开什么玩笑！\n你比我弱多了！\012我已经不是从前的我了！\012我现在获得了\n最棒、最强的宝可梦！\011简直就是天下无敌！\012{PLAYER}！\n来和我对战吧！",
  ["42:5b65"] = "……赢不了啊。\012我明明使出全力了……\012你一定具备一些\n我所没有的东西……\012我好像开始理解\n龙使者的那番话了……",
  ["42:5bf6"] = "…… …… ……\012我并没有放弃\n成为最强的训练家。\012我要弄清楚失败的原因，\n努力变得更强！\011然后会再来找你挑战的。\012到那个时候，我会用尽\n浑身解数来打败你！\012……哼！在那之前，\n你就努力挣扎吧。",
  ["42:5cd2"] = "……哼！\012果然要靠实力说话，\n其他的都是虚的！",
  ["43:4196"] = "快看，快看！\n我的包包！\012把最喜欢的宝可梦图鉴\n打印出来贴上去了！",
  ["43:41f1"] = "这张小纸片啊，\n是我女儿寄来的信件。\011我很高兴呢。",
  ["43:4228"] = "喂，别开小差——！\012……啊，糟糕，\n当老师当习惯了。\012你是宝可梦训练家吧？\012看在你这么努力的份上，\n就把这个送给你吧！",
  ["43:42d0"] = "这是先制之爪。\n让宝可梦携带后，\011偶尔可以抢先\011发起进攻哦！",
  ["43:4320"] = "我把宝可梦图鉴打印出来\n和朋友玩游戏！",
  ["43:4352"] = "谁赢了，谁就能拿走\n对手的图鉴贴纸！",
  ["43:437f"] = "我经常来公园里散步，\n但是从来没进过草坪。\012因为那里的训练家\n总是会找人对战！",
  ["43:43d9"] = "猫老大：呼，呼沙——！",
  ["43:43ed"] = "我正在用打印机\n打印宝可梦图鉴！\012信件或电脑盒子\n也是可以打印的哦！",
  ["43:4441"] = "宝可梦学非常深奥，\n现在还有很多未解之谜。\012但是我的知识储备量\n肯定是比你丰富的！",
  ["43:44a7"] = "唔唔唔？",
  ["43:44b6"] = "有很多知识必须要记住。\012比如说……\n招式学习器共有50种，\011与人交换得到的宝可梦\011成长的速度会更快。",
  ["43:4514"] = "我的宝可梦太可爱了，\n能让我向你炫耀炫耀吗？",
  ["43:4547"] = "它们好像不太适合对战啊，\n明明很适合拿来炫耀呢……",
  ["43:4584"] = "朋友有只玛力露，\n真的超级可爱啊！\011真好啊，我也想要玛力露。",
  ["43:45c1"] = "永远都要疼爱宝可梦！\n哪怕会被宝可梦嫌弃！\011这是发烧友俱乐部的规定！",
  ["43:4611"] = "小、小宝可梦！",
  ["43:461d"] = "虽然输了对战，\n但是我的宝可梦更可爱，\011这方面是我赢了！",
  ["43:4662"] = "怎么了，\n你干嘛盯着别人的脸？\012诶，要和我对战？",
  ["43:4693"] = "……嗯。",
  ["43:469b"] = "你一直盯着我，\n我都怀疑对我动心了！\012毕竟我这么可爱嘛！",
  ["43:46e4"] = "休息广场\n自然公园",
  ["43:4705"] = "这里贴着一张告示！\012宝可梦对战\n只能在草丛中进行。\012……自然公园\n管理事务所留……",
  ["43:475a"] = "有用的公告牌！\012在信件的界面\n按START键，\011就能打印信件！",
  ["43:48e0"] = "干泰：第一名一定是我！\n不要妨碍我！",
  ["43:4907"] = "辉奇：我的派拉斯特\n会使出蘑菇孢子\011让扑过来的宝可梦睡着！",
  ["43:4937"] = "小建：为了赢得比赛，\n我专门培养敏捷的宝可梦！",
  ["43:4960"] = "彰宏：第几名无所谓，\n我只想找稀有的宝可梦。",
  ["43:49a9"] = "贞夫：……嘘！\n飞天螳螂要跑了！回头聊。",
  ["43:49e6"] = "雄一：捉虫宝可梦之前，\n要先削弱它们再投球，\011这点很重要的。",
  ["43:4a25"] = "里美：你有意见？\n女生收集虫宝可梦怎么了？",
  ["43:4a70"] = "友道：从出生开始\n我就一心捕捉虫宝可梦，\011怎么可能会输呢！",
  ["43:4acd"] = "康太：有时间闲聊的话，\n去找宝可梦不是更好吗？",
  ["43:4b0c"] = "智行：我学过很多\n虫宝可梦的相关知识，\011我一定会是第一名！",
  ["43:4b4f"] = "休息广场\n自然公园",
  ["43:4b70"] = "这里贴着一张告示！\012宝可梦对战\n只能在草丛中进行。\012……自然公园\n管理事务所留……",
  ["43:4bc5"] = "有用的公告牌！\012在信件的界面\n按START键，\011就能打印信件！",
  ["43:4e1f"] = "欢迎光临！",
  ["43:4e29"] = "欢迎光临……\n非常抱歉，\011现在不能参观。",
  ["43:4e62"] = "您好，这里是兑换处。\012我们会核对您拥有的\n宝可梦的ID号码，\011运气好的话就能得到奖品！",
  ["43:4ee2"] = "本次的ID号码是\n{STRBUF}。",
  ["43:4f02"] = "那么请允许我\n立刻核对一下。",
  ["43:4f26"] = "下次公布时，\n期待您能再次光临。",
  ["43:4f5d"] = "5、5位数完全一致！\n1等奖！是1等奖！\0121等奖奖品是——\n大师球！",
  ["43:4fcb"] = "哇，最后3位数完全一致！\n是2等奖！\0122等奖奖品是——\n学习装置！",
  ["43:501e"] = "最后2位数完全一致！\n中了3等奖！\0123等奖奖品是——\nPP提升剂！",
  ["43:5068"] = "非常遗憾，\n没有一位数对得上。",
  ["43:508e"] = "您的行李已经满了。\n等您整理行好李之后，\011请尽快回来领奖。",
  ["43:50d5"] = "现在正在进行特别活动！\012如果能完全答对\n我们提出的5个问题，\011我们将会奖励广播卡！\012广播卡插入宝可装置后，\n就能随时随地收听广播了。\011你想挑战一下吗？",
  ["43:519a"] = "好的，第1题！\012可以使用宝可装置\n查看城镇地图吗？",
  ["43:51d1"] = "回答正确。\n下面是第2题！\012叫做尼多娜的宝可梦\n性别只有♀吗？",
  ["43:5204"] = "回答正确。\n接着是第3题！\012精灵球工匠钢铁先生\n使用的材料是圆果吗？",
  ["43:524d"] = "又回答正确了。\n那么第4题！\012叫做鲤鱼王的宝可梦\n无法学习招式学习器吗？",
  ["43:528b"] = "真厉害！\n终于到最后一问了。\012人气节目——\n大木博士宝可梦讲座\011中的搭档是小桃胡吗？",
  ["43:530b"] = "全部回答正确，\n恭喜您！\011请收下奖品——广播卡！",
  ["43:5350"] = "{PLAYER}的宝可装置\n现在可以听广播了！",
  ["43:5375"] = "希望您随时都能\n收听我们的节目！",
  ["43:5399"] = "哎呀，答错了呢。\n真可惜！\011请您再接再厉！",
  ["43:53d3"] = "这样吗，\n等你有兴趣的话再来吧。",
  ["43:5403"] = "说到主播，就要提到靖史！\n他那甜美的声音……\012真是令人着迷！",
  ["43:5439"] = "我喜欢宝可梦讲座的\n胡桃小姐姐哦！\012……虽然只听过她的声音。",
  ["43:5481"] = "终于占领了播音塔！\n我们要让全国领教\011火箭队的厉害！\012就先让你感受感受\n我们的厉害吧！",
  ["43:550f"] = "这，这家伙好强……\n其他人也要小心啊。",
  ["43:552f"] = "你太强了。\012这样下去计划肯定会泡汤，\n必须通知其他同伴……",
  ["43:5574"] = "1楼 …… 服务柜台\n2楼 …… 营业部\0113楼 …… 总务部\0114楼 …… 制作室\0115楼 …… 台长室",
  ["43:55be"] = "幸运频道！\n你的宝可梦的ID是？\012通过交换宝可梦\n来收集各种ID吧！",
  ["43:570e"] = "随时随地都能听广播！\n随时随地都要听广播！",
  ["43:5740"] = "收音机里播出的摇篮曲\n也能让宝可梦睡着哦。",
  ["43:576d"] = "他们占领电台\n到底是出于什么目的……？",
  ["43:57a0"] = "小胖丁：噗……噗噗……",
  ["43:57b5"] = "居然说上面的楼层\n“闲人免入”……\012这可真是前所未闻，\n台长最近很不对劲啊。",
  ["43:582e"] = "所有地方都能自由参观。\n台长终于又变回了\011以前那个和善的台长！",
  ["43:5885"] = "3年前，火箭队走投无路\n被迫选择解散……\012但是，我们要在此宣布：\n火箭队复活了！",
  ["43:58db"] = "咕，\n这家伙一点都不可爱。",
  ["43:58f1"] = "怎么能让你一个小屁孩\n妨碍我们的复活大计！",
  ["43:5923"] = "我们是——\n宝可梦黑手党火箭队！\011专门喜欢干坏事。\012哦哟，吓到了吗？",
  ["43:596a"] = "你想表演正义的伙伴？",
  ["43:5983"] = "别老是说\n我们火箭队在做坏事！\011我们是在做喜欢的事！",
  ["43:59b7"] = "喂喂！\n不要妨碍我们啊！",
  ["43:59d7"] = "呜呜……真没办法。",
  ["43:59ea"] = "干部们劫持这里\n好像是要密谋什么大事，\011那么，究竟是要干什么呢？",
  ["43:5a4e"] = "嚯嚯嚯！\n没想到轻易就占领了这里，\011真没意思！\012你来陪我解解闷吧？",
  ["43:5aa9"] = "你是何方神圣！？",
  ["43:5aba"] = "居然比我还强……\012不可原谅！",
  ["43:5ade"] = "2楼 …… 营业部",
  ["43:5ae8"] = "大木博士的宝可梦讲座，\n时下最火爆的广播节目！",
  ["43:5b1b"] = "随时随地都能收听——\n宝可梦广播",
  ["43:5cbf"] = "完全收录了迄今发现的\n所有宝可梦叫声！\011共计200多种呢！",
  ["43:5d20"] = "对训练家而言，\n宝可梦是重要的搭档。\012竟然有人粗暴地使唤它们，\n宝可梦也太可怜了！",
  ["43:5d89"] = "我们全天候营业！\012为了让大家随时都能\n拥有愉快的节目体验，\011我也会努力一整天！",
  ["43:5df2"] = "这帮家伙的老大\n锁在门里面不出来。\012就算是从内部上锁，\n台长也有办法打开！\012台长现在在5楼！\n求你了，去救救他吧！",
  ["43:5e69"] = "台长没事吧？",
  ["43:5e80"] = "谢谢你，小英雄！\n这是我送的谢礼！",
  ["43:5ebf"] = "里面是大晴天。\n使用一次后，\011火属性的威力会暂时提高。",
  ["43:5efa"] = "你的表现真是出色！",
  ["43:5f16"] = "我的任务嘛……\012就是把妨碍火箭队的人\n打得站不起来！",
  ["43:5f66"] = "！！！",
  ["43:5f6e"] = "任务失败了……\n要扣工资了……",
  ["43:5fa2"] = "下令让宝可梦干坏事，\n感觉超级爽！",
  ["43:5fd2"] = "……什么！",
  ["43:5fe2"] = "失败真让人不爽！\n可恶啊！\011这帮废物宝可梦！",
  ["43:601b"] = "卷帘门开了？怎么回事？\n是因为你小子吗？",
  ["43:6060"] = "被打败了。",
  ["43:606e"] = "什么！\n竟然突破了地下通道！？\011你到底是什么来头！",
  ["43:60b2"] = "这陌生小孩鬼鬼祟祟的……\n你是来干嘛的！？",
  ["43:60e1"] = "切，\n我太小看你了。",
  ["43:60ff"] = "咳咳咳……在这个地方\n可以随心所欲地发射电波。",
  ["43:6142"] = "有钥匙卡的插口！",
  ["43:615a"] = "{PLAYER}插入了\n钥匙卡！",
  ["43:6174"] = "3楼 …… 总务部",
  ["43:6182"] = "宝可梦音乐台\n由我靖史主持啦。",
  ["43:62b0"] = "我去遗迹里玩的时候，\n在收音机里面\011听到了奇怪的广播。",
  ["43:6306"] = "胡桃；为什么……\n会变成这样啊……？\012小喵喵，救救我——！",
  ["43:6349"] = "胡桃：啊——\n是你救了我！\012那就请你收下这个，\n算是我的心意！",
  ["43:638d"] = "胡桃：这个东西呢，\n好像很适合那些能使出\011一般属性招式的宝可梦！",
  ["43:63ca"] = "胡桃：要听我和大木博士\n的宝可梦讲座哦！",
  ["43:6404"] = "喵喵：……喵嗷。",
  ["43:6415"] = "你打算救台长？\n这可不太现实啊。\011因为我会在这打倒你！",
  ["43:646d"] = "我的天呐！",
  ["43:6480"] = "怎么回事！\n被打倒的居然是我！",
  ["43:64a2"] = "且慢！我被人称为\n“火箭队堡垒”！\011你别想再前进一步！",
  ["43:64ee"] = "堡垒沦陷……",
  ["43:6507"] = "你是个值得尊重的人，\n我想给你一句忠告：\012现在回头还来得及，\n望自珍重……",
  ["43:6562"] = "你问我宝可梦可不可爱？\n嗯，如果能在这击败你的\011宝可梦，那就能算可爱！",
  ["43:65b3"] = "够了！\n真是没用！",
  ["43:65cf"] = "我自己最可爱！\n宝可梦就算了吧！",
  ["43:6600"] = "太妙了！\012有了这座播音塔，\n我们的野心终于能实现了！",
  ["43:6641"] = "哎呀呀，\n正所谓“好事多磨”，\011伟大的计划总会遇上麻烦。",
  ["43:6669"] = "你以为你这样的小鬼\n真的能撼动火箭队吗？",
  ["43:669c"] = "4楼 …… 制作室",
  ["43:66ab"] = "4楼 …… 第2工作室",
  ["43:686a"] = "好、好心人！\n你是来救我的，对吗……",
  ["43:6889"] = "很期待这句台词吧！\n本大爷在给你演戏呢！\012为了顺利劫持电台，\n我特意假扮成真货！\012哈——哈哈，你一定\n很想知道台长在哪吧！\012我当然可以告诉你啊。\n如果你能赢我的话！",
  ["43:6965"] = "明，明白了……\n这就告诉你台长在哪。",
  ["43:6988"] = "真正的台长……\012被关在地下仓库里！\012知道地下仓库吗？\n在地下通道深之又深处。\011你大概到不了那里吧……",
  ["43:6a0d"] = "哎呀，小鬼！\n这可真是冤家路窄！\012在卡吉镇基地是我输了，\n但这次不会重蹈覆辙！",
  ["43:6a70"] = "……！\012明明全力应战了……\n怎么还是输了……",
  ["43:6aaa"] = "你叫{PLAYER}吧？\012像你这样的孩子\n应该无法理解\011我们的优越之处。\012真遗憾呢，\n我原本还很欣赏你的实力。",
  ["43:6b23"] = "了不起，居然能到这里。\012你一定是一位\n相当优秀的训练家。\012我们之所以劫持电台，\n是为了向全国宣布\011火箭队的复活。\012这样一来，\n在外修行的坂木老大\011肯定也会回到我们身边。\012这次一定要\n重现昔日的荣光……\011你别想妨碍我们！",
  ["43:6c45"] = "唔……\n坂木老大，请原谅我……",
  ["43:6c60"] = "……啊啊，这是怎么回事！\012我们的梦想\n如今全部破灭了！\012我还是不够格吗……\012没办法，\n只能效仿坂木老大了。\011我宣布：\011我们火箭队在此解散！\012再见了。",
  ["43:6d04"] = "台长：啊，{PLAYER}！\n真是太感谢你了。\012你的奋勇表现\n拯救了全国的宝可梦。\012这是我的一点心意，\n希望你不要嫌弃啊。",
  ["43:6d7e"] = "过去满金市也有一座塔。\n因为太过古老，成了危房。\011于是就改建成了播音塔。\012施工的时候，\n在那座塔的最上面\011发现了这个羽毛。\012据说啊，在很久以前\n满金市的上空也\011飞过了一只巨大的宝可梦。\012位于缘朱市的铃铛塔上\n好像会出现类似的宝可梦，\011这或许就是它掉落的物品。\012那么，\n我就先回台长室了。",
  ["43:6ee3"] = "过去满金市也有一座塔。\n因为太过古老，成了危房。\011于是就改建成了播音塔。\012施工的时候，\n在那座塔的最上面\011发现了这个羽毛。\012据说啊，在很久以前\n满金市的上空也\011飞过了一只巨大的宝可梦。\012湛蓝市附近的漩涡岛\n好像会出现类似的宝可梦，\011这或许就是它掉落的物品。\012那么，\n我就先回台长室了。",
  ["43:7049"] = "台长：{PLAYER}，\n我非常非常喜欢宝可梦。\011所以才想到通过广播\011来传播这份心意。\012如果节目让人喜闻乐见，\n那我就太高兴了。",
  ["43:70e3"] = "靖史：你爱听音乐吗？",
  ["43:7105"] = "5楼 …… 台长室",
  ["43:711e"] = "5楼 …… 第1工作室",
  ["44:409f"] = "嗯？\n那个是宝可梦图鉴吧！\011能给我看一下吗？\012唔……\n世上有很多宝可梦呢。\012等等！\012这个宝可梦是？\012和画在遗迹墙壁上的\n神秘花纹非常相似……\012如果花纹指某种宝可梦，\n那应该会有很多种类……\012好吧！\n我帮你升级一下图鉴吧！\011请跟我来！",
  ["44:42c3"] = "……嗯，\n这可真是个奇妙的地方。",
  ["44:42e6"] = "我最喜欢在遗迹里\n思考各种问题。",
  ["44:42fd"] = "神秘石板房间",
  ["44:431a"] = "阿露福遗迹\n对外开放参观",
  ["44:433a"] = "阿露福遗迹研究所\n帮你解答遗迹的一切谜题！",
  ["44:443c"] = "仿照古代宝可梦\n做出来的雕像。",
  ["44:4461"] = "该宝可梦闪耀着光芒\n飞过的地方会形成彩虹",
  ["44:4516"] = "欢迎来到遗迹小屋！\012这里有古代人\n绘制的宝可梦图画！\011你可以试着移动它们！\012右侧的文字是\n该宝可梦的说明。",
  ["44:45cb"] = "仿照古代宝可梦\n做出来的雕像。",
  ["44:45f0"] = "该宝可梦藏匿于海底时\n会用背上的眼睛观察四周",
  ["44:46bb"] = "仿照古代宝可梦\n做出来的雕像。",
  ["44:46e0"] = "该宝可梦弯曲着十只脚\n飘荡在在古代的大海中",
  ["44:4795"] = "仿照古代宝可梦\n做出来的雕像。",
  ["44:47ba"] = "该宝可梦飞翔在空中\n用锯齿般的獠牙袭击猎物",
  ["44:484a"] = "感受到了什么动静……",
  ["44:486d"] = "房间这么宽阔，\n里面却什么都没有。",
  ["44:489b"] = "这算是神圣感吗？\n这个地方可真神秘。",
  ["44:48e5"] = "说起年代久远的建筑，\n就会让人想到皇帝陵，\011比方说金字塔什么的……",
  ["44:4933"] = "仿照古代宝可梦\n做出来的雕像。",
  ["44:4b1e"] = "好了！\012宝可梦图鉴的\n改造工作完成了！\012我在选项中追加了\n未知图腾图鉴。\012它会按照捕捉的顺序\n自动进行记录哦。",
  ["44:4ba0"] = "{PLAYER}的\n宝可梦图鉴升级了！",
  ["44:4bb7"] = "捕捉到的未知图腾\n全都会被记录下来。\012你就帮我们确认一下\n究竟有多少种类吧！",
  ["44:4c05"] = "你捕捉到了\n所有种类的未知图腾吗？\011那太了不起了！！\012研究所里有台打印机，\n可以用它来打印\011未知图腾的图像。\012请你一定要试试看！",
  ["44:4c93"] = "这个遗迹，\n大约是1500年前建造的。\011但是我们还没弄清谁是\011建造者，以及建造的原因。",
  ["44:4ceb"] = "遗迹里的宝可梦\n总共有多少种类呢？",
  ["44:4d1e"] = "遗迹里真的\n出现宝可梦了吗！？\012这是大新闻啊！\n必须要赶紧调查一下！",
  ["44:4d71"] = "画在墙上的花纹就是\n解开遗迹之谜的关键！\012……我是这么觉得的。",
  ["44:4ded"] = "你遇到的宝可梦\n看起来非常像\011遗迹墙壁上的花纹呢。\012……唔。\012这可能意味着：\n遗迹里还有更多种类……",
  ["44:4e8b"] = "调查阿露福遗迹……\n已经有十年了。",
  ["44:4eae"] = "神秘的宝可梦\n名字叫做……未知图腾。\011总共发现了26个种类。",
  ["44:4ee3"] = "现在似乎用不了……",
  ["44:4f02"] = "可以打印\n未知图腾的图像！",
  ["44:4f5b"] = "放着好多复杂的书：\n《古代遗迹》……\011《古代文明之谜》……",
  ["44:505c"] = "你这是要去桧皮镇吗？\n让我的宝可梦测试一下\011你能否离开这个地方吧！",
  ["44:50b0"] = "哎呀哎呀……",
  ["44:50bd"] = "好——嘞！我决定了！\012在我的宝可梦变强之前，\n我要一直待在这里！",
  ["44:5106"] = "我走遍四方寻找宝可梦。\n你也是来找宝可梦的吗？\012那你就是我收集之路上的\n竞争对手了！",
  ["44:516c"] = "啊，我的小宝可梦……",
  ["44:5182"] = "一到周五，\n这个洞窟的深处就会\011传出宝可梦的叫声。",
  ["44:51c4"] = "天哪！震惊！震撼！\n居然在这种地方碰到人！",
  ["44:51ff"] = "天哪！震惊！震撼！\n居然能碰到这么强的人！",
  ["44:521a"] = "被人忽悠了，一不小心\n就买了呆呆兽的尾巴。\011总觉得呆呆兽很可怜呢。",
  ["44:5266"] = "超音蝠的超音波\n让我变得一片混乱，\011我现在超级火大！",
  ["44:52b1"] = "燃 烧 殆 尽 ！",
  ["44:52c0"] = "每逢周末，\n洞穴的深处就会\011传来奇异的叫声。",
  ["44:5300"] = "够明亮就不怕无底洞，\n够强大就不怕宝可梦。",
  ["44:5345"] = "闪——光！！",
  ["44:534d"] = "我的宝可梦\n用火焰照亮了四周，\011所以这个洞穴如此明亮！",
  ["44:546e"] = "啊呀，好久没见过活人了，\n那就赶紧派出宝可梦吧！",
  ["44:54bb"] = "唔……",
  ["44:54c4"] = "我迷路好久了……\012虽然出不去也无所谓，\n但是肚子会饿啊。",
  ["44:5510"] = "哦哦，久违的来客！",
  ["44:552e"] = "哇哈哈哈——\n充满活力的小朋友！",
  ["44:554c"] = "我在这里过日子！\n你也能住在这里哦！\011空地要多少有多少。",
  ["44:559b"] = "你哪位？不要来打扰只有\n我与宝可梦的世界啊！",
  ["44:55c4"] = "呜……\n你给我滚！",
  ["44:55d2"] = "只有我和宝可梦……\n啊啊，这是多么幸福啊。",
  ["44:5601"] = "为了调查宝可梦，\n就连这种地方我也愿意来。\012让我用实战来告诉你\n我的调查结果吧！",
  ["44:5668"] = "反而受到指教了……",
  ["44:5681"] = "我也该归纳调查结果\n并将其发表出来了。\012说不定我可以变得和\n空木博士一样出名。",
  ["44:57bf"] = "这个世上的人\n大致能分成2种：\011有品位的和没品位的。\012你是哪种呢？",
  ["44:5826"] = "光彩夺目！",
  ["44:5841"] = "你的宝可梦品味，\n有看点又很养眼呢！\011你一定能变得更强！",
  ["44:5895"] = "我正好在这里特训，\n你愿意陪我玩玩吗？",
  ["44:58b8"] = "啊啊，真是的！\n你也太强了吧！",
  ["44:58d9"] = "在变强之前，\n我要默默地进行特训！",
  ["44:5907"] = "只要有喜欢的宝可梦，\n刀山火海在所不辞。\011这就是所谓的训练家哦。",
  ["44:5958"] = "比起宝可梦对战，我可能\n更喜欢照料宝可梦吧。",
  ["44:597c"] = "有种宝可梦，\n每周只会来水边一次。\012我一直都很想\n见它一面呢……",
  ["44:5b06"] = "钢铁：哟，{PLAYER}！\012上面本来有人放风，\n我大声批评两句\011居然就把他吓跑了……\012我刚刚从井口掉下来，\n折了腰，动不了了。\012可恶……要是我没事，\n一定能用宝可梦\011好好教训一下他们……\012算了，{PLAYER}，\n你一定要给他们展示一下\011训练家之魂！",
  ["44:5c1d"] = "钢铁：{PLAYER}，\n干得漂亮！\011火箭队这帮人全都跑了。\012我的腰也没事了，\n一起回去吧。",
  ["44:5c78"] = "可恶！本来在上面望风，\n不知道从哪来了个老头。\012他突然大叫一声，\n吓得我掉进井里了。\012哼，我就把你揍一顿，\n以解心头之恨吧！",
  ["44:5d1f"] = "啊——可恶——\n完全不行嘛！",
  ["44:5d3b"] = "没错，我们确实\n把呆呆兽的尾巴\011割下来拿去卖了。\012拼死拼活都是为了赚钱！\n只要有钱赚，\011火箭队啥都干！",
  ["44:5dde"] = "什么？\012妨碍我们工作的话，\n我可不会轻饶你的！",
  ["44:5e23"] = "切，臭小子，\n真有你的！\011但下次不会这么走运了！",
  ["44:5e54"] = "我们火箭队\n的确在三年前解散了。\012但还是能像这样\n继续进行地下活动。\012接下来会发生什么呢，\n你就拭目以待吧！",
  ["44:5ee5"] = "什么，叫我别割尾巴了？\012让我住手就住手，\n火箭队不要面子的吗！",
  ["44:5f37"] = "太、太强了……",
  ["44:5f4a"] = "竟然卖呆呆兽的尾巴……\n怎么能这样赚钱啊！\012太为难我们这些手下了……",
  ["44:5f9b"] = "什么，叫我别割尾巴了？\012那你就试试看\n能不能击败我们全员吧！",
  ["44:5fd3"] = "哎呀，真可恨！",
  ["44:5fe5"] = "呆呆兽的尾巴\n不是马上就能长出来吗，\011凭什么不能拿去卖？",
  ["44:6023"] = "是呆呆兽……\n尾巴被割掉了……\012哎呀，这只带着信件呢。\n要读读看吗？",
  ["44:6061"] = "{PLAYER}\n阅读了信件！\012你要和呆呆兽还有\n爷爷好好地看家哦 爸爸留",
  ["44:60b9"] = "是呆呆兽……\n尾巴被割掉了……",
  ["44:6182"] = "我一直在这里\n想看到呆呆兽\011进化的那个瞬间。\012根据观察，我发现：\n携带王者之证的呆呆兽\011不知为什么，\011特别容易大舌贝咬上。\012对了，我也分给你\n一个王者之证吧！",
  ["44:624a"] = "我像呆呆兽那样，\n悠哉地等着进化的瞬间。",
  ["44:62c5"] = "这座灯塔\n也是修行的地方。\012因为训练家非常多，\n想往上爬还挺费力的。",
  ["44:631a"] = "从古至今，浅葱市一直有\n宝可梦在夜间照亮大海。\012为了纪念它们，\n人们就建造了这座灯塔。",
  ["44:646b"] = "大海男儿\n该出手时就出手！",
  ["44:64a1"] = "噢！\n是我输了！",
  ["44:64af"] = "你的实力，我很看好！\n要一起去外国吗？",
  ["44:64e9"] = "哦，你是……？\n这里可不是给你玩的。",
  ["44:650c"] = "哦哦，你是认真的！",
  ["44:652f"] = "顶层有一只宝可梦\n总是会发光。\012听说它现在生病了，\n而且普通的伤药\011无法治好。",
  ["44:6625"] = "你是来干嘛的？\n探望？闲逛？\011闲逛的话还是回去吧！",
  ["44:666e"] = "不是来玩啊……\n真的是来探望呢。",
  ["44:6689"] = "顶层要怎么走啊？\n本来想去探望一下的，\011却找不到路，头疼。",
  ["44:66dd"] = "海上男儿既强大\n又不失温柔。\011你又是哪种人呢？",
  ["44:670f"] = "你的战斗方式\n温柔而强大呢。",
  ["44:672e"] = "只要我回到浅葱市，\n必定会去一趟道馆。\012馆主使用的宝可梦属性\n似乎和以前不太一样……",
  ["44:679e"] = "我周游世界，\n以此来锻炼宝可梦。\011来和我对战吧！",
  ["44:67e1"] = "哎……\n修行还不够啊……",
  ["44:6801"] = "以前的阿蜜用的都是\n大岩蛇一类的宝可梦，\011那时还是擅长岩石属性的\011宝可梦训练家。",
  ["44:68bc"] = "阿蜜……\n很担心宝可梦呢……\011仿佛要永远地失去笑容了。",
  ["44:690f"] = "我也要忘记怎么笑了……",
  ["44:692e"] = "要……药！\n我记得听别人说过，\011湛蓝市有家妙手药店！",
  ["44:696f"] = "阿蜜毕竟还是\n这个城市的道馆馆主……\012我一定要把她带回去！\n谁也别想妨碍我！",
  ["44:69d5"] = "啊啊，我的宝可梦！",
  ["44:69e6"] = "宝可梦受伤了的话，\n确实很让人担心呢。\012我会在这里祈祷，\n希望阿蜜尽快重返道馆。",
  ["44:6aef"] = "本来是想和阿蜜对战的，\n但现在好像不是时候。\011那就让你来代替她吧！",
  ["44:6b3a"] = "哦、哦！\n强到离谱！",
  ["44:6b5b"] = "馆主不仅要有强大的实力，\n还需要一颗温柔的心。",
  ["44:6bb0"] = "天空近在咫尺，\n我的鸟宝可梦状态绝佳！",
  ["44:6beb"] = "啊呀呀，\n状态突然就没了……",
  ["44:6bff"] = "我的宝可梦在湛蓝市\n学会了叫飞翔的招式。\012算了，既然输了，\n那就干脆飞越大海吧。",
  ["44:6dbd"] = "阿蜜：……这只宝可梦\n一直为我们照亮大海。\012……可是，\n有一天它突然没了精神，\011变得奄奄一息……\012……有传闻说，\n在大海彼岸的湛蓝市\011有一家神奇的药店……\012可是我现在不能\n放着光儿不管啊……",
  ["44:6ea0"] = "我有个不情之请……\n能不能请你代替我\011去把药带回来呢？",
  ["44:6ed5"] = "阿蜜：……那个药\n真的能治好光儿吗？",
  ["44:6eff"] = "{PLAYER}把秘传之药\n交给了阿蜜。",
  ["44:6f26"] = "阿蜜：……那、那个，\n希望你别见怪。\012因为光儿……\n不喜欢别人给的东西，\011只有我是例外。",
  ["44:6f80"] = "阿蜜：…… …… ……\012光儿，感觉怎么样？",
  ["44:6fa8"] = "阿蜜：……啊，太好了！\n真是太好了！\012真是非常感谢，\n这都多亏了你。\012那么……\n我也该回道馆了。",
  ["44:701b"] = "阿蜜：……是吗。",
  ["44:702d"] = "……光儿，撑住啊！",
  ["44:703f"] = "光儿：…… …… ……\n……巴……巴鲁。",
  ["44:7055"] = "感觉它有些呼吸困难。",
  ["44:7079"] = "光儿：帕鲁！帕鲁鲁！",
  ["45:4126"] = "通向地下的楼梯\n暴露了……",
  ["45:414f"] = "嘿嘿嘿！\n实验大成功！\012虽然鲤鱼王没人买，\n但暴鲤龙就不一样了！",
  ["45:41bc"] = "呜呜……\012那家伙的龙宝可梦……\n太强了吧……",
  ["45:41e5"] = "阿渡：快龙，破坏光线！",
  ["45:4204"] = "好慢啊，{PLAYER}！\012奇怪的电波\n果然是从这里发出的。",
  ["45:4259"] = "楼梯就在这里！",
  ["45:4275"] = "阿渡：{PLAYER}！\n我们分头去找！\011我先走一步了！",
  ["45:47cd"] = "哎呀！\n发现入侵者！",
  ["45:47e3"] = "见鬼，\n居然被反杀了……",
  ["45:47f4"] = "下一个换我！\n你逃不掉的！",
  ["45:4814"] = "宝可梦雕像上有监控。\012只要隐秘开关没被关掉，\n我们就会不断地来找你！",
  ["45:4876"] = "这里原本是忍者基地。\012所以设置了很多机关\n来阻碍入侵者！",
  ["45:48c6"] = "原来如此呢……",
  ["45:48d1"] = "……好吧，我能告诉你\n这个基地的秘密之一。\012前面那个是传送板！\n一不小心碰到的话\011就会被送回入口！",
  ["45:4972"] = "哦，还要继续前进吗？\n前面埋了“地雷”，\011一踩到就会爆炸！",
  ["45:49cd"] = "轰——隆！！",
  ["45:49d6"] = "连我都记不住\n到底哪里会爆炸。\011你也只能大胆往前走了。",
  ["45:4a37"] = "猫老大的宝可梦雕像……\n眼睛好像在发光。",
  ["45:4a68"] = "发现隐秘开关！\n按下去吧！……我按！",
  ["45:4a8b"] = "电源切断了……",
  ["45:4f65"] = "到此为止了！",
  ["45:4f7b"] = "居然被小屁孩小看，\n这让我们火箭队\011颜面何存！\012不管你有多强，\n也不能同时对付\011我们两个人吧？\012不好意思啊，\n你还是死心吧！",
  ["45:5044"] = "别那么说嘛！\n总得有人陪我玩两把吧？",
  ["45:5075"] = "居然还有同伴！\n真是让人讨厌呢。\012现在由我暂替坂木老大。\n你就好好体会一下\012杵逆火箭队\n会有什么下场吧！",
  ["45:5114"] = "哎呀，很强呢。\012真是可惜，\n你要是加入了火箭队\011起码也能当个干部吧。",
  ["45:517e"] = "……这个基地完蛋了。\012不过没关系。\n毕竟电波实验\011已经取得了成果。\011这个基地也无所谓了。\012我们的目标\n可不是仅此而已哦。\012终有一天你会明白\n火箭队的可怕之处。\012好好等着吧……\n哼哼哼……",
  ["45:5290"] = "阿渡：呼，这样一来\n我们已经打败了基地里\011所有的火箭队员。\012刚刚和我交战的少年，\n让人有些在意啊……",
  ["45:5306"] = "不好意思，{PLAYER}。\n我看你表现得这么出色，\011就一直没有出手帮忙。\012接下来……\n关闭奇怪的电波就行了吧。",
  ["45:5387"] = "是这个装置吗……\n找不到开关啊。\012没办法了，\n只能打昏顽皮雷弹了。\012那样一来，奇怪的电波\n也会停止发射吧。\012毕竟不是宝可梦的错，\n我也于心不忍呢。\012{PLAYER}，\n兵分两路吧。",
  ["45:54a2"] = "阿渡：这边就交给我吧。",
  ["45:54c1"] = "阿渡：奇怪的电波\n总算停下来了。\012这下愤怒之湖\n也会恢复正常吧。\011这多亏了你。\012我要代替宝可梦\n向你道谢！\012对了！\n这个给你吧！\012这是刚刚在这里找到的，\n我拿着也没什么用。",
  ["45:55b0"] = "里面是潮旋！\012教给宝可梦之后\n就能穿越汹涌的漩涡！\012不过你要知道，\n持有卡吉道馆的徽章\011才能使用这个招式。",
  ["45:564c"] = "{PLAYER}！\012通往宝可梦大师的道路\n幽深而险峻……\011你还愿意继续前行吗？\012…… …… …… ……\n是吗？\011确实如此。\012随随便便就放弃的话，\n还谈何梦想？\012那么，下次再会！",
  ["45:574f"] = "阿渡：你没事吧？\012你的宝可梦\n伤得很重啊。\011我的药也分你一些。",
  ["45:57af"] = "阿渡：来，{PLAYER}，\n为了宝可梦一起加油吧！",
  ["45:57da"] = "门打不开？\012那是当然的。\n开门所需要的密码，\011只有火箭队成员知道。",
  ["45:5831"] = "输、输了？",
  ["45:5840"] = "我只是给他们当手下的。\n密码也没有告诉过我，\011真遗憾呐。",
  ["45:5882"] = "呜，又是小孩子啊……\n虽然我不是很想动手，\011但是必须要扫除障碍！",
  ["45:58c1"] = "呜，还是输了……",
  ["45:58d2"] = "呜，上一次执行\n偷宝可梦任务的时候，\011被一个留了红色长发、\011目光凶狠的小孩子\011打得屁滚尿流……",
  ["45:5968"] = "跑来跑去的真碍眼！",
  ["45:5981"] = "咕噜咕噜……",
  ["45:5989"] = "打开那个门的密码\n只有老大才知道。\012你问老大在哪里？\n谁知道，自己找去吧。",
  ["45:59f1"] = "门紧闭着……\012输入1组密码\n才能把门打开。",
  ["45:5a23"] = "门紧闭着……\012{PLAYER}\n输入了密码。\012门打开了！",
  ["45:5a5f"] = "产生怪异电波的装置\n正在嗡嗡地运作着。",
  ["45:5abb"] = "产生怪异电波的装置\n似乎停下来了。",
  ["45:5e2f"] = "阿渡：进老大的房间之前，\n好像需要在门上\011输入2组密码。\012而这2组密码\n似乎只有个别\011火箭队员才知道。\012这是边上那个火箭队员\n刚刚跟我坦白的。\012{PLAYER}！靠你了！\n努力去寻找密码吧！",
  ["45:5eeb"] = "呜呜呜……\n那个斗篷男太强了……",
  ["45:5f1d"] = "…… …… ……\012我跟你说过的吧？\n火箭队应该由我击溃！\012……先不说这个。\n那个披斗篷的龙使者\011到底是什么来头？\012我的宝可梦\n根本不是他的对手……\012输了倒也无所谓。\n只要我能获得\011更加强大的宝可梦，\011那种人也不在话下！\012说起来……\n他的言论真是令人作呕！\012说什么“你对宝可梦的\n爱与信赖还不够”……\012赢了我的居然是那种\n满嘴胡话的人！生气！\012……哼！\n谁要当你的对手啊！",
  ["45:60b6"] = "谁啊，你是？\n这里是我们的老大——\011坂木老大的房间。\012坂木老大在3年前\n发表了解散宣言之后，\011一直都在进行修行……\012但是，我们相信\n他总有一天会回来的，\011所以一直守在这里。\012不管你是什么人，\n都不许在这里撒野！",
  ["45:61c7"] = "咕呜呜……\n完全抵挡不了。\012坂木老大，\n请原谅我……",
  ["45:61fe"] = "不行，\n现在不应该哀叹失败，\011而是要去通知同伴们……",
  ["45:623b"] = "黑暗鸦：密码是……\012坂木老大万岁。",
  ["45:6265"] = "问我知不知道密码？\n说不定知道呢。\012可是呢，我可不会\n把它透露给一些弱者！",
  ["45:62a7"] = "我知道了，\n告诉你总行了吧。",
  ["45:62c7"] = "老大门口密码是……\012呆呆兽的尾巴。\012但是，密码有2组。\n只有1组什么也干不了！",
  ["45:6327"] = "嘻嘻嘻！\012你以为你能打倒我？\n真是好胆量啊。\012我喜欢你！\n如果你赢了，\011我就告诉你\011老大门口的密码！",
  ["45:63cd"] = "嘻嘻嘻！\n干得不错嘛！",
  ["45:63ed"] = "嘻嘻嘻！\012就告诉你\n老大门口的密码吧。\011应该是“拉达的尾巴”。",
  ["45:6443"] = "我以前在西尔佛做实验。\n但是现在呢，\011我在火箭队做实验。\012小孩不乖是要打屁股的。",
  ["45:64b8"] = "不可能……\n作战失败了。",
  ["45:64d8"] = "使宝可梦发狂的电波……\012实验已经取得成功，\n这下就能出人头地了！\011输了就输了吧。",
  ["45:6562"] = "就算在实验中折磨宝可梦，\n又关我什么事呢？",
  ["45:6595"] = "我擅长的是思考，\n而不是战斗。",
  ["45:65c0"] = "将奇怪的电波升级后\n再散布到全国……\012光是想象就兴奋不已。",
  ["45:6626"] = "门紧闭着……\012输入2组密码\n才能把门打开。",
  ["45:6659"] = "门紧闭着……\012{PLAYER}输入了\n2组密码。\012门打开了！",
  ["45:6a44"] = "怎么办！\n师傅会生气的！\012大葱鸭不知道跑哪去了！\n平时制作木炭的木料\011都是靠大葱鸭砍来的……\012栎树林幽深阴暗，\n我一个人怕得不敢动啊。",
  ["45:6b01"] = "非常谢谢你！\012因为我没有徽章，\n所以师傅的宝可梦\011不愿意听我的话。",
  ["45:6b57"] = "遇见了走失的宝可梦！",
  ["45:6b6e"] = "大葱鸭：呱——",
  ["45:6b81"] = "啊！大葱鸭！\n是你帮我们找回来的吗？\012如果没有它帮忙砍树，\n我们就没法制炭了！\012多谢你啊！\n必须得送点谢礼才行……\012对了！就把这个拿去吧！",
  ["45:6c29"] = "里面是秘传的居合斩！！\n让宝可梦记住的话，\011就可以砍掉小树了！\012但是要有桧皮道馆的徽章\n才能使用哦。",
  ["45:6ca8"] = "要去我那里修行吗？\n花个10年就能出师哦！",
  ["45:6d03"] = "你问我在干嘛？\012我在用头锤摇树啊。\n超级有趣的，\011你也试试看吧！",
  ["45:6d55"] = "用头锤摇树的时候，\n偶尔也会掉下来\011睡着的宝可梦哦。",
  ["45:6d97"] = "这片栎树林\n草木葱茏、枝繁叶茂，\011天空都被遮住了。\012周围比较黑暗，\n务必当心脚边的遗失物。",
  ["45:6e11"] = "栎树林的祠堂……\n供奉着森林之神。",
  ["46:42dc"] = "本来想用宝可梦来作弊。\n不巧被人发现了，\011游戏城就把我赶出来了……",
  ["46:4329"] = "……嘟嘟囔囔。",
  ["46:4334"] = "果然还是要\n光明正大地做人吗……",
  ["46:4362"] = "你有没有研究过\n宝可梦的属性相克？\012如果合理利用属性相克，\n宝可梦就会变得更强哦！",
  ["46:43cb"] = "啊痛痛痛！",
  ["46:43d8"] = "虽然我很懂属性相克，\n但我只使用\011同一种属性的宝可梦……",
  ["46:441a"] = "我的宝可梦刚剪了头！\n就让你看看它的实力吧！",
  ["46:4458"] = "啊呀——！！",
  ["46:4462"] = "给宝可梦剪了头发之后，\n我们的关系好像更亲密了。",
  ["46:449b"] = "我感觉……\n你带着稀有的宝可梦呢。\011听话，让我看看。",
  ["46:44d7"] = "哇啊——！\n输了！好气啊！",
  ["46:44f9"] = "你在收集宝可梦图鉴？\n我这里有宝贵的情报哦！\01233号道路有个登山男，\n名字叫做勤快。\012他一看到稀有的宝可梦，\n就会打电话通知你哦！",
  ["46:457a"] = "锁得紧紧的！",
  ["46:458d"] = "门开着。",
  ["46:45a0"] = "使用了地下钥匙！\n门打开了！",
  ["46:45c3"] = "欢迎光临！\n这里是宝可梦美发沙龙！\012我是美发兄弟中的哥哥，\n特点是手法稳健，\011只需¥500就能\011让您的宝可梦变漂亮！\012怎么样？\n想变漂亮吗？",
  ["46:4664"] = "要让哪只宝可梦变美？",
  ["46:4682"] = "好——！\n我要把它变得美美的！",
  ["46:46a2"] = "好了，结束了！",
  ["46:46b4"] = "是吗？\n太遗憾了。",
  ["46:46d3"] = "看来你的钱不够呢。",
  ["46:46f5"] = "1天只剪1次。\n今天的营业结束了！",
  ["46:4726"] = "欢迎来到宝可梦美发沙龙！\012我是\n美发兄弟中的弟弟！\012特点是物美价廉！\n只需¥300就能\011让您的宝可梦变漂亮哟！\012怎么样？\n想交给我吗？",
  ["46:47bb"] = "要让哪只宝可梦变帅？",
  ["46:47d8"] = "好——！\n我要把它变得帅帅的！",
  ["46:47f4"] = "好，完成了！",
  ["46:480c"] = "是吗？\n真遗憾。",
  ["46:4825"] = "看来你的钱不够呢。",
  ["46:4845"] = "1天只剪1次。\n抱歉，今天打烊了！",
  ["46:4889"] = "{STRBUF}\n有点高兴。",
  ["46:48a6"] = "{STRBUF}\n很高兴！",
  ["46:48b8"] = "{STRBUF}\n非常高兴！",
  ["46:48ce"] = "今天不开张。",
  ["46:48e4"] = "前方禁止入内！",
  ["46:4e67"] = "慢着！\012我刚才凑巧看见你，\n所以就跟在你的后面。\012你怎么每次都跑出来\n妨碍我击溃火箭队！\012……我想起来了，\n上次我好像\011输给了你来着。\012那回只是侥幸罢了，\n出来混总是要还的！",
  ["46:4f27"] = "……为什么！\n为什么我会输！\012我手上有最强的宝可梦，\n对战中也没有放水啊……\012到底是为什么？",
  ["46:4f8c"] = "……可恶，我不明白！\012难道真像那个阿渡所说，\n因为我缺乏对宝可梦的\012爱意……\012信赖……\012所以我才赢不了？\012不知道到底是怎么回事！\012但是，我不能止步于此。\012怎么能就这样放弃\n成为最强的梦想……",
  ["46:50cc"] = "这就是我的实力。\012我要一鼓作气击溃火箭队！\n然后再去打败\011那个叫阿渡的家伙！",
  ["46:5140"] = "呼……有人在地下\n向我发起宝可梦对战，\011害我吃了顿苦头。\012你也要小心为妙。",
  ["46:519a"] = "在地下有很多店铺……\012但是训练家也不少，\n所以我不太敢靠近……",
  ["46:51f5"] = "有一个卷帘门打开，\n就会有另一个卷帘门关上。\011你能到达目的地吗？",
  ["46:5239"] = "可恶！\n我的战斗太犹豫了吗。",
  ["46:525a"] = "……我也迷路了。\012本来应该先按\n最里面的开关才对。",
  ["46:52a2"] = "哇哈哈！\012被卷帘门的机关\n搞糊涂了吧！\012如果你能战胜本大爷，\n我就给你一个好消息。",
  ["46:52ff"] = "呜呜……\n被打败了。",
  ["46:5311"] = "好吧，说好的提示。\012如果以不同的顺序\n按下卷帘门开关，\011连通的区域也会发生变化。",
  ["46:5378"] = "把你的宝贝\n乖乖交出来！",
  ["46:5391"] = "一团浆糊！",
  ["46:5399"] = "偷了别人的东西\n再拿去卖掉……\011这是很坏的做法。",
  ["46:53c5"] = "这里是烂尾建筑，\n没建好就被弃置了……\011说不定能捡到什么宝贝。",
  ["46:5416"] = "真强……",
  ["46:5425"] = "要去地下仓库吗？\012我还是劝你放弃吧，\n那里什么都没有。",
  ["46:547c"] = "管他是迷途小鬼还是羔羊，\n敢在我面前出现的家伙，\011我全部都要打倒！",
  ["46:54c6"] = "切！\n装什么酷啊！",
  ["46:54e9"] = "居然敢对反抗火箭队，\n真是不知天高地厚啊……",
  ["46:551e"] = "上面写着“开关1”",
  ["46:5535"] = "迷路了吗？似乎不是呢。\012你的眼神里充满了无畏。\n那就让大姐姐我来教教你\011什么是真正的恐怖吧！",
  ["46:55a0"] = "啊，怎么可能！",
  ["46:55b0"] = "够了！\n爱上哪上哪去！\011最好赶紧迷路！",
  ["46:55e1"] = "已经关上了，\n要打开吗？",
  ["46:55f7"] = "已经打开了，\n要关上吗？",
  ["46:560d"] = "上面写着“开关2”",
  ["46:5624"] = "上面写着“开关3”",
  ["46:563b"] = "上面写着\n“紧急开关”。",
  ["46:5795"] = "哎！别妨碍我工作！\n没人在旁边才能工作，\011这是我们的基本原则！",
  ["46:57f7"] = "要是被人看见了，\n就没精力去搬运货物了！\011一边呆着去！",
  ["46:5840"] = "哟吼，哟吼。\012掉在地上的净是些破烂，\n想要的话随便拿！",
  ["46:5886"] = "豪力：豪、豪嗷嗷！",
  ["46:59b3"] = "居然能来到这里……\012那就没办法了，\n就让我来收拾你吧！",
  ["46:59fd"] = "被收拾的人是我！",
  ["46:5a11"] = "只要坂木老大还没回来，\n我们就会一直\011守护着火箭队。\012上天入地，在所不惜！",
  ["46:5a70"] = "见鬼！\n别想再往前一步！\012就算对面是小孩子，\n我也不会手下留情的！",
  ["46:5abf"] = "框当！！",
  ["46:5aca"] = "我输掉了……\n坂木老大，对不起……",
  ["46:5af0"] = "嘻嘻嘻！\012我还记得你哦。\n在基地承蒙关照了。",
  ["46:5b34"] = "嘻嘻嘻！\n又是这样吗。",
  ["46:5b57"] = "嘻嘻嘻！有点意思！\n我会记住你的。",
  ["46:5b8f"] = "台长：……你、你是？\n啊，你是来救我的吗？\011真的是非常感谢啊。\012对、对了！\n播音塔现在怎么样了？\012什么？到处都有火箭队！\n明白了！\011这个钥匙卡交给你了。",
  ["46:5c24"] = "台长：只要有这个，\n就能打开3楼的卷帘门。",
  ["46:5c56"] = "拜托了！万一广播被劫持，\n后果不堪设想！\012说不定他们会通过广播\n释放奇怪的电波，\011以此来操纵宝可梦。\012我现在只能指望你了……\n请你拯救播音塔！\011拯救全国的宝可梦！",
  ["46:5f3d"] = "你好！\n我就是空手道大王！\012我正独自待在\n漆黑的洞穴中修行！\012喂！\n你！\011过两招吧！\011嘿呀——！",
  ["46:5f99"] = "哇哦哦！\n哒——！我输了啊！",
  ["46:5fb0"] = "遗……遗憾！\n修为不足吗……！\012输了就是输了！\n就算不甘心也得承认！\012喂！作为战胜我的证明，\n把我珍贵的\011格斗宝可梦交给你了！",
  ["46:6045"] = "{PLAYER}从空手道大王\n那里得到了无畏小子！",
  ["46:605a"] = "无畏小子的属性是格斗！\012培育得当的话，它就能\n进化成强大的宝可梦。\012你也要加油！\n我要继续修行了！\011嘿呀！",
  ["46:60cf"] = "嘿呀！\n已满了就拿不下了！",
  ["46:61cc"] = "石块掉下去了！",
  ["46:6267"] = "深深陷在冰面里，\n根本就推不动……",
  ["47:41c8"] = "奇——亚斯！！",
  ["47:438b"] = "呜哇！吓了一跳！\012因为我戴着黑色眼镜\n完全没注意到你！\012你问我来这里做什么？\012哎呀，怎么说呢……\n我把黑色眼镜给你，\011你就别管我了。",
  ["47:4458"] = "黑色眼镜……\n让宝可梦携带后，能提升\011恶属性招式的攻击力。",
  ["47:459c"] = "小椿:明白了！\n我认可你的实力。\012请收下这枚徽章吧。",
  ["47:45e1"] = "{PLAYER}从小椿那里\n得到了升龙徽章！",
  ["47:45fa"] = "拥有升龙徽章以后，\n无论怎样的瀑布\011都能攀上去了……\012以及，所有的宝可梦\n都会承认你这个训练家，\011会服从一切命令……\012另外，请收下\n这个招式学习器吧。",
  ["47:46d6"] = "这里面是——\n龙息。\012……不是那个最辣辣椒！\n如果你不需要，\011我也不会强迫你的。",
  ["47:4754"] = "你好像集齐所有徽章了。\012那就前往石英高原的\n宝可梦联盟吧。\012知道该往哪走吗？\n如果从这里出发的话，\011那就要先经过若叶镇。\012然后就用冲浪\n朝着东方一路前进就行。\011不过这段路并不平坦。\012如果你输给宝可梦联盟，\n我饶不了你！\012要不然，我这个\n手下败将情何以堪！",
  ["47:4881"] = "龙之祠堂\012里面供奉着曾经\n住在龙穴的龙宝可梦。",
  ["47:48d6"] = "…… …… ……\n原来是{PLAYER}啊……\012……不好意思，\n我没打算当你的对手。\012我手上这些宝可梦\n现在还赢不了你，\011我才不会自讨没趣。\012要不然，\n我永远也无法成为\011最强的训练家……",
  ["47:4980"] = "…… …… ……\012呼……\n别碍事！",
  ["47:49a6"] = "{PLAYER}找到了\n{STRBUF}！",
  ["47:49b8"] = "但是，{PLAYER}\n已经拿不下更多道具了！",
  ["48:4101"] = "哇，好酷的宝可装置！\n是你妈妈买给你的吗？",
  ["48:413e"] = "啊！{PLAYER}！",
  ["48:4148"] = "你一个人要上哪去啊！？",
  ["48:4168"] = "真是的！没有宝可梦同行\n就走进道路是很危险的！\012去隔壁城镇的这条路\n到处都是会跳出\011野生宝可梦的草丛哦！",
  ["48:41ce"] = "哇！好可爱的宝可梦！\n我也好想要啊！",
  ["48:41fc"] = "哎呀，{PLAYER}，\n你又要出门吗？\012要踏上旅途的话，\n得先跟你妈妈讲一句哦！",
  ["48:4240"] = "只要有宝可装置，\n随时都能给妈妈打电话，\012让她听一听\n你那充满活力的声音。",
  ["48:427e"] = "哟，{PLAYER}！\012我听说空木博士\n发现了新的宝可梦呢。",
  ["48:42b0"] = "…… …… ……\012这里就是著名的\n空木博士研究所……",
  ["48:42d7"] = "……干嘛？\n别用那种眼神盯着别人！",
  ["48:42f2"] = "这里是若叶镇。\n吹起开始之风的城镇。",
  ["48:4332"] = "这里是{PLAYER}的家。",
  ["48:433c"] = "空木宝可梦研究所。",
  ["48:434a"] = "这里是空木的家。",
  ["48:45ae"] = "你还是新人训练家吧？\n被我说中了吧！\012很好很好，\n靡不有初嘛。\012要不要让我\n指点一下啊？",
  ["48:463a"] = "好，我给你带路！",
  ["48:4650"] = "这里是宝可梦中心！\n把受伤的宝可梦寄放在这，\011一瞬间就能治好！\012接下来你应该会\n经常来这里，\011一定要好好记住哦！",
  ["48:46cf"] = "这里是友好商店！\n捕捉宝可梦的球等等物品\011都要在这里购买哦！",
  ["48:4724"] = "这前面是30号道路！\n大家都在磨练着\011自己引以为豪的宝可梦！",
  ["48:4772"] = "这里如你所见，是一片海。\012有的宝可梦\n只会出现在水中！",
  ["48:47b7"] = "这里是……\012我的家！\n感谢你愿意陪我。\012这个是谢礼哦！",
  ["48:4803"] = "{PLAYER}可以用\n宝可装置查看城镇地图了！",
  ["48:481c"] = "给宝可装置\n装上各种好用的扩展卡\011它就会变得越来越好用！\012那么，加油吧！",
  ["48:486a"] = "这样啊……\n我还挺期待的……\011你心情好的时候尽管来吧。",
  ["48:48ad"] = "…… …… ……\012你在研究所里\n得到了宝可梦啊。\011给你这么弱的人真浪费。\012…… …… ……\012什么啊，\n你听不懂我在说什么吗？\012…… 那就没办法了。\n我也拿到了不错的宝可梦，\011我来好好教教你吧！",
  ["48:4942"] = "…… 哼！\n赢了很开心吗？",
  ["48:4961"] = "…… …… ……\012我的名字是???。\012将会成为世界最强\n宝可梦训练家的男人！",
  ["48:49a5"] = "…… 哼！\n真是浪费时间。",
  ["48:49c7"] = "…… …… ……\012我的名字是???。\012将会成为世界最强\n宝可梦训练家的男人！",
  ["48:4a0b"] = "你有没有向宝可梦中心\n旁边的那个爷爷问话？\012他可以为你身上的\n宝可装置增加\011城都地区地图功能哦！",
  ["48:4a63"] = "有宝可梦同行的话，\n去哪里都很开心呢。",
  ["48:4a91"] = "宝可梦爷爷的家\n还要再往前走一段距离。",
  ["48:4abc"] = "我和站在路边的训练家\n勇敢地大战了一场……\012但是我的宝可梦打输了，\n都累得精疲力尽……\011必须要去宝可梦中心了……",
  ["48:4b21"] = "之前钓上来的宝可梦\n身上携带者道具哦。\012好像叫神秘水滴什么的。\n我只要钓宝可梦就够了，\011你要的话就给你吧。",
  ["48:4b7c"] = "那么，我要继续垂钓了。",
  ["48:4b9b"] = "这里是吉花市。\n可爱花朵香气飘逸的城市。",
  ["48:4bd0"] = "这里是向导爷爷的家",
  ["48:4d29"] = "嘿～你是宝可梦训练家吧。\n打赢道馆馆～主～了没有？",
  ["48:4d62"] = "那可太～了不起了～！",
  ["48:4d81"] = "这～样吗～？\n那就要好～好～学习了。\011跟上我哦～",
  ["48:4daf"] = "我是这里的老～师！\012你就在这里\n好～好～学习吧！",
  ["48:4ddf"] = "有传闻说：到了晚上，\n喇叭芽之塔里会闹鬼。\012宝可梦与之对战的时候，\n使出一般属性的招式\011居然一点用也没有。",
  ["48:4e49"] = "哎呀，你是宝可梦训练家？\012如果战胜这里的道馆馆主，\n你就算得上是\011成熟的宝可梦训练家了。",
  ["48:4ea5"] = "桔梗市宝可梦道馆的阿速\n是一位了不起的训练家！\012他继承了父亲的意志，\n努力地捍卫着道馆！",
  ["48:4f1b"] = "前面有棵会动的树！\012一碰它就会晃悠悠地跳舞，\n超级有趣哦！",
  ["48:4f68"] = "这里是桔梗市。\n散发怀旧气息的城市。",
  ["48:4f92"] = "桔梗市宝可梦道馆\n馆主：阿速\011华丽的飞行宝可梦专家！",
  ["48:4fda"] = "这里是喇叭芽之塔\n来进行宝可梦修行吧",
  ["48:5003"] = "初始老师的宝可梦补习班",
  ["48:51e7"] = "…… 我有话要问你。\012…… 我听说火箭队复活了，\n这是真的吗？\012什么，你打败了他们？\n别胡扯了。\012…… 居然是真的？\n那就让我看看\011你的实力吧！",
  ["48:5280"] = "…… 哼！\n这些宝可梦真没用。\012…… 你要清楚，你能赢\n是因为我的宝可梦太弱了。",
  ["48:52cd"] = "…… 弱小的家伙\n真是太讨厌了。\012宝可梦也好，\n训练家也罢……\012那些弱小的家伙，\n我要全部击溃。\011所以我才想变强……\012火箭队也是一样。\012明明一个比一个没用，\n还凑在一起嚣张得要死。\011我绝对不会放过他们。\012…… 你不要来妨碍我，\n看到弱者在旁边晃荡，\011真的非常不舒服呢。",
  ["48:53f5"] = "…… 哼！\n我就知道你在胡扯。",
  ["48:5415"] = "这里面很危险，\n所以我站在这里看着，\011以免有人误闯进来。\012切，莫非我是个好人？",
  ["48:5461"] = "你知道呆呆兽的尾巴吗？\n有传闻说那东西超好吃哦。\012我怎么连这种好事都讲了，\n切，莫非我是个好人？",
  ["48:54b5"] = "镇子里的呆呆兽不见了……\012我好像听说某些地方\n正在出售呆呆兽的尾巴……",
  ["48:550d"] = "呆呆兽都回来了。\n嗯，毕竟是悠哉的呆呆兽，\011之前肯定是到哪悠哉去了。",
  ["48:5568"] = "你也是来找钢铁先生\n制作精灵球的吗？\011好多人都是这样。",
  ["48:55b4"] = "穿过桧皮的城镇后\n就是栎树林。\012但是，途中有小树挡路，\n难以继续前进。\012木炭工匠的宝可梦\n应该学会了能砍树的招式。",
  ["48:564a"] = "呆呆兽： ……\012…… …… ……",
  ["48:565d"] = "…… …… 呀呆？",
  ["48:5679"] = "这里是桧皮镇。\n宝可梦与人\011和谐共生的小镇。",
  ["48:56b2"] = "这里是钢铁先生的家",
  ["48:56c0"] = "桧皮镇宝可梦道馆\n馆主：阿笔\011会走路的虫宝可梦大百科",
  ["48:5706"] = "呆呆兽之井\n别名：求雨之井\012这个地区的人们相信，\n每当呆呆兽打哈欠时，\011天上就会下雨。\012实际上在400年前，\n因为呆呆兽的哈欠，\011帮人们解决了一场大旱灾。\011这件事写进了当时的记录。",
  ["48:57ac"] = "这里是木炭工匠的家",
  ["48:57bb"] = "穿过闸口就是栎树林。",
  ["48:5936"] = "你渡过了那片海？\n那可真是很辛苦啊。\012要是有学会飞翔的宝可梦，\n你就轻松多了……",
  ["48:59a8"] = "没有道馆徽章就没有意义。\n等你战胜了这个城市的\011道馆馆主以后再来吧。\011会给你好东西的。",
  ["48:5a28"] = "这是湛蓝的道馆徽章！\012那这个招式学习器\n就送给你了，拿去。",
  ["48:5a62"] = "让宝可梦记住飞翔的话，\n就可以一瞬间到达\011之前去过的地方哦。",
  ["48:5abc"] = "呵呵呵，我家的丈夫啊，\n输给你以后一直在特训。\012这也挺好的，\n他的肚子最近太松胯了。",
  ["48:5b24"] = "只要使用飞翔，\n就能立刻到达浅葱市！",
  ["48:5b5e"] = "城镇北方的岩石被打碎后，\n可能会出现各种东西。\012想破坏岩石的话，\n让宝可梦使出\011碎岩就行了。",
  ["48:5bd9"] = "道馆馆主阿四先生\n为了锻炼格斗宝可梦，\011会亲自和它们对抗。",
  ["48:5c78"] = "这里是湛蓝市。\n浪涛环绕的海滨城市。",
  ["48:5ca7"] = "湛蓝市宝可梦道馆\n馆主：阿四\011以猛拳诉说一切的男人",
  ["48:5cee"] = "500年老字号\n湛蓝药店\011期待您前来问药",
  ["48:5d3d"] = "湛蓝照相大叔\n请拍1张旅行纪念照吧。",
  ["48:5ec6"] = "原本在这里的塔太旧了，\n随时可能会倒塌，\011所以改建成了全新的电台。",
  ["48:5f06"] = "附近新开了一家自行车店，\n但是到底在哪里啊？\011根本找不到啊。",
  ["48:5f43"] = "那个一身黑的人\n是在模仿火箭队吗？\011真是个怪人！",
  ["48:5f8a"] = "那个一身黑的人\n居然真的是火箭队？\011我到现在都不敢相信。",
  ["48:5fd0"] = "到满金市就要去播音塔！\012听说现在正在进行活动，\n有机会让你的宝可装置\011获得听广播的功能！",
  ["48:6071"] = "哇，你的宝可装置\n可以听广播呢！",
  ["48:6093"] = "嘿嘿嘿……\n本来想在百货店地下楼层\011玩捉迷藏，结果被批评了。",
  ["48:60e0"] = "可以去那间屋子里，\n对宝可梦的昵称\011进行占卜哦。\012你甚至还可以在那里\n给宝可梦重新取个好名字。",
  ["48:612c"] = "嗬哟，这城市真气派啊！\n不过实在是太大了，\011根本搞不清楚哪是哪啊。",
  ["48:616a"] = "这里就是播音塔吗……",
  ["48:6187"] = "你怎么回事？一边去！",
  ["48:61ab"] = "喂，不要在这里瞎晃悠！\n你这样很烦人啊！",
  ["48:61ca"] = "如果能占领播音塔……\012你干嘛！\n关你一个小孩什么事！",
  ["48:6207"] = "宝可梦？\n那是用来挣钱的工具吧！",
  ["48:623f"] = "我们的野心马上就能……\n实在是等了太久了……",
  ["48:627c"] = "喂！\n你一个小孩来这里干嘛！？\011一边凉快去！",
  ["48:62a8"] = "你最好还是明白\n火箭队到底有多可怕！",
  ["48:62d4"] = "这里是满金车站",
  ["48:62ec"] = "满金播音塔",
  ["48:6308"] = "宝可梦物品应有尽有！\n满金百货店",
  ["48:6341"] = "满金市宝可梦道馆\n馆主：小茜\011火爆的可爱小姐姐！",
  ["48:6386"] = "这里是满金市。\n华丽绚烂，\011精致、精神、精美的城市。",
  ["48:63b8"] = "去哪都能悠游自如！\012要找自行车，\n就来奇迹自行车店！",
  ["48:63de"] = "大家的游乐园！\n……满金游戏城",
  ["48:640b"] = "这里是姓名鉴定师的家\n为您占卜宝可梦的姓名",
  ["48:6435"] = "前方是地下通道",
  ["48:644b"] = "前方是地下通道",
  ["49:40d7"] = "…… …… ……\012……又是你吗？\012用不着那么提防吧？\n我也没打算搭理\011像你这样的弱者。\012说起弱者，\n这里的道馆馆主也没影了。\012听说她去了灯塔\n在那照料虚弱的宝可梦。\012……哼，蠢死了！\n碰到虚弱的宝可梦\011放着不管不就好了。\012无法拿来对战的宝可梦，\n根本就是毫无价值。\012你要不要顺便去灯塔\n自我修行一下？\012说不定啊，\n可以强那么一丢丢呢。",
  ["49:4235"] = "晦暗的夜路十分危险！\n晦暗的大海也充满危机！\012没有灯塔的光芒指引，\n船只无法在海上移动。",
  ["49:42e1"] = "你身上的那个东西，\n是传说中的宝可装置吧？\011真好啊，太酷了吧！",
  ["49:431e"] = "你身上的那个东西，\n是传说中的宝可梦图鉴吧？\011真好啊，太酷了吧！",
  ["49:434e"] = "哦哦，少年啊！\n大海超级棒——\012大——海——汪——洋\n无——边——无——际！",
  ["49:439a"] = "这里是浅葱市。\n最接近遥远异国的\011港口城市。",
  ["49:43ca"] = "浅葱港\n高速船的登船口",
  ["49:43e7"] = "浅葱市宝可梦道馆\n馆主：阿蜜\011铜墙铁壁般的少女",
  ["49:442a"] = "浅葱灯塔\n别名：光辉灯塔",
  ["49:4604"] = "以前好像有两座塔\n分别位于缘朱东西二侧……",
  ["49:4646"] = "呵、呵，你有没有学过\n年轻和服女孩的舞蹈？\012现在去舞场的话，\n可以看到一个奇怪的客人，\011他好像会送出好东西呢。",
  ["49:46de"] = "我接下来要去舞场\n练习舞蹈，\011你要不要也去看看？",
  ["49:471d"] = "曾今的这座塔……\n其实比现在高得多，\011可是被一场大火烧毁了。",
  ["49:4761"] = "有三只巨大的宝可梦\n往各个方向跑走了，\011那是什么啊？",
  ["49:47a4"] = "这是听别人说的：\n浅葱市的灯塔里……\012有只照亮黑暗的宝可梦，\n它现在病得很重。",
  ["49:481d"] = "我听说浅葱灯塔的\n那只宝可梦痊愈了，\011这下晚上也能出船了。",
  ["49:487e"] = "听别人说在愤怒之湖里，\n有宝可梦在大闹特闹，\011真想去看看。",
  ["49:48c3"] = "这里是缘朱市。\n过去与未来之间的\011历史名城。",
  ["49:4905"] = "铃铛塔\012据说传说的宝可梦\n会降临于此。",
  ["49:493a"] = "缘朱市宝可梦道馆\n馆主：松叶\011千里眼的修验者",
  ["49:497e"] = "缘朱舞场\n正式名称：歌舞练场",
  ["49:4996"] = "烧焦塔\012在神秘的大火中焚毁。\n里面非常危险，请勿靠近。",
  ["49:4b65"] = "喂、喂、小伙子！\012难得来趟卡吉镇，\n当然要买愤怒馒头啦！\011这是旅行小贴士哦！\012立即抢购，只需¥300，\n心动不如行动？",
  ["49:4c03"] = "哦哦，吃个痛快吧！",
  ["49:4c14"] = "你的钱不够啊。",
  ["49:4c31"] = "啊，这样啊……",
  ["49:4c41"] = "拿不下更多了！",
  ["49:4c5f"] = "愤怒馒头卖完了，\n我正在收拾东西呢，\011你别来打搅我！",
  ["49:4ca2"] = "您也去湖边看了\n舞姿狂野的暴鲤龙吗？",
  ["49:4cda"] = "说起这愤怒之湖啊，\n鲤鱼王好像都回来了。\012湖畔的垂钓者们\n应该也会很开心吧？",
  ["49:4d33"] = "哎呀哎呀，来都来了，\n不如好好观光一番吧。\012现在北方的愤怒之湖\n非常值得一看哦！",
  ["49:4daf"] = "有空去婆婆的小店看看？\n有些东西只在那里卖哦！",
  ["49:4deb"] = "这儿是卡吉镇。\n欢迎来到忍者之乡。",
  ["49:4e1b"] = "既然来了卡吉镇，\n必须尝尝“愤怒馒头”！！",
  ["49:4e4e"] = "卡吉镇宝可梦道馆\n馆主：柳伯\011传授严寒的老师",
  ["49:5063"] = "在这个湖里\n到处都是暴鲤龙……\012肯定是有人做了手脚，\n强行让湖里的鲤鱼王\011进化了……",
  ["49:50c0"] = "你也是听了传言\n才跑过来的吧？\012你叫{PLAYER}吗？\n我是阿渡，\011和你一样，我也是训练家。\012得知到这里的事情之后，\n我很想查明真相……\012{PLAYER}！\n我看了刚才的战斗，\011知道你是\011相当有实力的训练家。\012你愿不愿意\n和我一起进行调查？",
  ["49:51d2"] = "阿渡：那可帮大忙了！\012好像是某种神秘电波\n强行让湖里的鲤鱼王进化。\011而这个神秘的电波\011是从卡吉镇发出来的。\012{PLAYER}！\n我先过去等你吧！",
  ["49:527d"] = "这样吗……\n等你改主意了再过来吧。",
  ["49:52b1"] = "阿渡：嗯？\n你愿意帮忙吗？",
  ["49:52d7"] = "暴鲤龙：暴鲤——！！",
  ["49:52eb"] = "{PLAYER}\n拿到了红色鳞片！",
  ["49:5304"] = "暴鲤龙生气了！\n肯定要发生坏事了……",
  ["49:532d"] = "嚯嚯！\n你带着的鲤鱼王不错啊。",
  ["49:5350"] = "听说以前就有暴鲤龙\n在这一带大闹的先例。\012这和这次的大量出现事件\n是不是有某种关联呢？",
  ["49:53c7"] = "我是不是看错了？\n怎么看到湖里\011有只红色的暴鲤龙……\012要说暴鲤龙，\n一般应该是蓝色吧？",
  ["49:542e"] = "用我刚刚垂钓到的\n引以为豪的宝可梦对战吧！",
  ["49:545a"] = "虽然垂钓技巧很成熟，\n但是宝可梦很不成熟……",
  ["49:549b"] = "比垂钓我可不会输！\n毕竟我一整天\011都在垂钓宝可梦！",
  ["49:54cc"] = "不管怎么努力，永远只能\n钓到同一种宝可梦！",
  ["49:5503"] = "……钓鱼线缠成一团了。",
  ["49:551d"] = "为什么就是钓不到\n好宝可梦啊，讨厌！",
  ["49:553e"] = "发现训练家之后\n一定要发起挑战！\011这是训练家的宿命！",
  ["49:5594"] = "呼……\n不错的战斗。",
  ["49:55a8"] = "宝可梦与训练家都能\n在一次又一次的战斗中\011获得锻炼！",
  ["49:55eb"] = "红色暴鲤龙去哪了？\012啊，已经没了？\n我特地过来看它的啊……\012算了，你和我对战吧！",
  ["49:5651"] = "精彩。",
  ["49:565e"] = "说起来，\n我以前见过粉红色巴大蝶！",
  ["49:5690"] = "星祺三：呀，初次见面！\012我是星期三的星祺三！",
  ["49:56e9"] = "难得能见到你，\n请收下这个吧！",
  ["49:5717"] = "星祺三：那是黑带。\n这个道具可以提升\011格斗属性招式的威力！",
  ["49:5750"] = "星祺三：既然能找到我，\n那你应该见过\011其他的兄弟姐妹吧？\012或者说这次是运气好？",
  ["49:57b5"] = "星祺三：今天好像\n不是星琪三呢！\011好可惜啊！",
  ["49:57e3"] = "这里是愤怒之湖\n别名：暴鲤龙湖",
  ["49:580f"] = "垂钓名人的家",
  ["49:5994"] = "非常抱歉。\012道馆馆主正在\n后面那个洞穴中修行。\012不知道什么时候回来……",
  ["49:5a01"] = "道馆馆主正在等着你呢。\012不过一般水准的训练家\n是不可能赢过她的。",
  ["49:5a6b"] = "你居然战胜了馆主吗！\n太厉害了吧……\012以你现在的实力，\n或许能战胜宝可梦联盟呢。",
  ["49:5ad0"] = "只有龙使者才能\n在这里进行修行。\011您请回吧。",
  ["49:5b0e"] = "既然你得到了龙使者首领\n小椿大人的认可，\011那就请进吧。",
  ["49:5b4e"] = "我的收音机坏了吗？\n最近怎么只能听见\011奇怪的节目啊？",
  ["49:5b87"] = "哇——\n信号很强烈啊！\012嗯？\n我在听广播呢！",
  ["49:5bc1"] = "哎呀，你也想\n让宝可梦忘记招式吗？",
  ["49:5bf5"] = "我一定要成为\n小椿那样的龙使者！",
  ["49:5c1f"] = "星祺六：…… …… ……\012我是星期六的星祺六……",
  ["49:5c4f"] = "这个给你……",
  ["49:5c63"] = "星祺六：…… …… ……\012诅咒之符……\012幽灵属性招式会变强，\n强到吓你一跳……",
  ["49:5cae"] = "星祺六：…… …… ……\012到了下个星期六\n再见吧……\012不过到时候没东西给你……",
  ["49:5cf8"] = "星祺六：今天\n不是星期六啊……\011…… …… …… …… ……",
  ["49:5d16"] = "哎！\n你居然穿过了冰雪小径！\012想必你一定是\n实力非凡的训练家吧！！",
  ["49:5d5f"] = "这里是烟墨市。\n坐落在山间的静谧城市。",
  ["49:5d89"] = "烟墨市宝可梦道馆\n馆主：小椿\011神圣的龙宝可梦使者！",
  ["49:5dd1"] = "啥都能忘记？爷爷的家",
  ["49:5de7"] = "前方是龙穴",
  ["49:5dfb"] = "有用的公告牌！\012如果携带了奇迹果，\n不论什么特殊状态\011都能恢复！",
  ["49:5f27"] = "这里是白银山",
  ["4a:4175"] = "为了挑战宝可梦联盟，\n我在做最后的调整。",
  ["4a:41ab"] = "失、失误了！",
  ["4a:41b7"] = "如果宝可梦缺乏锻炼，\n想获胜就很难了。\012宝可梦联盟的四天王\n实力远超现在的\011所有道馆馆主！",
  ["4a:4246"] = "不断进行严酷的战斗，\n就能领悟真正的强大！",
  ["4a:4276"] = "人生更加严酷啊！",
  ["4a:4293"] = "要去宝可梦联盟\n必须穿过冠军之路……\012不过，冠军之路非常艰险，\n谁也不敢去。",
  ["4a:430b"] = "能够站在这里就说明\n你有一定的实力！\012我也会尽全力\n与你对战！",
  ["4a:436c"] = "骗人！\n我不相信！",
  ["4a:4386"] = "战胜8个道馆馆主\n让我很有自信……\012看来还要更加努力！",
  ["4a:43e5"] = "被一个叫{RIVAL}\n的训练家打败了……\012强是很强，\n但感觉他心里只有获胜。\011他的宝可梦好可怜啊。",
  ["4a:446e"] = "宝可梦当然不是\n用来战斗的工具。",
  ["4a:4488"] = "宝可梦应该是\n贯穿人生的重要伙伴。",
  ["4a:44b3"] = "居然有这么多徽章，\n真了不起！\012但是你应该不会\n仅仅满足于收集徽章吧。",
  ["4a:4519"] = "真是不错的战斗！",
  ["4a:4527"] = "人和宝可梦想要获得成长，\n就要经历各种磨难。\012你今后也不能大意，\n要继续努力啊！",
  ["4a:4573"] = "今天状态极好！\n感觉现在的自己甚至可以\011战胜宝可梦联盟的冠军！",
  ["4a:45bc"] = "哎呀呀，\n想对战还差了点吗？",
  ["4a:45d5"] = "垂钓也好，宝可梦也好，\n放弃的话就全部结束了。",
  ["4a:4613"] = "这里是26号道路\n宝可梦联盟接待处入口",
  ["4a:486a"] = "嘿！",
  ["4a:4870"] = "就在这一刻！\012你迈出了\n关都地区的第一步！\012你不妨打开地图\n确认一下吧！",
  ["4a:48d8"] = "你看起来很强呢。\n那就请你和我交手吧！",
  ["4a:4904"] = "……！",
  ["4a:490a"] = "当你越过这条漫长的路，\n你一定会获得许多感悟。\012抱歉，其实\n我只是想说点帅气的话。",
  ["4a:497b"] = "唔，你丫有两下啊！",
  ["4a:4997"] = "不出所料！",
  ["4a:49ab"] = "强大的训练家之间\n是会产生共鸣的！",
  ["4a:49de"] = "千万不要小看\n这一带的野生宝可梦！",
  ["4a:4a18"] = "啊啊，太强了！",
  ["4a:4a34"] = "我不应该小看\n你这样的小朋友！",
  ["4a:4a72"] = "哎呀，真少见，\n居然有人经过这里。\011你在磨练技术吗？",
  ["4a:4ab3"] = "呃，太强了吧。",
  ["4a:4acd"] = "有的宝可梦我让它进化，\n有的宝可梦我不让它进化，\011以此来研究宝可梦的特性。\012进化后虽然会变强，\n但学会招式的时机会变迟。",
  ["4a:4b54"] = "我来猜猜你的想法。\012……嗯嗯嗯。\012明白了！\n是挑战宝可梦联盟吧！",
  ["4a:4bc0"] = "……太强了！",
  ["4a:4bd1"] = "以你的实力，\n在宝可梦联盟也会顺利，\011这是我预测到的结果。",
  ["4a:4c21"] = "哔，咻，哔哔咿咿！",
  ["4a:4c39"] = "哔——！",
  ["4a:4c41"] = "我们养鸟人用口哨\n模仿宝可梦的叫声，\011以此来下达命令。",
  ["4a:4c7e"] = "这里是都城瀑布\n关都与城都的交界处",
  ["4a:4d53"] = "这里是28号道路",
  ["4a:4ed2"] = "宝可梦潜伏在草丛中，\n随时都可能会扑过来。",
  ["4a:4f0a"] = "我看你经过好几次了，\n现在捕捉到多少宝可梦了？\012要不，我告诉你\n捕捉宝可梦的方法吧？",
  ["4a:4f78"] = "嗯嗯，就是这种感觉！\012先削弱对方，\n就会变得更容易捕捉！",
  ["4a:4fc2"] = "这样吗，\n那就算了吧。\012如果有想捕捉的宝可梦，\n来回走就对了！",
  ["4a:500e"] = "嗯？希望我来教你\n宝可梦的捕捉方法吗？",
  ["4a:503f"] = "哟，\n你的宝可梦还好吗？\012如果宝可梦太虚弱，\n不想让它战斗，\011那你走路的时候\011尽量避开草丛比较好。",
  ["4a:5097"] = "那里不是有个断坡吗？\012虽然直接往下跳挺吓人的，\n但是可以避开草丛，\011直达若叶镇哦！",
  ["4a:5104"] = "因为我想稍微休息一下，\n所以正在写记录。",
  ["4a:5177"] = "有的宝可梦只在夜晚出现，\n我在这等着捕捉它们呢。",
  ["4a:51a7"] = "有的宝可梦只在清晨出现，\n我在这等着捕捉它们呢。",
  ["4a:51dd"] = "星琪二：我们这是\n初次见面吧？\012我是星期二的星琪二。",
  ["4a:525a"] = "作为我的问候，\n请你收下这个。\011这是粉红丝带。",
  ["4a:529a"] = "星琪二：你不觉得\n这条丝带非常可爱吗？\012这是可以强化一般属性\n招式的道具。\011我想它一定会派上用场的。",
  ["4a:5312"] = "星琪二：你见到了\n星琪一姐姐吗？\011那星祺三弟弟呢？\012我在7个兄弟姐妹里\n排行老二哦。",
  ["4a:5384"] = "星琪二：今天好像\n不是星期二呢。\011真遗憾……",
  ["4a:53b9"] = "这里是29号道路\n吉花市   ……   若叶镇",
  ["4a:53e4"] = "这里是29号道路\n吉花市   ……   若叶镇",
  ["4a:55ad"] = "上啊，小拉达！\012撞击！",
  ["4a:55c3"] = "你干嘛？\n这是场关键的对决！\011一边待着去！",
  ["4a:55f0"] = "我刚才输了，所以我要\n寻找更多的宝可梦。\012不过嘛，你看起来很弱！\n好！来对战吧！",
  ["4a:5649"] = "啊！\n没有能战斗的宝可梦了。",
  ["4a:566a"] = "我收集的宝可梦太少了，\n所以对战时很吃力呢！\011要捕捉更多宝可梦啊！",
  ["4a:56ae"] = "你是宝可梦训练家吧？\n那就来场宝可梦对战吧！",
  ["4a:56e5"] = "太奇怪了。\n之前我还是能赢的啊？",
  ["4a:5703"] = "宝可梦之路\n真是艰险而漫长……\012好！我要挑战各种训练家，\n以此来锻炼自己！",
  ["4a:575e"] = "虫宝可梦没碰到，\n倒是碰到了个训练家！",
  ["4a:5789"] = "嗷！你太强了！",
  ["4a:57a2"] = "我在捕捉宝可梦时\n耗费了许多精灵球。\012我之前就应该\n多买一些的……",
  ["4a:57f0"] = "你要去宝可梦爷爷的家？\n再往前一点就到了哦。",
  ["4a:581a"] = "看他们进行宝可梦对战\n还挺开心的！\011要不你也来试试？",
  ["4a:584a"] = "我不是训练家。\012但是我知道\n训练家目光交汇的那一刻\011就意味着对战开始了。",
  ["4a:5891"] = "这里是30号道路\n桔梗市   ……   吉花市",
  ["4a:58ba"] = "宝可梦爷爷的家\n就在前面！",
  ["4a:58db"] = "宝可梦爷爷的家",
  ["4a:58ec"] = "有用的公告牌！\012捕捉别人的宝可梦\n是小偷行为！\012精灵球只能\n投向野生的宝可梦！",
  ["4a:5b1e"] = "这是黑暗洞穴……\n如果我的宝可梦会用\011照亮周围的招式就好了，\011那我就可以去里面调查了。",
  ["4a:5b54"] = "我捉到了很多宝可梦，\n来和我对战吧！",
  ["4a:5b87"] = "怎么回事啊……",
  ["4a:5b90"] = "即使已经带了6只宝可梦，\n也可以继续捉喔。\011捉住的新宝可梦会自动\011传进电脑的盒子里。",
  ["4a:5bf8"] = "唔，呼噜呼噜……\012为了找宝可梦跋山涉水，\n脚很痛，人又很困……\012如果我是野生的宝可梦，\n现在这样应该很好捕捉……\011呼……呼噜呼噜……",
  ["4a:5c80"] = "呼……唔姆唔姆……\012嗯？什么？\n有信件要给我？",
  ["4a:5caf"] = "{PLAYER}交出了\n携带信件的宝可梦！",
  ["4a:5cd9"] = "我看看……\012上面写着\n“其实，黑暗洞穴还能\011通往其他道路。”\012感谢你特地送来！\012我朋友可真够意思，\n你也很够意思！\012看到别人这么够意思，\n我也想意思意思！\012对了，\n这个送给你吧！",
  ["4a:5dbb"] = "招式学习器50是恶梦。\012用这个招式可以慢慢削减\n睡眠中的对手的体力。\012呜——太可怕了……\n我可不想做恶梦啊……",
  ["4a:5e46"] = "这封信件不是给我的。",
  ["4a:5e5e"] = "那只宝可梦怎么了？\n没有信件啊。",
  ["4a:5e97"] = "什么？什么都没有？",
  ["4a:5eb6"] = "我拿走那只宝梦后，\n你拿什么出战呢！",
  ["4a:5efa"] = "我在黑暗洞穴里\n捕捉到了不错的宝可梦！\012我要锻炼它，\n然后用它去挑战\011桔梗道馆的馆主阿速！",
  ["4a:5f6a"] = "这里是31号道路\n桔梗市   ……   吉花市",
  ["4a:5f93"] = "这里是黑暗洞穴",
  ["4b:42a5"] = "喝——！！\n且慢——！！",
  ["4b:42c0"] = "你就是{PLAYER}吧？\n好像有个眼镜男正在\011到处找你哦。\012这会儿应该在宝可梦中心\n等着你吧。\011你去看看吧！",
  ["4b:43c5"] = "去过宝可梦道馆吗？\n要通过宝可梦道馆\011来磨练自己以及宝可梦。\012这是训练家的常识呀！\n赶紧过去吧！",
  ["4b:443a"] = "嗯，你的宝可梦很不错啊。\n他们都在桔梗市\011进行过各种训练吧？\012其中最有价值的修行\n肯定是宝可梦道馆。\012好！既然来了桔梗市，\n就收下这个当作纪念吧。\012据说让宝可梦携带以后，\n草属性招式的威力\011就会上升哦！",
  ["4b:452a"] = "在桔梗市获得的经验，\n肯定能用到今后的旅程中！",
  ["4b:456e"] = "又香又有营养的\n美味尾巴，您需要吗？\012现在购买，\n只要¥1,000,000。\011欲购从速！",
  ["4b:45e4"] = "你的钱根本不够嘛！\012切！我还以为现在的\n小朋友都很有钱呢……",
  ["4b:4611"] = "不要吗！\n滚一边去！滚！",
  ["4b:4636"] = "哇！\012你吓跑了我的猎物啊！",
  ["4b:4659"] = "咕咚！",
  ["4b:4663"] = "不能急，不能躁……\012不论钓鱼还是宝可梦，\n诀窍都是一样的。",
  ["4b:46a4"] = "我很擅长垂钓，\n更擅长运用宝可梦！",
  ["4b:46d3"] = "急着起竿了……",
  ["4b:46f1"] = "钓鱼是一生的乐趣！\n宝可梦是一生的朋友！",
  ["4b:4863"] = "我的宝可梦新鲜得很，\n现在还在活蹦乱跳呢！",
  ["4b:487d"] = "扑通扑通。",
  ["4b:4886"] = "新捉到的宝可梦\n和以前的宝可梦合不来啊。",
  ["4b:48c2"] = "之前没见过啊，\n你小子很强吗？",
  ["4b:4907"] = "太强了吧！",
  ["4b:4916"] = "我要用我喜欢的宝可梦\n来成为最强的训练家！\012不论有多强，我也不想用\n大家都在用的宝可梦。",
  ["4b:497c"] = "在草丛里发现了好宝可梦！\n一定能派上用场吧！",
  ["4b:49bf"] = "啊啊，\n还以为能赢的。",
  ["4b:49dd"] = "在草丛里走着走着，\n就粘上了好多虫子。",
  ["4b:4a02"] = "你的目光……\n很令人在意啊。",
  ["4b:4a20"] = "嗯，遗憾。",
  ["4b:4a3e"] = "不想对战的话，\n就不要和别人目光交汇。",
  ["4b:4a73"] = "……对对，\n就是这么一回事！\012啊，什么？宝可梦对战？\n可我还在打电话啊。\011算了，只好速战速决了。",
  ["4b:4ad2"] = "真是的！你生什么气啊！\n对面可是女生啊！",
  ["4b:4aed"] = "刚刚我还聊得很开心的……",
  ["4b:4b0c"] = "哦，那个徽章是……\012桔梗的道馆徽章！\n你战胜了阿速先生吗！",
  ["4b:4b41"] = "我知道自己不够成熟。",
  ["4b:4b61"] = "我该回桔梗市宝可梦道馆\n重新历练自己了吧。",
  ["4b:4bc0"] = "喔哦哦哦！\012我随便一吼大家就跑了，\n你却迎面而来哎哎哎！\011我好感动嗡嗡嗡！\011这个就拿去吧啊啊啊！",
  ["4b:4c19"] = "喔哦哦哦！\n里面是“吼叫”！\011一吼叫就能吓跑宝可梦！",
  ["4b:4c4e"] = "星琪五：哟呵——！\012人家是星期五的星琪五！\n请多关照哦！",
  ["4b:4c91"] = "瞧，这是毒针！\n就把它送给你了！",
  ["4b:4caf"] = "星琪五：让宝可梦携带它\n再使出毒属性招式……\012啊！\012你猜怎么着！\012招式的威力居然变强了！",
  ["4b:4d27"] = "星琪五：哎呀呀！\n你最喜欢星期几啊？\012人家选星期五哦！\n这还用说嘛！\012你也这么认为吧？",
  ["4b:4d8c"] = "星琪五：今天不是\n星期五吗？\011真的是太无聊了！",
  ["4b:4dc7"] = "这里是32号道路\n桔梗市   ……   桧皮镇",
  ["4b:4deb"] = "阿露福遗迹\n东侧入口",
  ["4b:4e08"] = "前方是互连洞",
  ["4b:4fad"] = "虽然刚脱离洞穴，\n不过我还精力充沛！",
  ["4b:4ff1"] = "哦哦！\n还是小男孩更有精力！",
  ["4b:5011"] = "如果放登山男归山，\n精力会比这充沛一百倍！",
  ["4b:503e"] = "这里是33号道路",
  ["4b:52ee"] = "这一带是我的\n练习用地！",
  ["4b:530f"] = "怎么会这样！",
  ["4b:531f"] = "如果一般的练习还不够，\n那就要进行特训！\011毕竟我的梦想是道馆馆主！",
  ["4b:536c"] = "我是我们班\n宝可梦最强的人哦！",
  ["4b:538e"] = "哦呦呦……\n天外有天吗……",
  ["4b:53b0"] = "为了在班里能有面子，\n我还要不断努力。",
  ["4b:53e2"] = "我有信心能培养好宝可梦，\n来和我对战吧！",
  ["4b:541a"] = "是我培育太少了吗？",
  ["4b:5439"] = "嗯——该怎么办呢？\n要不要寄存放到育屋呢？",
  ["4b:5473"] = "你是宝可梦训练家吗？\n那就来当我的练习搭档吧！",
  ["4b:54a4"] = "不行啊！\n完全赢不了！",
  ["4b:54be"] = "你太强了，\n根本没法好好练习！",
  ["4b:54ea"] = "你，就是说你，\n在那里干嘛呢？",
  ["4b:550f"] = "好厉害的小朋友啊！",
  ["4b:552a"] = "巡逻没有发现异常！\n你也多加小心啊。",
  ["4b:5570"] = "我在附近巡逻，\n看看有没有可疑的人。",
  ["4b:559c"] = "让你看看我刚从培育屋里\n取回来的宝可梦\011究竟变得有多强！",
  ["4b:55e7"] = "为什么会这样！？",
  ["4b:5602"] = "宝可梦不知道什么时候\n记住了我没见过的招式，\011所以我才会不知所措。",
  ["4b:5649"] = "真理纱：呀！\n来了个男孩！",
  ["4b:5669"] = "真理纱：讨厌～好强啊！",
  ["4b:5688"] = "真理纱：我一定要让\n真理亚姐姐为我报仇！",
  ["4b:56b6"] = "真理纱：沙滩很美吧？\n这里是我们的秘密基地！",
  ["4b:56f4"] = "真理香：还真敢过来！\n我要给真理纱报仇！",
  ["4b:5722"] = "真理香：对不起！\n真理纱！姐姐！",
  ["4b:573f"] = "真理香：千万不要大意！\n真理亚姐姐很强的！",
  ["4b:576f"] = "真理香：太阳的光芒\n能让身体变得更结实哦！",
  ["4b:5799"] = "真理亚：你倒是很关照\n我那几个妹妹嘛！",
  ["4b:57c9"] = "真理亚：我居然\n会输给你！",
  ["4b:57eb"] = "真理亚：你好强啊。\n我输了，彻底输了……\012这个就给你了！",
  ["4b:5834"] = "真理亚：真是很抱歉，\n突然向你发起对战。\012我们还以为没人会来这里，\n所以有点惊慌失措。",
  ["4b:58b1"] = "这里是34号道路\n满金市   ……   桧皮镇\011途经栎树林",
  ["4b:58f6"] = "有用的公告牌！\012能结果的树木，\n每天都会结出新树果。\012先记下哪里有什么树果，\n有空再回去看看吧！",
  ["4b:595a"] = "这里是培育屋\n为你培育宝可梦",
  ["4b:5c09"] = "靠广播收集到了\n很多宝可梦情报呢。\011我现在应该挺强的。",
  ["4b:5c44"] = "我输了！",
  ["4b:5c4d"] = "广播节目中播放的音乐\n有时能让野生宝可梦镇静，\011有时能让它们变得更活跃！",
  ["4b:5c81"] = "好吧！就在女朋友面前\n好好展示一下吧！",
  ["4b:5cac"] = "求你了……\n能不能输给我啊……",
  ["4b:5cd0"] = "反而在女朋友面前\n出丑了……",
  ["4b:5cfd"] = "我的男朋友好弱，\n真靠不住啊……",
  ["4b:5d29"] = "哎，你好强啊！",
  ["4b:5d43"] = "比起男朋友，\n还是宝可梦更可靠呢。",
  ["4b:5d73"] = "你要去宝可梦道馆？\n我也是！",
  ["4b:5d96"] = "嗯，赢不了哇……",
  ["4b:5daa"] = "道馆给的徽章很漂亮，\n所以我在收集它们。",
  ["4b:5dd6"] = "你捕捉宝可梦的时候，\n都在用哪种球呢？",
  ["4b:5df8"] = "呀！\n速度还不够吗。",
  ["4b:5e11"] = "有些宝可梦逃得很快，\n这种时候最好用的\011就是钢铁先生的速度球！\012每当我找到白球果，\n就会把它交给钢铁先生，\011让他制作特制的球。",
  ["4b:5eaa"] = "看！\n这华丽的丢投球姿势！",
  ["4b:5ece"] = "噫——发麻了。",
  ["4b:5ee6"] = "本来想用我自豪的宝可梦\n让你麻痹的，\011反而被你的强大迷倒了！",
  ["4b:5f36"] = "只要有虫宝可梦，\n什么地方我都愿意去！",
  ["4b:5f61"] = "原来如此，\n这就是你的战斗风格呢。",
  ["4b:5f81"] = "我就是靠宝贵的毛球\n在公园的捕虫大赛里\011获得了第一名！",
  ["4b:5fc3"] = "我在这种地方\n进行喷火练习！",
  ["4b:5fe5"] = "烫烫烫……\n刚才烧到鼻子了。",
  ["4b:6009"] = "用广播听宝可梦进行曲，\n宝可梦会比平时更易扑来！",
  ["4b:6037"] = "夜晚充满了危险！",
  ["4b:6053"] = "哎呀呀。",
  ["4b:605c"] = "夜晚有夜晚的快乐，\n但你也别玩过头了。",
  ["4b:60a3"] = "因为你有强大的宝可梦，\n所以去哪都不怕，对吧？",
  ["4b:60e1"] = "这里是35号道路",
  ["4b:6321"] = "有棵奇怪的树！\n要使用杰尼龟喷壶吗？",
  ["4b:6346"] = "{PLAYER}使用了\n杰尼龟喷壶！",
  ["4b:6360"] = "奇怪的树好像很反感\n杰尼龟喷壶！\012奇怪的树扑过来了！",
  ["4b:63a7"] = "你好呀！\012我本来以为，\n靠我那厚重的掌力，\011推倒一两棵树不在话下……\012但是办不到呀！\n真是太遗憾了呀！",
  ["4b:6408"] = "是你帮我搞定了\n那棵碍事的树？\012真是令人惭愧呀！\n我要送给你这个呀！",
  ["4b:6464"] = "里面是必杀碎岩！\n只要有了这个招式，\011随手一击就能打碎岩块！\012请你尽情地\n去击碎岩块呀！",
  ["4b:64f0"] = "路上长了棵奇怪的树，\n不能去满金市买东西了！\011希望能有人解决这个问题。",
  ["4b:6568"] = "那棵奇怪的树\n消失得无影无踪……\012什么！它是宝可梦？",
  ["4b:65b7"] = "让我猜猜你的心思！",
  ["4b:65d8"] = "没猜中！",
  ["4b:65e8"] = "如果进攻时能预测对手，\n那就会变得十分强大！",
  ["4b:662a"] = "我已经充分地预习过\n如何面对各种宝可梦！",
  ["4b:665a"] = "什么……？\n计算失误了？",
  ["4b:6674"] = "唔唔唔唔唔……\n我每天花5小时学习啊……\012这世上有很多事情\n光靠教科书是学不会的呢。",
  ["4b:66cc"] = "星祺四：你是谁？\012我是星期四的星祺四。",
  ["4b:66f9"] = "好的，收下这个！",
  ["4b:6713"] = "星祺四：让宝可梦携带它\n再使出岩石属性招式……\012岩石属性招式的\n攻击力就会提升哦！",
  ["4b:6776"] = "星祺四：我是\n星期四的星祺四！\0117个孩子里的二儿子！",
  ["4b:67bf"] = "星祺四：今天\n不是星期四吗……\011好失望啊。",
  ["4b:67f0"] = "这里是36号道路",
  ["4b:67fa"] = "阿露福遗迹\n北侧入口",
  ["4b:6818"] = "有用的公告牌！\012即使是同一种宝可梦，\n强弱也存有差异。\012即使刚开始都差不多，\n培育后也会产生巨大差异。",
  ["4b:68ba"] = "有用的公告牌！\012如果使用了\n“挖洞”这一招式，\011就可以瞬间返回入口。\012在洞穴探险的时候，\n如有宝可梦会使用挖洞，\011旅行也会轻松不少吧。",
  ["4c:4093"] = "茉奈：我会和佳奈\n齐心协力的！",
  ["4c:40bc"] = "茉奈和加奈:呜，\n哥哥好坏呀。",
  ["4c:40d5"] = "茉奈：我懂姐姐的想法，\n也懂宝可梦的想法。",
  ["4c:410f"] = "佳奈：我会和茉奈\n齐心协力的！",
  ["4c:4138"] = "茉奈和加奈:呜，\n哥哥好坏呀。",
  ["4c:4151"] = "佳奈：我们姐妹\n和宝可梦异体同心！",
  ["4c:4180"] = "如果宝可梦陷入睡眠，\n就做不了任何事情。\011我要让你体验这种恐惧！",
  ["4c:41ca"] = "输了……\n我好悲伤啊。",
  ["4c:41e5"] = "让对方陷入麻痹或睡眠，\n从而剥夺对方的自由。\011这是非常重要的技巧。",
  ["4c:422d"] = "星祺天：我呢，\n就是星期天的星祺天！",
  ["4c:4269"] = "既然遇见了大哥哥，\n我就要按规矩送出这个！",
  ["4c:4294"] = "星祺天：这个就是……\012呃……\012……是什么来着？\012…… …… ……\012啊！\n想起来了！\012让宝可梦携带它，\n再使出电属性招式，\011招式威力就会变强！\011这是星琪一姐姐说的！",
  ["4c:4336"] = "星祺天：大姐星琪一，\n二姐星琪二，\011三哥星祺三，\011四哥星祺四，\011五姐星琪五，\011还有六哥星祺六！\012而我是最小的！",
  ["4c:43a8"] = "星祺天：今天不是\n星期天呀？\011呃……我忘了！",
  ["4c:43d1"] = "这里是37号道路",
  ["4c:45a8"] = "展翅翱翔吧，\n我的鸟宝可梦！",
  ["4c:45d6"] = "我现在想直接乘上\n鸟宝可梦去旅行呢。",
  ["4c:45f9"] = "为了让宝可梦学会\n能在天空飞翔的招式，\011我打算去湛蓝市修行！",
  ["4c:4638"] = "那么请让我赶紧试试\n今天新学到的知识吧。",
  ["4c:4661"] = "哎呀，不对劲啊？\n是我的学识太浅薄了吗？",
  ["4c:4681"] = "平时光顾着考试了，\n都没怎么研究宝可梦。\012所以能用宝可梦的时候，\n我都会全神贯注哦！",
  ["4c:46f0"] = "你的宝可梦很强吗？\012既然这么强，\n教我一些小窍门呗！",
  ["4c:472e"] = "原来如此……\n还有这种战斗方式啊。",
  ["4c:4752"] = "告诉你一些有用的情报吧：\012哞哞牧场的鲜奶，\n喝了都说好哦。",
  ["4c:4796"] = "嘿！\n这位可爱的训练家！\012带着怎样的宝可梦啊，\n让我看看嘛？",
  ["4c:47ca"] = "看到了好多宝可梦，\n我真是太幸福了——！",
  ["4c:47eb"] = "每次看到宝可梦，\n都会让人感到舒心，\011或者说是让人安心吧。",
  ["4c:481d"] = "我去过各种国家，\n认得很多宝可梦哦！",
  ["4c:4856"] = "你简直就是\n世界级水平！",
  ["4c:4872"] = "在各种各样的国家\n生活着各种各样的人，\011他们都和宝可梦和谐共处。",
  ["4c:48b2"] = "这里是38号道路\n浅葱市   ……   缘朱市",
  ["4c:48d9"] = "有用的公告牌！\012在宝可梦进化时\n按下B键，\011受惊的宝可梦会停止进化。\011这被称为“取消进化”。",
  ["4c:4abc"] = "大奶罐：嗯，哞——！",
  ["4c:4acc"] = "好久没有回浅葱市了，\n那就来场宝可梦对战吧！",
  ["4c:4b05"] = "哐——！",
  ["4c:4b10"] = "我的宝可梦是在外国捉的，\n也是在外国培育起来的。\011是我长途航行的好搭档！",
  ["4c:4b68"] = "我能炫耀自己的宝可梦吗？",
  ["4c:4b94"] = "炫耀失败……",
  ["4c:4bae"] = "不听别人的炫耀！\n这可是我们\011发烧友俱乐部的规定！",
  ["4c:4c11"] = "喂，和我同时拿出\n可爱的宝可梦吧？",
  ["4c:4c53"] = "输了也无所谓了。",
  ["4c:4c68"] = "你有没有听说过\n宝可梦有小宝宝呢？\011一定非常可爱吧？",
  ["4c:4ca2"] = "让我见识一下\n你的宝可梦有什么能耐！",
  ["4c:4ccd"] = "不错啊，\n你的宝可梦很有潜力啊。",
  ["4c:4ced"] = "宝可梦不是\n具备各种能力嘛。\012与之类似，我们人类\n也拥有很多可能性呢。",
  ["4c:4d5a"] = "这里是39号道路\n浅葱市   ……   缘朱市",
  ["4c:4d81"] = "哞哞牧场\n来杯美味的现榨鲜奶吧！",
  ["4c:4dad"] = "有用的公告牌！\012用头锤摇树的时候，\n不同的树上会掉落\011不同的宝可梦。\012对各种树使出头锤吧！",
  ["4c:4f84"] = "入水之前\n要做热身运动！\012这是基础知识！",
  ["4c:4fc3"] = "呜，难过！",
  ["4c:4fd7"] = "从这里去湛蓝市，\n路程相当遥远啊！",
  ["4c:5009"] = "少年，\n别乘着宝可梦，要自己游！",
  ["4c:5044"] = "我输了……",
  ["4c:5054"] = "游泳需要动用全身，\n是一种很好的锻炼！",
  ["4c:5087"] = "你想游到湛蓝市？\012在那之前，\n和我来场小对战吧？",
  ["4c:50c3"] = "是我输了呢。",
  ["4c:50d5"] = "如果是比游泳，\n那一定是我更强。",
  ["4c:5103"] = "没有游泳圈也没问题，\n我抓着海里的宝可梦前进！",
  ["4c:5137"] = "嗯……\n头晕目眩。",
  ["4c:514f"] = "一直像这样飘荡在水面，\n不知不觉就被海浪冲走了。",
  ["4c:5183"] = "虽然这边还看不到对岸，\n但只要越过大海，\011就能抵达湛蓝市。",
  ["4c:51c4"] = "星琪一：初次见面！\n我是星期一的星琪一。",
  ["4c:51f4"] = "这是我们友谊的象征，给！",
  ["4c:522a"] = "星琪一：这个道具可以\n提升飞行属性的攻击力，\012让你的鸟宝可梦携带它\n真是在合适不过了！",
  ["4c:529a"] = "星琪一：我的\n弟弟妹妹们\011在各种地方等你哦。\012你去找找看吧！",
  ["4c:52f5"] = "星琪一：今天好像\n不是星期一呀……\011好遗憾哦。",
  ["4c:5325"] = "这里是40号水道\n湛蓝市   ……   浅葱市",
  ["4c:54a1"] = "这一带的海水很暖，\n感觉全身都放松了。\011来打一场吧！",
  ["4c:54e4"] = "吸、吸水发胀了……",
  ["4c:5500"] = "一直像这样漂着，\n真是太舒服了。",
  ["4c:552b"] = "我有点累了。\n如果我能赢你，\011你就把宝可梦借我吧？",
  ["4c:5559"] = "呼……呼……",
  ["4c:5566"] = "离湛蓝市还很远啊。\n回浅葱市也不轻松……\011该怎么办呢？",
  ["4c:55c0"] = "那座被漩涡围绕的岛屿，\n肯定有什么秘密吧？",
  ["4c:5612"] = "你的实力\n肯定也有什么秘密吧！",
  ["4c:5636"] = "据说在一个暴雨之夜……\012有人看见\n一只巨大的宝可梦\011从漩涡岛飞了出来，\011同时还散落了银色之羽。",
  ["4c:56b8"] = "这片海波涛汹涌，\n想游过去要花很大力气。",
  ["4c:56f4"] = "断、断气了……",
  ["4c:56fe"] = "被潮水搅乱了方向，\n怎么也到不了那座岛。",
  ["4c:572f"] = "你也想要探索\n漩涡岛的秘密吗？",
  ["4c:575e"] = "嗯，不好对付。",
  ["4c:577f"] = "先不说秘密不秘密……\n漩涡岛里面真的很黑啊！",
  ["4c:57b6"] = "我要和朋友一起\n去漩涡岛探险！",
  ["4c:57f9"] = "嗯……原来如此。",
  ["4c:5811"] = "传说在漩涡岛的地下深处\n栖息着一只巨大的宝可梦。\011那到底是怎样的宝可梦呢？",
  ["4c:586c"] = "哎呀？你骑着宝可梦的\n样子很优雅呢。",
  ["4c:5896"] = "我很失望呢……",
  ["4c:58a3"] = "你有没有听过一首\n《骑拉普拉斯的少年》？",
  ["4c:58d8"] = "天气真不错啊……\n令人沉醉。",
  ["4c:5904"] = "呀——",
  ["4c:590b"] = "日照是皮肤的天敌！\012但是我怕会弄脏大海，\n所以没涂防晒霜。",
  ["4c:5962"] = "如果游累了想休息，\n那就站在水中吧。\011这能缓解疲劳恢复活力！",
  ["4c:59c5"] = "真是的！\n你比我更有精神嘛！",
  ["4c:59ea"] = "说起来，我听到岛上的\n洞窟深处传来叫声。",
  ["4c:5a17"] = "一到了晚上啊，\n海星星就会在接近\011水面的地方聚集。",
  ["4c:5a49"] = "……哎呀呀。",
  ["4c:5a54"] = "海星星聚集以后，\n会一起发光哦！\011漂亮得有点诡异！",
  ["4c:5c16"] = "看好了，我钓到的\n宝可梦就是这么厉害！",
  ["4c:5c4a"] = "喔哟，不对劲啊？",
  ["4c:5c62"] = "呵呵呵，靠钓上的宝可梦\n成为最强训练家，\011这就是垂钓者的乐趣！",
  ["4c:5cbf"] = "还是在蓝天之下更舒服！\n心胸也变得更宽广了啊！",
  ["4c:5cec"] = "哇、哈、哈！",
  ["4c:5cf6"] = "与天空的辽阔相比，\n失败太渺小了！渺小！",
  ["4c:5d33"] = "喂！\012这里是我的秘密基地，\n外人别来捣乱啊！",
  ["4c:5d6a"] = "唉，要是当初\n用了月之石就好了……",
  ["4c:5d8d"] = "咦，在收集宝可梦图鉴吗？\n那你一定见过很多\011珍惜的宝可梦吧？\012喂，把图鉴借我看看嘛？",
  ["4c:5dee"] = "这里是42号道路\n缘朱市   ……   卡吉镇",
  ["4c:5e16"] = "雷钵山\n里面有大瀑布的洞窟。",
  ["4c:5e3a"] = "雷钵山\n里面有大瀑布的洞窟。",
  ["4c:5e5e"] = "这里是42号道路\n缘朱市   ……   卡吉镇",
  ["4d:418e"] = "我非常喜欢宝可梦！\012所以我会和宝可梦\n永远永远在一起！",
  ["4d:41d8"] = "这不可能！",
  ["4d:41f6"] = "宝可梦之外的爱好？\012……电台的胡桃小姐姐吧。\n我猜她长得超级可爱。",
  ["4d:423d"] = "你有没有带什么\n稀有的宝可梦啊？",
  ["4d:425e"] = "我的小宝可梦——！",
  ["4d:427d"] = "只要带着稀有的宝可梦，\n我就会觉得无比幸福。",
  ["4d:42aa"] = "你给我听着！\012有个叫{RIVAL}的人，\n居然跑过来戏弄\011我重要的宝可梦！\012可恶——\n我的宝可梦明明很强啊！",
  ["4d:42fa"] = "怎么样？\n我的尼多王很酷吧？",
  ["4d:431c"] = "喜欢什么样的宝可梦，\n是训练家自己的事情。\012并不只有强大的宝可梦\n才算是宝可梦啊。",
  ["4d:4385"] = "我最近陷入低谷了。\n是因为道具不给力吗？\012算了，我要转换心情。\n来场宝可梦对战吧！",
  ["4d:43d4"] = "虽然我输了，\n但是心情变好了。",
  ["4d:43f7"] = "嗯……如果想捕捉\n钓上来的宝可梦，\011我推荐钢铁先生的诱饵球！\012这绝对比高级球\n更容易捕捉成功！",
  ["4d:4459"] = "和宝可梦在一起\n能做很多事情，我很开心！",
  ["4d:4489"] = "输了就不开心了……",
  ["4d:44a2"] = "愤怒之湖发生什么了？\n我还想去露营来着……",
  ["4d:44e5"] = "你也要去愤怒之湖？\n那先陪我玩玩吧！",
  ["4d:4528"] = "玩过头了！",
  ["4d:453c"] = "我要和宝可梦一起野餐，\n你要加入吗？",
  ["4d:456f"] = "这里是43号道路\n愤怒之湖  ……   卡吉镇",
  ["4d:4596"] = "这里是43号道路\n愤怒之湖  ……   卡吉镇",
  ["4d:45bd"] = "有用的公告牌！\012宝可梦的属性之间\n存在属性相克。\012即使有很高的等级，\n也不见得一定能赢。\012好好研究一下自己的\n宝可梦克制什么属性，\011以及被什么属性克制吧。",
  ["4d:488b"] = "啊啊！都怪你！\n蚊香蝌蚪跑掉了啊！\011你怎么赔我啊！！",
  ["4d:48d1"] = "已经够了。",
  ["4d:48e8"] = "跑掉的那只蚊香蝌蚪……\n好家伙，长得可大了，\011起码有个五米吧！",
  ["4d:4937"] = "钓啊，钓啊，拼命钓，\n赢啊，赢啊，一直赢，\011我和宝可梦就是这种关系！",
  ["4d:4995"] = "……嗯，怎么说呢……",
  ["4d:49af"] = "目前100胜，101败。\012输多赢少……\n暂时不和别人对战了。",
  ["4d:49ef"] = "关于传说的鸟宝可梦，\n你知道多少？",
  ["4d:4a1b"] = "哟，还挺厉害！",
  ["4d:4a33"] = "传说的鸟宝可梦\n总共有三种，分别是：\012火焰鸟、闪电鸟、急冻鸟。\012但是我听说除了这三种，\n还有其他传说的鸟宝可梦。",
  ["4d:4aa7"] = "我要赢！\n我一定要赢！",
  ["4d:4ac0"] = "……哐！\n备受打击！",
  ["4d:4adf"] = "不管做什么事情，\n都要具备强大的意念！",
  ["4d:4b0f"] = "我说什么也要弄到\n稀有的宝可梦啊！",
  ["4d:4b3e"] = "啊！\n你的宝可梦不错啊！",
  ["4d:4b61"] = "即使是同一种宝可梦，\n颜色不同价值就会不同！\011哎，不是这样嘛？",
  ["4d:4bbf"] = "这相貌，这身姿，\n一看就知道水平很高！\012我也拥有强大的宝可梦，\n所以我能看出你的实力！",
  ["4d:4c26"] = "……！\n我彻底输了！",
  ["4d:4c49"] = "原来你有这么多徽章啊！\n难怪这么厉害呢！\012说起来，缘朱道馆的松叶\n现在也在继续修行吧。\011他让我吃了不少苦头哦。",
  ["4d:4cd0"] = "你貌似很强啊……\012寻求强大的对手\n是训练家的本能哦！",
  ["4d:4d14"] = "啊，不行不行。",
  ["4d:4d30"] = "经历各种战斗之后，\n大家都能变得更强。\012在成为精英训练家之前，\n我还要经历更多的战斗！",
  ["4d:4d96"] = "这里是44号道路\n前方是冰雪小径",
  ["4d:4daf"] = "这里是44号道路\n卡吉镇   ……   烟墨市",
  ["4d:4feb"] = "正所谓有备无患！\n你有没有好好培育宝可梦？",
  ["4d:5039"] = "哦，我输了。",
  ["4d:504b"] = "我还是回烟墨市的\n冰雪小径重新锻炼吧。",
  ["4d:5087"] = "好！很有精神！\n但是要比精力，\011叔叔我可不会输哦！",
  ["4d:50dc"] = "虽然叔叔还没输，\n但是宝可梦没精神了。",
  ["4d:50fb"] = "叔叔的最爱就是\nHP增强剂！\012太好喝了。不小心就\n把宝可梦那份也喝了。",
  ["4d:5147"] = "我的宝可梦\n对自己的力量充满自信！",
  ["4d:5162"] = "哇哈哈！\n叔叔输了！",
  ["4d:517e"] = "我可不擅长思考，\n平时都是一个劲地进攻。",
  ["4d:51c4"] = "人为什么要爬山？\n……因为山就在那里。\012人为什么要培育宝可梦？\n然是因为宝可梦就在那里！",
  ["4d:5220"] = "失败者也在那里！",
  ["4d:523b"] = "人生最大的喜悦，\n就是与宝可梦的邂逅！",
  ["4d:5276"] = "我正独自在这里\n进行修行……\012让你见识一下成果吧！",
  ["4d:52b1"] = "唔哇！",
  ["4d:52bc"] = "看来必须剃了眉毛，\n去深山老林里修行了……",
  ["4d:530e"] = "你培育宝可梦的时候，\n怀有怎样的信念？",
  ["4d:5339"] = "不愧是你。",
  ["4d:5350"] = "你很重视对宝可梦的培育。\012你们之间的这种牵绊，\n会在关键时刻起作用的！",
  ["4d:53b2"] = "用宝可梦对战的时候，\n你都在想些什么？\012可不能一味地强迫\n宝可梦使出强大的招式哦。",
  ["4d:5405"] = "……是我输了。",
  ["4d:5414"] = "没错，我并不偏好\n过于强大的招式。\012虽然想赢得对战，\n但不能因此就去\011伤害宝可梦。",
  ["4d:5490"] = "这里是45号道路\n再往前走全是山路",
  ["4d:561f"] = "好嘞！\n我就让你好好看看\011山里的宝可梦有多强！",
  ["4d:5652"] = "难过！\n我体会到了你的实力！",
  ["4d:5674"] = "结束了也毫不在意！\n这就是登山男的气概！",
  ["4d:56a5"] = "我也在培育宝可梦，\n你来陪我较量一下吧！",
  ["4d:56d6"] = "什么？",
  ["4d:56dd"] = "全力以赴还是输了，\n那就应该老老实实认了！",
  ["4d:571b"] = "我也在培育宝可梦，\n和我对战吧！",
  ["4d:573b"] = "啊，不甘心！",
  ["4d:5749"] = "我也去过很多道馆，\n其中最喜欢的是满金道馆！\011到处都是鲜花，可漂亮了。",
  ["4d:57aa"] = "这里是46号道路\n前方是山路",
  ["4d:588a"] = "去过深灰道馆吗？\012那里的道馆馆主使用的是\n岩石属性宝可梦哦！",
  ["4d:58c8"] = "听说每当夜幕降临，\n月见山的皮皮们\011就会现身哦。\012但好像不是每天都这样。",
  ["4d:590e"] = "喔！\n居然从城都远道而来啊！\012嗯，真令人怀念啊。\n我年轻的时候也在城都\011进行过训练家修行。\012我觉得我们很聊得来。\n就把我在城都发现的羽毛\011送给你好了！",
  ["4d:59f2"] = "去各种各样的地方，\n经历各种各样的事情。\011这就是旅行的乐趣所在。",
  ["4d:5a47"] = "这里是深灰市。\n深灰即是磐石的灰黑之色。",
  ["4d:5a66"] = "深灰市宝可梦道馆\n馆主：小刚\011如岩石般强大的男人。",
  ["4d:5aa6"] = "……这里贴着一张告示！\012由于正在进行改装，\n深灰科学博物馆闭馆中。",
  ["4d:5af1"] = "……这里贴着一张告示！\012月见山礼品店\n隆重开业！",
  ["4d:5b24"] = "欢迎来到深灰市！",
  ["4d:5c1a"] = "我的虫宝可梦很强！\n做好觉悟吧！",
  ["4d:5c43"] = "被打败了——！",
  ["4d:5c53"] = "还要去找\n更强的虫宝可梦才行！",
  ["4d:5c7c"] = "穿着短裤走进草丛里\n不会被草划伤腿吗？",
  ["4d:5cc2"] = "痛痛痛痛痛……！",
  ["4d:5cd5"] = "在洗澡的时候\n会有强烈的刺痛感！",
  ["4d:5d00"] = "女孩子为什么\n不能喜欢虫宝可梦呢？",
  ["4d:5d1f"] = "不行啊！",
  ["4d:5d29"] = "要是你试着摸摸\n虫宝可梦的小肚肚，\011就能感受到柔软的触感！\011我喜欢的就是这一点！",
  ["4d:5d80"] = "这里是2号道路\n常青市   ……   深灰市",
  ["4d:5da5"] = "这里是地鼠洞穴",
  ["4e:4062"] = "喂！嗝……你等等！\n好好听我讲话！\012别看我现在是这样，\n以前也算是\011捕捉宝可梦的高手！\012你信吗？",
  ["4e:412c"] = "对吧！对吧！\n嗯嗯。",
  ["4e:4174"] = "你这小屁孩！\012我要是再年轻点，\n一定会给你露两手！",
  ["4e:41ce"] = "前不久，这家道馆\n还是没有道馆馆主的。\012最近有个真新镇的年轻人\n成了这里的新馆主。\011……不过现在不在这里。",
  ["4e:423b"] = "你要去挑战馆主吗？\n加油啊。",
  ["4e:4281"] = "哈啊……！\n想要晒会儿太阳，\011结果居然就这么睡着了……\012我做了个很奇怪的梦……\n我梦见催眠貘在吃梦！\011……咦？我手里怎么会\011拿着一个招式学习器咧？\012这简直\n太邪门了！\011给你吧，你快拿去！",
  ["4e:4343"] = "招式学习器42就是……\n食梦哦……\011……呼噜噜……",
  ["4e:4367"] = "我听别人说\n有很多看不见的道具\011散落在常青森林里！",
  ["4e:43ac"] = "这里是常青市。\n常青即是恒久的翠绿之色。",
  ["4e:43d8"] = "常青市宝可梦道馆\n馆主：……\011后面的字看不清了！",
  ["4e:441d"] = "欢迎来到石英高原的\n关口城市——常青市！",
  ["4e:4456"] = "训练家之屋\n强者的聚集地",
  ["4e:44fc"] = "这里是宝可梦联盟\n冠军之路的入口",
  ["4e:455e"] = "只要碰到训练家，\n来场对战就对了！",
  ["4e:4592"] = "输掉了——！",
  ["4e:45b2"] = "对训练家来说，\n对战也是一种问候。",
  ["4e:45f0"] = "你等等！\n和我来场对战吧？",
  ["4e:460c"] = "输了……！",
  ["4e:461b"] = "你好强啊。\n经历过很长久的修行吧。",
  ["4e:4650"] = "这里是1号道路\n真新镇   ……   常青市",
  ["4e:46c2"] = "我也一直都在\n培育宝可梦！\011它们现在是我的保镖！",
  ["4e:46fb"] = "科学的力量好厉害！\012据说现在的电脑连接技术\n已经可以实现\011超越时空的宝可梦交换了。",
  ["4e:4746"] = "这里是真新镇。\n真新即是无垢的纯白之色。",
  ["4e:4778"] = "这里是赤红的家",
  ["4e:4785"] = "这里是大木博士的\n宝可梦研究所",
  ["4e:479c"] = "这里是青绿的家",
  ["4e:482b"] = "加油啊！\n看到陆地了！",
  ["4e:4847"] = "扑通——！",
  ["4e:484e"] = "有个人在红莲镇的\n火山附近装模做样。",
  ["4e:487b"] = "嘿！\012我刚才正想\n涂点防晒霜来着！",
  ["4e:48ab"] = "要被晒伤了啊……",
  ["4e:48c6"] = "我这个年纪\n最怕色素和雀斑了。",
  ["4e:48fc"] = "垂钓也腻了！\n好！来对战吧！",
  ["4e:4921"] = "惨败……",
  ["4e:4931"] = "还是乖乖地垂钓吧……",
  ["4e:49a7"] = "你哪位？\n是宝可梦训练家吧，\011这点倒是一目了然……\012我的名字是青绿！\n曾经当过冠军的男人！\011虽然没当太久……\011都怪赤红那个混蛋，\011就知道给我碍事……！\012说起来，你来干嘛的？\n难道想和我对战？\012……不好意思，\n我现在没那个心情。\012你看看这里的惨况……\012只是一场小型火山爆发，\n就让整个城市蒸发了。\012不论宝可梦对战\n是输还是赢，\011大自然随便哆嗦一下，\011就能让我们一败涂地……\012…… …… ……\n…… …… ……\011算了，\011我毕竟也是训练家。\011要是遇见强者，\011当然也会技痒。\012你要是想找我对战，\n那就来常青道馆吧。\011到时候自然会和你交手的。",
  ["4e:4c48"] = "……这里贴着一张纸条！\012红莲镇的道馆\n搬到双子岛去了\011……夏伯",
  ["4e:4c97"] = "这里是红莲镇。\n红莲即是热情的鲜红之色。",
  ["4e:4d3d"] = "待在水中\n感觉身体都变轻了不少。",
  ["4e:4d5f"] = "讨厌！",
  ["4e:4d68"] = "因为游泳能锻炼全身，\n所以对健康非常有益哦！",
  ["4e:4da5"] = "居然已经取得了这么多\n徽章！来和我对战吧！",
  ["4e:4de5"] = "不——！",
  ["4e:4dea"] = "能在水上使用的秘传招式\n并不只有冲浪哦。",
  ["4e:4e20"] = "就这样游到城都\n是不可能的吧。",
  ["4e:4e58"] = "呜呀——！",
  ["4e:4e60"] = "就算找不到大海……\n江河湖泊也是随处可见的。",
  ["4e:4e97"] = "……这里贴着一张纸条！\012这里是红莲镇的道馆！\n道馆馆主：夏伯",
  ["4e:4fa6"] = "你试过天黑以后\n在海里游泳吗？",
  ["4e:4fd8"] = "哗啦——！",
  ["4e:4fdf"] = "夜间的大海黑洞洞的，\n仿佛能把人吸进去。",
  ["4e:5025"] = "吁吁……\n马上就能……\011吁吁……到浅红市了……",
  ["4e:5058"] = "溺、溺水了——！",
  ["4e:5066"] = "我答应女朋友\n我要游到浅红市……\011吁吁……",
  ["4e:509a"] = "没出息的人\n真让人恶心！",
  ["4e:50b9"] = "比游泳的话就能赢了……",
  ["4e:50d8"] = "不就是往返于\n浅红市和双子岛吗……\011是男人就加油啊！",
  ["4e:5144"] = "游泳……？\n我不太擅长。\011我这是在浅滩泡水呢。",
  ["4e:5191"] = "还以为会赢呢……！",
  ["4e:51a9"] = "就算不太擅长游泳，\n我也依然爱着大海！",
  ["4e:51da"] = "这里正在施工，无法前进。\n要去红莲镇的话，\011还是从真新镇绕过去吧。",
  ["4e:524f"] = "我出了很多汗，\n正打算去游个泳！",
  ["4e:5270"] = "搬掉这块岩石\n到底需要花多久啊……",
  ["4e:52a8"] = "终于施工完毕了！\012这下就可以去垂钓了！",
  ["4e:52e7"] = "这里是19号水道\n浅红市   ……   双子岛",
  ["4e:5310"] = "打算游到双子岛的人\n一定要多加小心！\012……浅红市警署留",
  ["4e:53eb"] = "现在的四天王之中，\n有一个人曾担任过\011浅红道馆的道馆馆主！",
  ["4e:5429"] = "现在的道馆馆主\n是阿桔的女儿，\011而阿桔去当四天王了！",
  ["4e:5479"] = "狩猎地带正在休业。\n毕竟是浅红市名胜，\011感觉若有所失啊……",
  ["4e:54c8"] = "这里是浅红市。\n浅红即是华丽的红粉之色。",
  ["4e:54f0"] = "浅红市宝可梦道馆\n馆主：阿杏\011毒行天下！",
  ["4e:5531"] = "……这里贴着一张告示！\012狩猎地带事务局\n正在休业",
  ["4e:557b"] = "狩猎地带\n园长的家",
  ["4e:5596"] = "狩猎地带的园长\n去遥远的外国旅游了，\011所以正在休业。",
  ["4e:55dd"] = "禁止随地乱扔垃圾！\n垃圾要自己处理！",
  ["4e:56d3"] = "寻找宝可梦的诀窍是：\n每见到一块新草丛\011只管进去就对了！",
  ["4e:5713"] = "嘘——！",
  ["4e:571c"] = "如果我有你那么强，\n对战也会很有意思吧。",
  ["4e:574e"] = "自行车道\n是前往玉虹的捷径！",
  ["4e:577c"] = "…… ……呼！",
  ["4e:5784"] = "如果没有自行车的话，\n就无法走捷径了。",
  ["4e:57c8"] = "这里是18号道路\n玉虹市   ……   浅红市",
  ["4e:587f"] = "喂！\n你是从城都来的吧！",
  ["4e:58a1"] = "强无敌……！",
  ["4e:58b2"] = "城都佬，\n你别太嚣张啊——！",
  ["4e:58d3"] = "哟，哟！\n真是帅气的自行车啊！",
  ["4e:58ef"] = "不是做做样子啊……！",
  ["4e:590d"] = "不管装得有多酷，\n弱者就是逊啦……\011我还要努力啊！",
  ["4e:5957"] = "陪大爷来场高速对战，\n怎么样？",
  ["4e:597a"] = "脚力惊人……",
  ["4e:599c"] = "在自行车道上，\n松手骑车感觉真棒。",
  ["4e:59d3"] = "我们是\n不要命的暴走侠！",
  ["4e:59f1"] = "勇往直前！",
  ["4e:5a0a"] = "事故源自鲁莽，\n大家要引以为戒啊……！",
  ["4e:5aa6"] = "享受坡道！\n自行车道！",
  ["4e:5b3a"] = "这只蚊香泳士\n就是我的搭档！\012这家伙总有一天\n也会变成蛙宝可梦吧？",
  ["4e:5b88"] = "蚊香泳士：呱～呱呱～～！",
  ["4e:5b9b"] = "啊！\n玩老虎机又输了！\012最近连女孩子都\n沉迷于老虎机哦！\011你也去玩玩看吧？",
  ["4e:5c00"] = "最近出现了\n很多臭泥。\012你看，我家门前的池子里\n也出现臭泥了！\012它们到底是从哪来的啊？\n真伤脑筋……",
  ["4e:5c99"] = "嘿嘿嘿！\n这个道馆好的很哇！\011道馆里头美女多哇！",
  ["4e:5cd2"] = "我告诉你一个秘密！\012玉虹大厦里面\n其实有一个秘密后门！",
  ["4e:5d12"] = "那边那个食堂\n正在举行大胃王比赛……\011光是看着就饱了……！",
  ["4e:5d7a"] = "玉虹百货公司商品齐全，\n是最好的百货公司！\011你想要的东西应有尽有！\012……我怎么\n变得跟推销员似的！",
  ["4e:5e18"] = "……我一边走，\n一边看路上的花纹，\011眼睛都看花了！",
  ["4e:5e52"] = "这里是玉虹市。\n玉虹即是梦幻的彩虹之色。",
  ["4e:5e7b"] = "玉虹市宝可梦道馆\n馆主：莉佳\011热爱自然的大小姐！",
  ["4e:5ebb"] = "必能邂逅您梦寐以求的商品\n玉虹百货公司",
  ["4e:5ee6"] = "玉虹大厦",
  ["4e:5ef7"] = "大人和小孩的休闲乐园\n玉虹游戏城",
  ["4e:5f2a"] = "……有用的公告牌！\012在战斗中使用能力防守\n可以保护我方宝可梦，\012防止其受到火、水、电等\n特殊攻击的影响！\012购买道具，\n请认准玉虹百货公司！",
  ["4e:6081"] = "……这里贴着一张告示！\012最近有些没规矩的训练家\n聚集在地下通道\011进行宝可梦对战。\012住在附近的居民\n向我们发来了投诉，\011因此决定关闭地下通道！\012……玉虹市警署留",
  ["4e:614f"] = "锁得紧紧的！\n……打不开！",
  ["4f:407f"] = "你有没有忘记什么东西？",
  ["4f:409d"] = "呀——！",
  ["4f:40a6"] = "老师我呢，\n小时候也经常忘东忘西。",
  ["4f:40e4"] = "只要碰上好天气，\n就不想待在教室里学习。\011真想去操场上做运动啊！",
  ["4f:414c"] = "输掉了……",
  ["4f:4163"] = "虽然学习很重要，\n但是运动也很重要！",
  ["4f:419c"] = "你等一下，\n我要先打电话给妈妈。",
  ["4f:41be"] = "抱歉，妈妈！\n我输掉了！",
  ["4f:41d9"] = "我妈妈总是大惊小怪的，\n所以我要经常联系她。",
  ["4f:421d"] = "来对战吧！\n我不会输的！",
  ["4f:4238"] = "补习班的作业\n忘记做了——！",
  ["4f:4255"] = "你好——！\n这是我昨天刚学会的！",
  ["4f:428a"] = "我们要去紫苑镇的播音塔\n进行社会实践！",
  ["4f:42cc"] = "你太强了啊！",
  ["4f:42e3"] = "已经走累了……\n让我休息一下吧。",
  ["4f:4313"] = "我最擅长的科目是——\n体育！",
  ["4f:432e"] = "糟糕——！\n输了——！",
  ["4f:4349"] = "如果上课让带宝可梦，\n那我就是第一名了！",
  ["4f:437c"] = "这里是15号道路\n浅红市   ……   紫苑镇",
  ["4f:4458"] = "这些令我自豪的宝可梦\n来之不易，陪它们对战吧！",
  ["4f:4495"] = "呜哇……！",
  ["4f:449e"] = "杰尼龟、小火龙，\n再加上妙蛙种子，\011这种组合非常均衡！",
  ["4f:44e8"] = "我的梦想是与心爱的\n鸟宝可梦共同翱翔！",
  ["4f:4517"] = "啪嗒啪嗒——！\n怎么挥手都飞不起来！",
  ["4f:453a"] = "你肯定\n让自己的宝可梦\011记住了秘传招式飞翔吧？\011我好羡慕啊……",
  ["4f:457a"] = "和所有道馆训练家\n都对战过了吗？",
  ["4f:45a0"] = "哇！\n你好强！！",
  ["4f:45bd"] = "如果拥有关都地区的徽章，\n对战时会更有优势哦！",
  ["4f:46a7"] = "看到我那威严的宝可梦，\n还不赶紧跪下！",
  ["4f:46c7"] = "遗、遗憾……",
  ["4f:46e8"] = "既然生而为男人，\n任谁都想称王称霸吧？",
  ["4f:4714"] = "嘻嘻嘻嘻！\n要和皮卡丘对战吗？",
  ["4f:4747"] = "皮、皮卡丘啊！",
  ["4f:4754"] = "不管你拥有\n多少宝可梦，\011最棒的还是皮卡丘！",
  ["4f:4796"] = "动作迅速是\n鸟宝可梦的特长！",
  ["4f:47c2"] = "怎么可能！？\n居然靠速度打败了我！？",
  ["4f:47e0"] = "锻炼得很出色呢，\n你的宝可梦们！",
  ["4f:4809"] = "好好看看我的宝可梦！\n这是多么美妙的色泽呀！",
  ["4f:484e"] = "见鬼——！\n干不过呀！",
  ["4f:4867"] = "把宝可梦整得漂漂亮亮的，\n宝可梦也会很开心呢！",
  ["4f:488b"] = "我要去岩山隧道\n捕捉大岩蛇！",
  ["4f:48be"] = "输掉了！",
  ["4f:48c7"] = "天然的地形乍一看\n好像万年不变。\012其实它们是在\n一点一点地变化着。",
  ["4f:4921"] = "……有用的公告牌！\012没错没错！\n就是栅栏的另外一边！",
  ["4f:4960"] = "这里是13号道路\n往北 …… 寂静桥",
  ["4f:4982"] = "往北 …… 紫苑镇\n往西 …… 浅红市",
  ["4f:4a69"] = "钓鱼要有耐心！\n对宝可梦也要有耐心！",
  ["4f:4a9a"] = "忍！忍！",
  ["4f:4aa3"] = "我这种急性子，\n或许不适合钓鱼……",
  ["4f:4ac2"] = "垂钓的同时还能听广播，\n这真是太幸福了！",
  ["4f:4b0b"] = "因为一直在听广播……\n所以才输了！",
  ["4f:4b2b"] = "你有没有听过\n关都的广播电台？\011这边也有很多节目哦！",
  ["4f:4b74"] = "在我们的日常生活中\n什么东西最重要？",
  ["4f:4ba5"] = "答案稍后揭晓！",
  ["4f:4bc4"] = "我觉得嘛，\n答案是电力！\012不然，发电厂无法运作\n也不会给我们带来\011这么大的恐慌。",
  ["4f:4c6b"] = "你能体会到吧……！？",
  ["4f:4c7d"] = "真能体会到吗——！？",
  ["4f:4c8f"] = "垂钓宝可梦时，\n钓竿上的那种感触！\011就是垂钓的乐趣所在啊！",
  ["4f:4cf7"] = "这里是12号道路\n往北 …… 紫苑镇",
  ["4f:4d18"] = "这里是垂钓名胜",
  ["4f:4de8"] = "绝不能对宝可梦使诈！\n要堂堂正正地对战！",
  ["4f:4e25"] = "哎呀？\n这不可能呀……",
  ["4f:4e40"] = "因为堂堂正正地战斗了！\n所以我绝不后悔！",
  ["4f:4e81"] = "只要穿短裤走在草丛里，\n就会被树叶弄得又刺又痒！",
  ["4f:4ebf"] = "呜呜——，\n输掉了——！",
  ["4f:4ed8"] = "我要在草丛里\n捉到更多宝可梦！",
  ["4f:4f09"] = "…… …… ……\012一直闭着眼睛，\n不知怎么就输掉了……",
  ["4f:4f2f"] = "我能看到……\n你的全部……",
  ["4f:4f5b"] = "你的实力，\n高深莫测……",
  ["4f:4f7a"] = "信赖的力量……\012因为你信赖着宝可梦，\n所以才会这么强吗……",
  ["4f:4fc6"] = "这里是11号道路",
  ["4f:5048"] = "这栋楼很大吧？\n这可是关都的播音塔哦！",
  ["4f:5080"] = "关都地区也会播放\n一些有趣的广播节目哦。",
  ["4f:50a2"] = "很多来自不同城市的人\n都会来这里扫墓。",
  ["4f:50f2"] = "如果想唤醒睡着的宝可梦，\n最好使用宝可梦之笛！\011这是训练家的常识！",
  ["4f:513d"] = "这里是紫苑镇。\n紫苑即是高贵的紫兰之色。",
  ["4f:5162"] = "这里是关都电台。\n广播节目热播中！",
  ["4f:51a7"] = "爱心志愿者聚首于此。\n宝可梦之家",
  ["4f:51c6"] = "这里是灵魂之家。\n宝可梦安眠于此。",
  ["4f:5308"] = "这里是枯叶港，\n关都通往大海的入口。\012甚至会有豪华游轮\n从外国开过来哦。",
  ["4f:5362"] = "我让宝可梦先用重踏压路，\n不过建楼的钱还没着落……",
  ["4f:53bd"] = "腕力：嚎哦～～嚎嚎嚎～～",
  ["4f:53d5"] = "腕力一边吼叫，\n一边用重踏来压路！",
  ["4f:540d"] = "我们关都地区\n也有8枚徽章哦。\012看，那个大型建筑物\n就是枯叶市的道馆了！",
  ["4f:5457"] = "卡比兽正在打鼾，\n似乎睡得很香……",
  ["4f:5477"] = "拿起宝可装置，\n凑近了卡比兽……\012…… …… …… …… ……\n…… …… …… …… ……\012卡比兽醒来了！",
  ["4f:54bb"] = "关都的道馆里聚集了\n很多强大的训练家。\012其中道馆馆主尤为强大，\n别以为可以轻松获胜哦。",
  ["4f:551e"] = "你已经开始收集\n关都的道馆徽章了吗！\012这里有很多\n难缠的训练家，对吧！",
  ["4f:557b"] = "只差一点就能\n征服关都的所有道馆了！\012等你收集到8枚徽章\n一定要和我说一声啊！",
  ["4f:55e6"] = "终于集齐关都的徽章了！\n恭喜你！\012既然你这么努力，\n那我就要送你这个！",
  ["4f:563d"] = "与朋友对战的时候，\n多带不同属性的宝可梦，\011一定会更有优势。\012我觉得关都地区的徽章\n也一定能帮到你的！",
  ["4f:56ac"] = "这里是枯叶市。\n枯叶即是日暮的橙黄之色。",
  ["4f:56da"] = "枯叶市宝可梦道馆\n馆主：马志士\011闪电般的美国人！",
  ["4f:571b"] = "这里是宝可梦发烧友俱乐部\012热烈欢迎任何\n喜欢宝可梦的朋友！",
  ["4f:5741"] = "地鼠洞穴",
  ["4f:5751"] = "枯叶港入口",
  ["4f:5820"] = "在发电厂的事故\n得到解决之前，\011这里禁止通行！",
  ["4f:5864"] = "前方是地下通道\n华蓝市   ……   枯叶市",
  ["4f:5923"] = "这里住着一个女孩子，\n她非常擅长模仿哦。\012她总是学别人说话，\n和她交谈会陷入混乱哦。",
  ["4f:59a3"] = "擅长模仿的少女\n弄丢了她一直以来\011珍爱的皮皮玩偶。\011她现在非常难过。",
  ["4f:59f6"] = "你来自城都吗？\012磁浮列车能发车就好了，\n那样你马上就能回城都！",
  ["4f:5a44"] = "你来自城都吗？\012只要乘上磁浮列车，\n一眨眼就能回到城都呢！",
  ["4f:5a94"] = "当初想挑战道馆训练家，\n进门一看……\012发现自己误闯进\n隔壁那家歇业的道馆了……\011有点尴尬啊……",
  ["4f:5b24"] = "这里是以宝可梦物品\n而闻名的西尔佛公司！\012但是这里曾经\n被火箭队盯上过。",
  ["4f:5b92"] = "我嚼，我嚼……\012发电厂好像出大事了啊。\n我嚼，我嚼……",
  ["4f:5be1"] = "我嚼，我嚼……\012我听说发电厂\n之前出什么大事了……\011我嚼我嚼……吃饱了！",
  ["4f:5c3b"] = "第一次走进某个小巷，\n让人有点兴奋呢！",
  ["4f:5c7b"] = "我听说在常青市\n有个叫训练家之屋的建筑，\011里面聚集了很多训练家！",
  ["4f:5cdb"] = "我听到广播节目\n介绍这个城市了！\012有人夸奖自己住的城市，\n让人有点害羞呢！",
  ["4f:5d4d"] = "这里是金黄市。\n金黄即是辉煌的黄金之色。",
  ["4f:5d7c"] = "金黄市宝可梦道馆\n馆主：娜姿\011超能力淑女！",
  ["4f:5dbf"] = "欢迎各位到场！\n这里是格斗道场！",
  ["4f:5de0"] = "西尔佛公司\n总部大楼",
  ["4f:5dfb"] = "超能力大叔的家",
  ["4f:5e0f"] = "这里是金黄市\n磁浮列车车站",
  ["4f:5f1e"] = "在发电厂的事故\n得到解决之前，\011这里禁止通行！",
  ["4f:5f62"] = "前方是地下通道\n华蓝市   ……   枯叶市",
  ["4f:5f93"] = "……贴了张纸！\n出售房子……\011看起来没人住……",
  ["4f:60b0"] = "如果想去关都发电厂，沿着\n9号道路走到尽头就行。\011但我听说那里出事了。",
  ["4f:610c"] = "喔——！\n你正在收集所有宝可梦？\012这虽然不太轻松，\n但很有意义啊。",
  ["4f:6170"] = "往北有个海角，\n那可是女生们最爱的\011约会胜地哦！",
  ["4f:61b1"] = "呆壳兽：呆～？",
  ["4f:61c2"] = "我和呆壳兽\n是无敌的组合！",
  ["4f:61f1"] = "来吧，呆壳兽，\n快用念力！",
  ["4f:6216"] = "华蓝道馆的馆主是小霞！\n我是她的粉丝！",
  ["4f:623d"] = "有个超级可疑的人\n往华蓝海角那边跑了！",
  ["4f:6271"] = "这边曾经有个洞窟，\n里面栖息着极强的宝可梦！",
  ["4f:62b6"] = "哎呀……？\012我的探宝器\n怎么一直都有反应……？",
  ["4f:62da"] = "这里是华蓝市。\n华蓝即是神秘的水蓝之色。",
  ["4f:630d"] = "华蓝市宝可梦道馆\n馆主：小霞\011俏皮的美人鱼。",
  ["4f:6349"] = "……这里贴着一张告示！\012……奇迹自行车店\n现在已经搬到\011城都地区满金市……",
  ["4f:6394"] = "……这里贴着一张告示！\012这里是和谐正能量的城市，\n请停止盗窃行为。\011……华蓝市警署留",
  ["4f:6403"] = "前方是华蓝海角",
  ["4f:6418"] = "……锁得紧紧的！",
  ["50:4080"] = "我是来岩山隧道\n进行探险的！",
  ["50:40a0"] = "糟、糟糕！",
  ["50:40b4"] = "进入隧道以前\n我的宝可梦已经受伤了，\011要快点去宝可梦中心！",
  ["50:411a"] = "你试过出去野餐吗？\n非常有趣哦！",
  ["50:414f"] = "讨厌——！",
  ["50:4157"] = "我做了很多点心，\n打算和大家一起享用！\011超好吃的！",
  ["50:419d"] = "你怎么这样！\n这里禁止乱丢烟头！",
  ["50:41b5"] = "我就是想提醒一下……",
  ["50:41d1"] = "你没有在吸烟呢，\n是我看错了。",
  ["50:4202"] = "自己的垃圾\n应该要自己带走！",
  ["50:422c"] = "啊啊……\n输掉了啊……",
  ["50:423a"] = "电力很重要，\n自然也很重要呢。",
  ["50:4283"] = "山是——白银——山……\012歌词里的“白银山”\n好像在城都吧？",
  ["50:42d2"] = "唱得忘乎所以，\n疏忽了宝可梦吗……",
  ["50:42eb"] = "战斗需要集中注意力！",
  ["50:430d"] = "告诉你个秘密！\n不过要先来场宝可梦对战！",
  ["50:433b"] = "见鬼！\n输了吗！",
  ["50:4353"] = "渡过那条细长的河流，\n就能看到巨大的发电厂。",
  ["50:437d"] = "这里是9号道路\n华蓝市  ……  岩山隧道",
  ["50:443b"] = "嘿，小子！\n我是火箭队成员！\012我还是来自外国的\n头号训练家！\012我要让发电机\n彻底停止运转，\011把大家吓一大跳，\011让他们陷入恐慌！\012我的作战计划\n才不会告诉你！\012不过，如果你能赢我，\n我就会信守承诺，\011把秘密告诉你！\012嘿，小子！\n来战斗吧！",
  ["50:4574"] = "哦！不！\n真不敢相信！\012你真是颗小蓝莓！\n……抱歉，说错了！\011你真的非常强！\n我打不过你！",
  ["50:45cd"] = "好吧……\n告诉你我的秘密。\012被偷走的机械零件\n藏在华蓝道馆里！\012到水里找一找，\n你就能找到它。\011就在正中间那块！\012但是，别忘了！\012我们火箭队一定会\n好好教训你！\011我在城都的伙伴\011正在赶来这里！",
  ["50:46f3"] = "…… …… ……\n…… …… ……\011什么？\011火箭队已经解散了？\011已经不存在了——？\012哦，不！\n我今后该何去何从——！？",
  ["50:48e7"] = "小霞：你这人怎么回事！\n突然出来碍事！\012你知不知道你这种人\n应该怎么称呼呢！？\011那当然是“电灯泡”！\012…… …… ……\n哎呀？你那些徽章……\011难道是城都的道馆徽章？\012居然集齐了8个，\n看起来你还挺有一手……！\012好吧！\n请来华蓝道馆吧！\011我来做你的对手！\012我是小霞！\n是华蓝市的道馆馆主！",
  ["50:4a2e"] = "如果能连胜我们6人，\n就有豪华奖品！\012那么！\n你办得到吗？",
  ["50:4a83"] = "你很厉害啊。",
  ["50:4a96"] = "我尽力了，\n无怨无悔！",
  ["50:4ab9"] = "我是你的第2个对手！\n接下来可要来真的了！",
  ["50:4ad6"] = "简直不可置信！",
  ["50:4ae9"] = "我尽全力了，\n无怨无悔！",
  ["50:4b0c"] = "你的第3个对手登场！\n我不会让你轻易过去！",
  ["50:4b2a"] = "哎呀呀，我不行了。",
  ["50:4b3d"] = "我尽力了！\n无怨无悔！",
  ["50:4b60"] = "我是你的第4个对手！\n你差不多该\011累趴下了吧？",
  ["50:4b7a"] = "我也输了呢。",
  ["50:4b87"] = "我尽全力了，\n无怨无悔！",
  ["50:4baa"] = "好！我是你的第5个对手！\n来对战吧！",
  ["50:4bc8"] = "你可真了不起！",
  ["50:4bd9"] = "我尽力了，\n无怨无悔！",
  ["50:4bfc"] = "第6个对手是我！\n最后且最强的对手！",
  ["50:4c2c"] = "骗人的吧！",
  ["50:4c3c"] = "我尽全力了，\n无怨无悔！",
  ["50:4c5f"] = "呼、呼、呼……\0126人车轮战里面\n可没有包括我哦。\012我之所以会在这里，\n就是想等你精疲力竭，\011坐收渔翁之利哦！",
  ["50:4ce2"] = "你总不会是不知疲惫的\n不死训练家吧！？",
  ["50:4cfb"] = "非常抱歉……\n我不会再耍诈了！",
  ["50:4d1c"] = "虽然多打了一场，\n但你还是非常精彩地\011战胜了所有人！\012按之前说好的，\n我要给你奖品！",
  ["50:4d7e"] = "……哎呀，\n看了你的战斗后，\011我也跃跃欲试了。\012请一定要与我对战！\n来吧！",
  ["50:4dde"] = "我从来没体验过\n这么精彩的对战！",
  ["50:4e01"] = "真是美妙的战斗！\012你和你的宝可梦们\n真的很强呢！",
  ["50:4e48"] = "这里是海角小屋\n正辉的家",
  ["50:4f79"] = "啊——！\n今天天气也很好——！",
  ["50:4f9c"] = "天空万里无云，\n我的心里却在下雨……",
  ["50:4fb8"] = "一旦下雨，\n就很难生火了。\011啪！",
  ["50:4fe2"] = "嗯……\n怎么办呢……",
  ["50:5001"] = "还是输了……",
  ["50:5012"] = "你看着很强，\n我不太敢和你对战……",
  ["50:5043"] = "我是风之子，\n充满了活力！",
  ["50:505d"] = "咻——！",
  ["50:506a"] = "一年到头都要穿短裤！\n这是我的原则！",
  ["50:50a8"] = "欢迎光临！\n随意参观！",
  ["50:50c8"] = "好烫——！",
  ["50:50d9"] = "关都第一喷火艺人\n就是本大爷！\011……虽然输了宝可梦对战。",
  ["50:5124"] = "月见山广场\n……爬上楼梯近在眼前！",
  ["50:51d5"] = "听说发电厂\n发生了什么意外！",
  ["50:520a"] = "我竟然会输……\n这也是一场意外！",
  ["50:5223"] = "那个……\n我想要去发电厂，\011我记得好像是在\011岩山隧道的附近吧？",
  ["50:525b"] = "我觉得我能赢！\n来和我对决吧！",
  ["50:5293"] = "果然很强啊……！",
  ["50:52ad"] = "传闻说有人在月见山\n目击到了皮皮，\011是在哪里遇见的呢？",
  ["50:52eb"] = "那个……\n我……",
  ["50:52f6"] = "…… …… ……\012……还需要\n更多的修行……",
  ["50:5311"] = "月见山广场\n……爬上楼梯近在眼前！",
  ["50:53ef"] = "我们是训练家帮派——\n“关都宝可梦会”！\011我们要干你丫的！",
  ["50:543f"] = "非、非常抱歉——！",
  ["50:5449"] = "“关都宝可梦会”\n永远不灭！",
  ["50:5475"] = "地下通道是我们的地盘！\n条子居然说封就封！\011真是岂有此理！",
  ["50:54b5"] = "请、请原谅我——！",
  ["50:54c4"] = "居然输给了\n从城都来的人……！",
  ["50:54e8"] = "我来自“关都宝可梦会”！\n还望赐教！",
  ["50:551b"] = "对、对不起——！",
  ["50:552a"] = "从今以后……\n我们尽量不给别人\011添麻烦就是了。",
  ["50:5557"] = "磁浮列车是通过怎样的\n原理运作起来的呢？",
  ["50:557a"] = "我真想看一眼\n磁浮列车…… ……",
  ["50:55a0"] = "磁铁的力量\n真厉害——！",
  ["50:55c4"] = "我们的生活\n需要用电。\012发电厂在努力地\n生产电力。",
  ["50:5615"] = "珍惜用电……！",
  ["50:562e"] = "我听说磁浮列车运行时\n所需要的电力\011是由紫苑镇北侧的\011发电厂供应的。",
  ["50:5675"] = "锁得紧紧的！\n……打不开！",
  ["50:5682"] = "……告示被撕毁了，\n无法阅读……！",
  ["50:571c"] = "这里是关都发电厂",
  ["50:5776"] = "哈——哈、哈、哈、哈！",
  ["50:5780"] = "哈——哈、哈、哈！\n嘻——嘻、嘻、嘻！\011不小心吃了笑菇！",
  ["50:5790"] = "嘻——嘻、嘻、嘻！\n……哈嘻、哈嘻嘻……",
  ["50:57bd"] = "您很喜欢宝可梦吧？\n我也非常喜欢！",
  ["50:57df"] = "这也就是说\n我输了吧！",
  ["50:57fe"] = "我宝贵的宝可梦们……\n我不会忘记你的……",
  ["50:5831"] = "这里是10号道路\n华蓝市   ……   紫苑镇",
  ["50:588f"] = "这里是石英高原。\012宝可梦训练家的顶点！\n宝可梦最高机构，\011宝可梦联盟总部。",
  ["51:400e"] = "水手非常豪爽哦。\012竟然免费送给我\n推动巨大岩石的招式\011——怪力！",
  ["51:4067"] = "湛蓝市位于大海彼岸，\n那里有个人喜欢显摆\011自己拥有的稀有宝可梦。",
  ["51:419a"] = "……之前灯塔的事情\n我必须向你表示感谢。\012……可是对战归对战。\n我要重新自我介绍一下：\012我是道馆馆主——阿蜜，\n使用的宝可梦，\011全都是钢属性。\012……所谓的“钢属性”\n你听说过吗？\012这是最近才发现的\n宝可梦的一种新属性。\012……呃、呃呃。\n那就开始吧？",
  ["51:429c"] = "……作为宝可梦训练家，\n你似乎比我优秀得多。\011你更强大，也更温柔呢。\012……那么按照联盟的规矩，\n我要把徽章交给你。",
  ["51:431b"] = "{PLAYER}从阿蜜那里\n得到了钢铁徽章！",
  ["51:4335"] = "……钢铁徽章拥有\n提升宝可梦防御力的\011特殊效果哦。\012……那个，这个也请收下。",
  ["51:4386"] = "……使用那个招式学习器，\n可以教授“铁尾”。",
  ["51:43b2"] = "呃、呃……\n我也不太会说话，\012……总之请你好好加油吧。",
  ["51:43e3"] = "阿蜜使用的宝可梦\n都具有最新发现的属性\011——钢属性。\012至于这个属性的特点，\n我就不太清楚了。",
  ["51:4432"] = "哎呀，真不得了。\n与钢属性相遇……\011几乎就是与未知相遇啊！",
  ["51:4489"] = "就因为灯塔的宝可梦\n身体状况不是很好，\011道馆馆主阿蜜\011一直在旁边照顾它哦。\012所谓的强大的训练家，\n也要拥有温柔的心呢。",
  ["51:4583"] = "我的宝可梦\n之前也生过一场病，\011于是我就委托缘朱市的药店\011帮忙做了一些药。",
  ["51:45d1"] = "钻角犀兽：咕嗷——！",
  ["51:4624"] = "通往湛蓝市的那片海域\n有4座无人岛。\012如果想要惩罚坏孩子，\n不妨把他带到那些岛上！",
  ["51:4692"] = "只要我做了什么恶作剧，\n爸爸马上就会吓唬我……",
  ["51:472a"] = "说起浅葱就会想到大海！\n说起大海就会想到钓鱼！\012我已经在这里\n垂钓了30年！\012你要不要试试挥舞钓竿\n向大海发起挑战？",
  ["51:47bc"] = "喔、呵、呵！\n又诞生了一名垂钓者！",
  ["51:47e8"] = "不只是大海，\n只要是有水的地方\011随时可以使用钓竿哦！",
  ["51:482d"] = "你说什么！\n你讨厌钓鱼？难以置信！",
  ["51:4860"] = "怎么样？钓到好东西了吗？",
  ["51:48bd"] = "哎呀？\n你的宝可梦看着好柔弱啊。\012这样子怎么可能\n推得动大石头呢？\012快用这个来教它们\n叫做“怪力”的招式！\012但是在对战外使用的话，\n必须拥有满金市的\011道馆徽章才行！",
  ["51:4980"] = "在茫茫大海中，\n只能依赖自己的肉体！\011我对自己的力气很有自信！",
  ["51:49e0"] = "你打算穿越大海吗？\n那么你要听我的建议！\012要注意，从这里到湛蓝市\n一路上到处都有漩涡。\012如果没有掌握特别的招式，\n就没办法穿过漩涡！",
  ["51:4aaa"] = "你的宝可梦有没有学会\n载人渡海的那个招式？",
  ["51:4aec"] = "身在外国的男朋友\n给我送来了巴大蝶，\011而且还携带着信件！\012你想知道写了什么嘛？\n这个嘛……\012果然还是不·能·说！",
  ["51:4bb0"] = "你是打哪来的？\012哎，若叶镇！？\012啊，就是空木博士\n所在的那个城市嘛，\011那可真是远道而来呢。",
  ["51:4d04"] = "哞哞没什么精神……\n必须让它多吃树果……",
  ["51:4d30"] = "我们正在给哞哞喂食物！",
  ["51:4d46"] = "大奶罐：……嗯哞",
  ["51:4d56"] = "叫声有气无力……",
  ["51:4d68"] = "大奶罐：……嗯哞",
  ["51:4d77"] = "要给大奶罐树果吗？",
  ["51:4d91"] = "{PLAYER}\n给出了树果！",
  ["51:4dad"] = "大奶罐\n稍微有点精神了！",
  ["51:4dd1"] = "大奶罐\n变得相当有精神了！",
  ["51:4df0"] = "大奶罐\n变得精气十足！",
  ["51:4e11"] = "{PLAYER}\n没有树果了。",
  ["51:4e24"] = "{PLAYER}没拿出树果。\n大奶罐的眼神中\011流露着悲伤……",
  ["51:4f0d"] = "我的大奶罐\n最近都不产奶了啊。\012咱家的奶可是远近闻名，\n大家以前都很爱喝的……\012只要喂它大量树果，\n就能让它提起精神。\011然后就能挤出许多\011好喝的鲜奶吧……",
  ["51:4fb7"] = "要不要我们牧场\n引以为傲的哞哞鲜奶？\012给宝可梦喝下去\n就可以回复体力哦！\012现在只需¥500！",
  ["51:5031"] = "喝个痛快吧！",
  ["51:5050"] = "哎呀呀，你的钱不够呢！",
  ["51:506f"] = "哎呀呀，你的行李满了！",
  ["51:508e"] = "不需要吗？\n那就下次再来吧！",
  ["51:50b3"] = "那就开始挤奶吧！",
  ["51:50cd"] = "咱家的鲜奶生意\n都已经做到关都去了。\012但如果大奶罐\n产不出好喝的鲜奶，\011我们会很头疼的！",
  ["51:512d"] = "大奶罐终于又能\n产出好喝的鲜奶了！\011这都是托你的福！\012就把这个送给你了，\n拿好了！",
  ["51:519e"] = "那是叫做“打鼾”的招式。\012是只能在睡着的时候\n使出的稀有招式。\011好好想想该怎么用吧。",
  ["51:526c"] = "湖泊中出现了\n红色的暴鲤龙呢！\012暴鲤龙平时很少会\n在那座湖中出现啊……",
  ["51:52de"] = "我喜欢的广播节目？\n应该是宝可梦音乐台吧。",
  ["51:530d"] = "最近总能在广播里\n听见一些笑声……\011感觉有些诡异啊。",
  ["51:545d"] = "宝可梦也好，人也好，\n活着就会经历很多事。\012我也体会过\n各种各样的辛酸。\012作为长者，\n我要教你一点人生经验。\012在你出生之前，\n我就和宝可梦一起生活，\011遇到困难绝不轻易认输。\012现在就让你见识见识\n“严冬柳伯”的能耐！",
  ["51:5583"] = "嗯嗯，\n非常出色的战斗方式。\012只要怀着那颗坚韧的心，\n不管遇到什么困难，\011最终也一定能战胜。\012好！\n这个徽章你就拿去吧！",
  ["51:560b"] = "{PLAYER}从柳伯那里\n得到了冰雪徽章！",
  ["51:5625"] = "只要带着它，\n就可以提高特殊能力。\012还有，\n能让人穿越汹涌的漩涡的\011“潮旋”也能使用了。\012另外，这个是\n老夫送你的饯别礼物。",
  ["51:56bf"] = "这是冰冻之风。\012造成伤害的同时，\n还能降低对方的速度……\012这个招式能让人\n感受到隆冬严寒。",
  ["51:5729"] = "冰雪融化之后……\n春天就会到来。\012今后你还要和宝可梦\n相处很长的一段时间，\011好好珍惜吧。",
  ["51:57b1"] = "我要冻住你的宝可梦，\n使它无法动弹！",
  ["51:57e0"] = "无法动弹的是我啊！",
  ["51:57fd"] = "说起来……有的招式\n能在冰冻状态中使出哦。",
  ["51:5835"] = "卡吉道馆里面滑溜溜的，\n很好玩吧？\012话虽如此，\n我们可不是来玩的哦！",
  ["51:588d"] = "我们真的不是来玩的，\n你现在应该能明白吧?",
  ["51:58ad"] = "这个道馆很棒啊！\n不管什么时候都能\011和宝可梦一起溜冰哦！",
  ["51:58df"] = "我其实知道\n柳伯保持强大的秘诀哦！",
  ["51:58f6"] = "伤脑筋，\n我就把秘密分享给你吧。",
  ["51:5917"] = "柳伯之所以那么强大……\012是因为他每天都去\n经受冰冷瀑布的冲刷，\011既磨砺肉体，也磨砺精神！",
  ["51:597e"] = "如果你想见到馆主柳伯，\n那就得好好思考，\011制定一条溜冰路线哦！",
  ["51:59c4"] = "真是的——！\n如果是滑雪我就赢了……",
  ["51:59e6"] = "不好好研究溜冰路线，\n就去不了想去的地方，\011这是本道馆的乐趣所在。",
  ["51:5a27"] = "这华丽的尾迹，看好了！！",
  ["51:5a44"] = "呀！吓了一跳，\n不小心摔了个屁股蹲！",
  ["51:5a5f"] = "明明是宝可梦对战，\n我怎么炫耀起滑雪技术了！",
  ["51:5a8f"] = "和宝可梦相处了50年的\n柳伯是一名强大的战士！\012据说他最拿手的就是\n使用冰属性的招式\011彻底冻住对手的宝可梦！\012所以你应该尝试\n用燃烧的激情去融化它！",
  ["51:5b45"] = "柳伯很了不起，\n战胜他的你也很了不起！\012这场炽热的战斗\n超越了年龄的差距！",
  ["51:5c32"] = "怎么回事！\n火箭队复活了吗？\012我在愤怒之湖看到了\n几个全身黑的人……",
  ["51:5c83"] = "为了让自己培育的宝可梦\n提前学会一些招式，\011我选择“进化取消”哦。",
  ["51:5ce8"] = "宝可梦进化之后，\n虽然能力会得到提升，\011但学招式的进度会变慢。",
  ["51:5d88"] = "在雷钵山的山体之中\n形成了一个天然迷宫，\011小心不要迷路了哦！",
  ["52:406c"] = "铃铛塔是一座神圣的塔，\n拥有缘朱道馆徽章的人\011才能进行攀登。\012非常抱歉，\n施主请回吧。",
  ["52:40cc"] = "铃铛塔是一座神圣的塔，\n拥有缘朱道馆徽章的人\011才能进行攀登。\012哦！\012这正是缘朱道馆的徽章！\012请走这边。",
  ["52:413f"] = "前面的铃铛塔\n是为了让翱翔高空的\011宝可梦休息而建造的。",
  ["52:417d"] = "刚才铃铛塔震动了！\012这一定是因为\n宝可梦回到了塔顶！",
  ["52:41b9"] = "2座塔对应\n2只宝可梦……\012但是其中一座塔烧毁之后，\n宝可梦也一去不回了……",
  ["52:4304"] = "我是正辉，\n您是……？\012是{PLAYER}啊？\n您来得正好。",
  ["52:434e"] = "我马上就能\n把时光胶囊调整好了。\012宝可梦可以拿去交换，\n这您应该知道吧。\012不过我还发明了\n能和过去的人交换的\011时光胶囊。\012……可是呢，\n要是送过去的玩意儿\011过去的人不认识，\011那电脑可得歇菜了。\012您必须得先把\n过去没有的东西拿下来。\012说白了就是：\n新宝可梦和新招式\011不能用时光胶囊\011进行连接交换。\012估摸着马上就能完事儿。\n等明个儿天一亮，\011全国宝可梦中心的\011时光胶囊应该就能用了。\012我要回满金市去，\n偶尔也得孝顺孝顺爹妈。\012那就拜拜了。",
  ["52:4581"] = "和服女孩跳舞的样子和\n使用宝可梦的样子都很美。",
  ["52:45d6"] = "道馆馆主松叶\n真的很不错啊。\011我就喜欢这种酷酷的感觉。\012而且他的宝可梦\n也非常强大哦。",
  ["52:461c"] = "愤怒之湖……\n出现了大量暴鲤龙……\011我感觉要出大事。",
  ["52:46d3"] = "这是我小时候发生的事：\012有天，天空突然暗了下来。\n我抬头一看，一只巨大的\011宝可梦正在从天上飞过。\012那只像龙又像鸟的宝可梦\n到底是什么呢？",
  ["52:4782"] = "这世上真的有\n那么大的宝可梦吗？\011要是有的话，肯定超级强。",
  ["52:48b8"] = "您的宝可梦好很不错呀，\n能让奴家好好瞧瞧吗？",
  ["52:48e9"] = "真厉害啊！",
  ["52:4903"] = "感谢您愿意陪奴家对战。\n欢迎下次再来。",
  ["52:4938"] = "奴家和珍爱的宝可梦们\n总是在一起跳舞。\011当然，也会抽空培育它们。",
  ["52:4974"] = "真是可惜呢。\n奴家差点儿就能赢了。",
  ["52:4995"] = "跳舞也好，宝可梦也好，\n节奏感很重要。",
  ["52:49c9"] = "奴家的头花儿很漂亮吧？\n呀，您是来对战的？",
  ["52:49f6"] = "奴家好像没有\n可以拿来战斗的宝可梦了。",
  ["52:4a12"] = "说起奴家戴的头花儿，\n每月都会换上不同的花哦。",
  ["52:4a4a"] = "哎呀，有位可爱的训练家。\n是来找奴家对战的吗？",
  ["52:4a7f"] = "真是抱歉，\n奴家刚刚以貌取人了。",
  ["52:4a9e"] = "每天都在努力练习，\n还以为自己已经娴熟了。\011看来奴家还差得远呢。",
  ["52:4ae6"] = "您看奴家这舞如何？\n奴家的宝可梦也很强哦。",
  ["52:4b14"] = "嗯……\n你的宝可梦也很强呢。",
  ["52:4b32"] = "有宝可梦陪在身边，\n还有这么多人\011欣赏奴家的舞蹈，\011奴家一定会继续努力的。",
  ["52:4b94"] = "这些和服女孩舞跳得好，\n宝可梦也用得溜！\012我总是会挑战她们，\n但是完全打不过……",
  ["52:4c1b"] = "小兄弟！\n如果能战胜所有和服女孩，\011我就送你好东西！",
  ["52:4c5e"] = "我刚刚看到了，\n你的宝可梦战斗的姿态\011简直就像跳舞一样优美！\012真是大饱眼福！\012这算我的一点心意，\n你尽管收下就是了！",
  ["52:4cdf"] = "这是叫做冲浪的招式。\n有了它就能在水面上\011悠游自如！",
  ["52:4d19"] = "真希望我的宝可梦也能\n像她们一样高贵优雅。",
  ["52:4d4e"] = "钻角犀兽：咕嗷，咕嗷嗷！",
  ["52:4d68"] = "那边的大叔，\n总是和钻角犀兽在一起！\012他希望学会冲浪的宝可梦\n也能学会跳舞！\012他可能是打算让宝可梦\n进行花样游泳吧……",
  ["52:4dee"] = "和服女孩真漂亮……\012但是想要出来表演的话，\n必须经过严格的训练，\011还要遵守很多规矩！\012不过喜爱的力量是无敌的。",
  ["52:4ebd"] = "这个屏风看起来很贵，\n上面画着各种季节的花！",
  ["52:4f8c"] = "我的伊布\n进化成太阳伊布了。\012可我朋友的伊布\n却进化成了月亮伊布。\012到底是哪里不一样呢？\n明明我们都\011坚持不让伊布进化啊……",
  ["52:5019"] = "如果使用了活力碎片，\n濒死的宝可梦马上就好了。",
  ["52:516b"] = "你来得正好。\012在缘朱市，\n人们从古至今一直\011把宝可梦奉为神明。\012然后还流传着一个说法：\n传说的宝可梦\011会在那些有实力的\011训练家面前降临……\012从出生开始就一直在此\n进行秘密修行的我\011对这个传说深信不疑。\012多亏了多年的修行，\n我现在已经能看见\011其他人所看不见的东西。\012只差一点了……\012我只差一点\n就能见到虹色的宝可梦。\011我几乎能预见这样的未来。\012为了实现我的梦想\n我要继续修行，\011就请你来辅助我吧！",
  ["52:52f4"] = "还不够吗……\012我知道了，\n这个徽章归你了！",
  ["52:532d"] = "{PLAYER}从松叶那里\n得到了幻影徽章！",
  ["52:5343"] = "只要带上幻影徽章，\n等级50以内的宝可梦\011全部都会服从于你。\012另外，叫做冲浪的招式\n也可以使用了。\012接下来要送你这个。",
  ["52:53d6"] = "这是暗影球。\012不只是能攻击对方，\n有时还能降低其特殊防御。\012按你的喜好去使用吧。",
  ["52:542f"] = "这样啊，\012你去过了很多地方，\n见识过很多\011我不知道的事物……\012我还挺羡慕你的。",
  ["52:54a7"] = "与宝可梦一起度过春天、\n夏天、秋天、冬天，\011然后又是一年春……\012就这样，我们与宝可梦\n共度了无数寒暑。",
  ["52:5527"] = "赢了很多次，\n也输过很多次。",
  ["52:554d"] = "宝可梦到底是从哪来的呢？",
  ["52:5568"] = "能不能让我们的宝可梦\n对你造成一些伤害？",
  ["52:5591"] = "哦，还挺厉害！",
  ["52:55a1"] = "我放出来的宝可梦\n全都是幽灵属性的。\012一般属性的攻击\n无法对它们造成伤害！",
  ["52:55e5"] = "我、我要赢——！！",
  ["52:55f3"] = "输、输了——！",
  ["52:5602"] = "越渴望胜利的人，\n越容易获得最终胜利！",
  ["52:5628"] = "隐形地板让你很惶恐吧？\n如果你能战胜我，\011我会给你点小提示！",
  ["52:5669"] = "怎、怎么会！",
  ["52:5674"] = "好吧，\n我告诉你隐形地板的秘密。\012真正的道路\n就在我们眼前！",
  ["52:56d2"] = "听说这里的训练家\n因为一些神秘的原因，\011都在不断地修行。\012如果赢了他们，\n或许能得知缘朱的秘密吧。",
  ["52:573c"] = "哇，{PLAYER}\n居然真的赢了！\012我实在是太害怕了，\n一直都躲在角落里发抖呢。",
  ["52:58cc"] = "喔！你和宝可梦\n正在四处探险啊。\012去探险的话，当然要寻宝！\n你也这么认为吧？",
  ["52:5945"] = "哦！\n你也很懂男人的浪漫啊。\012我看好你！\n这个就给你了！",
  ["52:599e"] = "有些看不见的道具\n掉落在各种地方。\012只要使用探宝器，\n就可以确认一下\011有没有道具\011掉落在你的周围。\012不过，具体的掉落地点\n还是得自己去找出来。\012对了！\n据说缘朱市的烧焦塔里，\011散落了很多宝贝哦。",
  ["52:5a95"] = "这样啊……\n人各有志嘛。",
  ["52:5ab6"] = "缘朱历史……\012要读吗？",
  ["52:5adc"] = "传说中记载：\n缘朱有两座塔，\011分别有不同的宝可梦\011会在两座塔上降临。\012但是其中一座塔失火之后，\n宝可梦也无影无踪了……\012要继续读下去吗？",
  ["52:5b92"] = "还有传说记载：\n有一些宝可梦\011奔驰在缘朱周围。\012据说它们分别是：\n雷的化身、火的化身，\011以及水的化身。\012然而它们拥有的力量\n实在是过于强大，\011只能像疾风一样\011穿越一片又一片草丛……\011以上就是古代的传说。",
  ["53:40f3"] = "我叫小椿！\n是世界第一龙使者。\012即使是面对\n联盟里的四天王，\011凭我的实力也不会输！\011即便如此，你还要挑战吗？\012……好吧，我明白了。\n那就开始吧！\012我也是一名训练家，\n不管对手是谁\011我都会全力应战的！",
  ["53:41cf"] = "我居然输了……\012不敢相信！\n一定是哪里弄错了……",
  ["53:4207"] = "我不承认。\012虽然输家说这种话不合适，\n可是以你现在的心态\011根本就没有资格\011挑战宝可梦联盟。\012……对了！\012在这个宝可梦道馆后面\n有一个洞穴，\011人们称之为龙穴。\012龙使者们想得到认可\n就需要进行一场仪式，\011那就是去龙穴深处\011带回龙之牙。\012你如果也能做到的话，\n那我就会认可你是\011配得上道馆徽章的训练家！",
  ["53:4391"] = "小椿：怎么？\012如果你战胜我\n不是因为一时侥幸，\011那应该可以轻松完成吧？",
  ["53:43f0"] = "小椿：你这个龙之牙不是\n从龙穴带回来的吧？\012别搞这种小动作啊……\n真令人失望。",
  ["53:4451"] = "小椿：我现在可以\n坦诚地认可你的实力了。\012拿走这个招式学习器吧。",
  ["53:44a7"] = "这里面是——\n龙息。\012……不是那个最辣辣椒！\n如果你不需要，\011我也不会强迫你的。",
  ["53:4525"] = "你好像集齐所有徽章了。\012那就前往石英高原的\n宝可梦联盟吧。\012知道该往哪走吗？\n如果从这里出发的话，\011那就要先经过若叶镇。\012然后就用冲浪\n朝着东方一路前进就行。\011不过这段路并不平坦。\012如果你输给宝可梦联盟，\n我饶不了你！\012要不然，我这个\n手下败将情何以堪！",
  ["53:4651"] = "让你好好感受第一个\n与你交战的龙使者有多强！",
  ["53:4696"] = "真遗憾啊。",
  ["53:46a8"] = "你说你见过\n龙使者阿渡……？\011这、这不可能。",
  ["53:46e5"] = "我输给你的可能性\n连百分之一都没有！",
  ["53:4711"] = "不对劲啊。",
  ["53:471d"] = "我体会到了自己的不成熟。\n这也是多亏了你，\011非常感谢！",
  ["53:4753"] = "龙是神圣的生物，\n是充满生命力的宝可梦。\011不要想随便获胜！",
  ["53:47c0"] = "还挺有两下的！",
  ["53:47cc"] = "没错，龙应付不了\n龙属性的招式。",
  ["53:47fa"] = "嗨～！\n未来的冠军！\012你终于来到这里了。\n只差一点了！\011我会为你提供帮助的！\012小椿用宝可梦是\n传说中的生物——\011神圣的龙宝可梦！\012太慢太柔弱的攻击\n是无法伤到它们的！\012……不过，\n我听说它们害怕\011冰属性的招式！",
  ["53:48e8"] = "居然战胜了小椿，\n你真了不得！\012接下来是挑战宝可梦联盟！\n目标是宝可梦冠军！对吧？",
  ["53:4a3f"] = "并不是道馆里的所有人\n都用龙属性宝可梦！\012我的追求就是\n比龙更强的宝可梦！",
  ["53:4aa9"] = "真不愧是你。",
  ["53:4abb"] = "不过，我的宝可梦\n还会变得更强！\012而且训练家也会和宝可梦\n一起得到更多的锻炼！",
  ["53:4b20"] = "我可和小椿一起\n经历过严格的修行。\011怎么可能会输呢！",
  ["53:4b69"] = "……啊，不甘心。",
  ["53:4b83"] = "呼……\n要重新修行了。",
  ["53:4bad"] = "石块掉下去了！",
  ["53:4c64"] = "小椿、阿渡等人\n为了磨炼他们\011身为训练家的实力，\011曾经在这里进行长期修行！",
  ["53:4ca4"] = "迷你龙：龙——",
  ["53:4d20"] = "使用活力块之后，\n濒死的宝可梦就会复活。\011不过友好商店里没得卖！\012另外，你要注意：\n它并不能回复招式点数！",
  ["53:4d9f"] = "黄金喷雾可以\n驱逐弱小的宝可梦。\012在各种喷雾之中，\n黄金喷雾的效果最持久！",
  ["53:4e3b"] = "据说宝可梦联盟在\n遥远的石英高原的深处。\012全国各地优秀的训练家\n都会聚集在那里。",
  ["53:4eb3"] = "我非常想让宝可梦\n学会一个新招式，\011于是就拜托遗忘大叔\011让宝可梦忘了秘传招式！",
  ["53:4fa7"] = "红莲道馆的夏伯\n现在好像独自待在\011双子岛的洞窟里……",
  ["53:4ff1"] = "这里的火山爆发之后\n已经过去一年了。",
  ["53:507c"] = "红莲镇的火山喷发导致\n19号道路被岩石堵塞，\011现在无法通行了。\012话说红莲镇的人们\n没事吧？",
  ["53:50fc"] = "红莲镇的人\n看起来全部都没事，\011太好了，太好了。",
  ["53:51ba"] = "夏伯：喝～～～！\012我以前的道馆\n在红莲镇被烧毁了！\012明明是擅长火属性的\n宝可梦道馆，\011居然被火山烧毁了！\012喝～～～！\012但我会在这个洞窟\n继续承担馆主的职责！\012如果你能战胜我，\n我会给你徽章！\012嘿～～～！\n灼伤药都准备好了吧！",
  ["53:52b8"] = "夏伯：灰……灰常精彩！\n我燃烧殆尽了……！\012深红徽章就交给你了！",
  ["53:52f5"] = "{PLAYER}从夏伯那里\n得到了深红徽章！",
  ["53:530f"] = "夏伯：这次是我输了。\n等红莲道馆重建完成，\011我肯定不会再输了！\011到时候再战一次吧！",
  ["53:538e"] = "夏伯：我的火宝可梦\n会变得更强！",
  ["53:53cb"] = "嗨～！\012……哎呀？\n看来已经结束了。\012抱歉、抱歉！\n因为原本的红莲道馆没了，\011我找了好久呢！\012算了，就算没有我的建议\n你也够强了。\011我就知道你会赢的！",
  ["53:5477"] = "有道馆馆主的地方\n就是宝可梦道馆！\011门面是次要的！",
  ["53:5521"] = "…… …… ……\n居然有人特地来这里……\012我一直这里冥想，\n已经参悟出了新能力！\012我把这个能力\n分给你的宝可梦吧！\011请带上这个。",
  ["53:55b4"] = "……知道吗，\n这是觉醒力量！\012用这个招式攻击的时候，\n可以发挥出宝可梦的潜力！\012不过，招式的属性和威力\n会随着宝可梦而改变。",
  ["53:5649"] = "我正在冥想…… ……",
  ["53:5704"] = "这个愤怒之湖原本是\n暴鲤龙大闹后形成的坑，\011积满雨水就成了湖泊。\012这是我爷爷的爷爷的爷爷\n那一代的事情了。\012之前在这个湖泊里\n还可以垂钓到\011非常不错的鲤鱼王……\012现在到底是怎么了？",
  ["53:5823"] = "之前有群黑衣服的男人\n在附近鬼鬼祟祟的，\011然后湖里就变得不对劲了。",
  ["53:5866"] = "哎呀，\n愤怒之湖变回了以前那样，\011又能钓到新鲜的鲤鱼王了。\012这样一来，\n见到世上最大鲤鱼王的\011梦想也有机会实现了。\012你带了钓竿吧，\n能不能助我圆梦呢？",
  ["53:5914"] = "哦，你带着鲤鱼王啊。\n那就让我看看\011你引以为豪的鲤鱼王吧！",
  ["53:594d"] = "这只真是绝了！\012你的垂钓术值得尊敬！\n作为纪念，请收下这个。",
  ["53:5999"] = "毕竟最要紧的是新纪录，\n这只就当余兴节目吧。",
  ["53:59d7"] = "这只真是绝了！\012虽然很想这么说，\n但还是上一只更大呢。",
  ["53:5a32"] = "我擦！\n这不是鲤鱼王啊。",
  ["53:5a4f"] = "这样啊……\n没钓到值得一看的鲤鱼王。\011下次一定要带来大家伙啊。",
  ["53:5af5"] = "最近好像每个人\n都要去愤怒之湖。",
  ["53:5b3b"] = "最近倒是没几个人\n去愤怒之湖了。",
  ["53:5ca8"] = "哎呀！\012这里的过路费\n要收¥1000。",
  ["53:5ce1"] = "嘿嘿嘿，谢谢惠顾！",
  ["53:5cf2"] = "那你有多少给多少吧。",
  ["53:5d13"] = "最近愤怒之湖\n出了些怪事，\011人们都往那跑，赚大发了！",
  ["53:5d6d"] = "突然就被那些一身黑的人\n赶了出来，真受不了。\012他们落下了这个。\n这玩意儿有点邪门，\011你要的话就拿去吧。",
  ["53:5dff"] = "这道闸口\n是为了那些想要躲开\011草丛的人而设置的。",
  ["54:4005"] = "你在收集关都的道馆徽章？",
  ["54:405a"] = "我听说有个可疑的人\n在四处溜达！\012如果那是小偷，\n我一定要给他一点颜色！",
  ["54:40c3"] = "几年前\n有个小偷闯进来过。",
  ["54:40e7"] = "地鼠：地地鼠",
  ["54:414d"] = "我家的老头子啊，\012以前和很多人交换过。\n现在和宝可梦们\011过着幸福的生活。",
  ["54:418a"] = "啊……\n我真是太幸福了——",
  ["54:419c"] = "袋兽：袋袋，袋袋！",
  ["54:41b5"] = "超音蝠：超音，超音～！",
  ["54:4218"] = "要去发电厂的话，\n沿着9号道路往东走，\011走到道路尽头就行。",
  ["54:4257"] = "磁浮列车时速550公里！\n往返于关都和城都\011只是一瞬间的事情！\012有了它，\n去城都就方便多了！",
  ["54:4453"] = "哦！抱歉！\n你没受伤吧？\011我现在非常忙！\011没空和你说话！\011万一被人发现，\n那就糟了！",
  ["54:44cc"] = "……糟了！\n我已经被你发现了！\011真是个大失误！",
  ["54:44fd"] = "喂！\n忘掉这件事！\011你什么都没看见、\011没听见，也不知道！\012再见，小鬼！\n永远别再见了！",
  ["54:4568"] = "抱歉，我要出去一会儿。\n……道馆馆主小霞留",
  ["54:459a"] = "因为小霞不在，\n我们也出去玩了。\011……道馆训练家留",
  ["54:45cc"] = "小霞：你来了啊！\n电灯泡！\012虽然你好像带着\n很多城都的徽章，\011但别把我看扁了！\012我的水属性宝可梦\n非常强哦！",
  ["54:4664"] = "小霞：还挺厉害……\012我要老老实实地\n认可你的实力……\012这个，拿着。\n是蓝色徽章哦！",
  ["54:46c0"] = "{PLAYER}从小霞那里\n得到了蓝色徽章！",
  ["54:46da"] = "小霞：城都难道\n有很多强大的训练家？\011我是说像你这样的。\012我以后也要出去旅行，\n去挑战强大的训练家！",
  ["54:4762"] = "抱歉，之前溜出去了！\n那就赶紧开始对战吧！",
  ["54:4790"] = "我投降！\n是我输了！",
  ["54:47ae"] = "我要安静地游泳。",
  ["54:47c8"] = "看到我如此优美的泳姿，\n你可别目瞪口呆！",
  ["54:47f7"] = "居然完全没被我吓到……\n你也太冷静了吧……！",
  ["54:4818"] = "虽然你打败了我，\n但还不是安心的时候！\011小霞非常强哦！",
  ["54:486a"] = "哇噗！\012你要先赢过我！\n尽管来吧！",
  ["54:488c"] = "这怎么可能……",
  ["54:489b"] = "最近几年，\n小霞长进了不少哦！\011你可别大意了！\011会 吃 苦 头 的！",
  ["54:48ff"] = "嗨～！\n未来的冠军！\012因为之前小霞她们都不在，\n所以我也跑出去玩了！\011哇哈哈哈哈！",
  ["54:4952"] = "你果然很强呢！\n真是一场精彩的对战！",
  ["54:4a25"] = "去华蓝海角的路上\n有很多训练家。\012他们会测试一下\n过路训练家的实力哦。",
  ["54:4a9e"] = "能够战胜华蓝海角\n那帮训练家的人，\011恐怕整个城市也只有\011一个道馆馆主小霞！",
  ["54:4b49"] = "难得有宝可梦中心建在\n洞窟附近，真令人高兴。",
  ["54:4b7e"] = "发电厂的厂长\n正在寻找强大的训练家。\012听说他想把\n小偷偷走的东西拿回来。",
  ["54:4bf6"] = "我听说，\n火箭队在城都复活了。\011然后好像又光速解散了。\012真的假的啊！",
  ["54:4c64"] = "站在外面不是能看到\n建筑物的屋顶吗？\011那就是发电厂哦！",
  ["54:4e31"] = "居然有小偷\n悄悄混进发电厂，\011真是前所未闻啊……",
  ["54:4e73"] = "从华蓝市\n发来了消息！\012说有个形迹可疑的男人\n在城里到处溜达！",
  ["54:4ed0"] = "你要是愿意的话，\n能给我们帮忙吗？",
  ["54:4ef3"] = "从今以后\n必须加强安保工作！",
  ["54:4f20"] = "发电机的零件\n被别人偷走了！\012缺了那个零件的话，\n新型发电机就废了！",
  ["54:4f89"] = "现在，每天都能输出\n大量的电力！",
  ["54:4fca"] = "这里曾经是一座\n无人发电厂。\012后来为了给磁浮列车\n提供足够的电量，\011就把它改建了。",
  ["54:5040"] = "发电机终于可以\n顺利地启动了！",
  ["54:505f"] = "这前方是发电室，\n厂长就在那里。\011自从机器坏掉后，\011他变得无比悲愤……",
  ["54:50d0"] = "机器修好了，\n厂长的心情也变好了！",
  ["54:5113"] = "毕竟磁浮列车\n需要消耗大量电力。\012如果新型发电机不能运作，\n磁浮列车就只能一直停着。",
  ["54:5176"] = "磁浮列车\n终于可以再次运营了！",
  ["54:51b5"] = "厂长：不、不可原谅！\012居然敢弄坏发电机！\n我的心血都付诸东流了！\012如果我抓到他，\n一定要使出必杀电磁炮\011干他一炮——！！",
  ["54:5259"] = "厂长：我绝不原谅犯人！\n就算哭着求我也没用！\011嘎哈、哈、哈……！",
  ["54:52bf"] = "厂长：哦、哦、哦、哦！！\012这不是我那可爱的\n发电机的零件吗！\011是你帮我找到的吗！",
  ["54:5315"] = "小英雄！！\n太谢谢你了！\011为表示感谢，\011请收下这个招式学习器！",
  ["54:5345"] = "厂长：招式学习器07是\n我的必杀电磁炮！\011这招式非常带劲儿！\012虽然不太好打中……\n但它威力大啊！",
  ["54:53c6"] = "厂长：我的发电机！\n源源不断地输出电力！",
  ["54:5612"] = "哦？\n您认识正辉吗？\011那可是我亲孙子！\012他在城都\n研究那个……电脑来着。\011就让我来看家了！",
  ["54:5676"] = "您要是带了那只宝可梦，\n请一定让我看看……",
  ["54:56a4"] = "哦哦，要给我看吗！\n太谢谢了！",
  ["54:56c8"] = "您没带吗？\n真遗憾哪……",
  ["54:56ea"] = "哦哦，这就是\n{STRBUF}呀！\011真是可爱的宝可梦！\012感谢您特意带来给我看。",
  ["54:5725"] = "太谢谢了！\012这个就给你当谢礼吧！",
  ["54:5752"] = "下次再来玩。",
  ["54:576e"] = "您让我见识了很多\n可爱的宝可梦呢。\011太谢谢了！\012我真是太开心了！\n很庆幸自己活了这么久！",
  ["54:57d5"] = "嗯……\012这好像不是我\n说的那只宝可梦吧……",
  ["54:5804"] = "我孙子正辉提到过：\n有这样一种宝可梦，\011它总是用长舌头舔东西。",
  ["54:5843"] = "对了，我孙子说过：\n有这样一种宝可梦，\011身子圆圆的，\011头上还长了绿色的叶子。",
  ["54:5897"] = "好像有这样的海生宝可梦：\n身上有红珠子，\011身体是星形的。\012一到夜晚就会出现。\n我真想亲眼看看它！",
  ["54:5942"] = "正辉跟我说过：\n有一种宝可梦擅长吼叫，\011对初始训练家十分忠诚。",
  ["54:599b"] = "听说有种可爱的宝可梦\n长了6根尾巴。\012我也好想抱抱\n这样的宝可梦啊——。",
  ["54:59f5"] = "不是有一种宝可梦\n特别受欢迎吗？\012哎呀！就是那个黄身体，\n红脸颊的宝可梦呀！\012我就特别想看看\n它进化之前的样子！",
  ["55:4013"] = "你的宝可梦有没有学会\n被称为秘传的招式？\012当宝可梦处于濒死状态，\n虽然没有精力出战，\011但是秘传招式还是能用的。",
  ["55:4067"] = "使用正辉的电脑，\n1个盒子最多可以\011寄放20只宝可梦哦。",
  ["55:4092"] = "你知道球果吗？\012割开球状树果，\n去掉里面的果肉，\011再装进特殊的装置中。\012接着就可以拿来\n捕捉宝可梦了！\012在精灵球问世之前，\n人们一直是都用球果\011来捕捉宝可梦的哦。",
  ["55:41ed"] = "镇上的呆呆兽都不见了，\012唔，会不会是\n森林之神生气了……？\012反正不是什么好兆头，\n现在最好不要贸然行动。",
  ["55:4276"] = "呆呆兽都回来了…… \012倒是那个来实习的小鬼\n去了栎树林就没回来了。\011他要玩到什么时候啊……\012真是的！\n拿他一点办法也没有！",
  ["55:42ec"] = "不仅驱逐了火箭队，\n还能勇敢地走进栎树林。\012你的气魄令人佩服！\n怎么样！\011和我们一起修行吧？",
  ["55:4359"] = "为什么呆呆兽都消失了，\n是跑出去玩了吗？",
  ["55:439e"] = "说起来，\n我还要向你道谢呀。\012这是我烧制的木炭。\n让火属性的宝可梦携带，\011它一定会很开心的！",
  ["55:440c"] = "呆呆兽也回来了，\n大葱鸭也找到了，\011你也太酷了吧！",
  ["55:445e"] = "大葱鸭：呱——",
  ["55:44c6"] = "呃……没有超级球吗，\n只能用精灵球将就了。\012真想使用\n钢铁先生制作的球哪。",
  ["55:452f"] = "使用超级球的话，\n会比精灵球\011更容易捕捉到宝可梦。\012但是在一些特殊情况下，\n钢铁先生的球才是首选哦。",
  ["55:47ee"] = "哟，您哪位啊？\012这样吗，叫{PLAYER}啊。\n是来拜托我做球儿的？\011不好意思，现在做不了。\012知道火箭队不？\n不知道也没事儿，\011我接着往下说吧。\012叫火箭队的是一帮\n强迫宝可梦做坏事儿、\011吊儿郎当的混子。\012本来在3年前，\n应该已经解散了的……\012就是他们这帮人，\n在井里切了呆呆兽的尾巴，\011大量往外倒腾。\012所以我要过去\n教训教训丫的！\012好嘞！等着我，呆呆兽！\n纯爷们儿钢铁来救你们了！",
  ["55:4990"] = "钢铁：哟，{PLAYER}，\n您在井里的表现可忒棒了！\012我很欣赏您！\n看到您这样的训练家，\011我就特别想制球儿。\012不过现在手边只有这个， \n您尽管收下！",
  ["55:4a44"] = "钢铁：我能用球果儿\n制作特制的球儿。\012调查一下外面的球果树，\n收集了果实再过来，\011那样我就能做成球儿了。",
  ["55:4ab1"] = "钢铁：哦哦，\n这不是带着球果儿嘛！\012好嘞，\n我要制球儿了！",
  ["55:4af4"] = "钢铁：完成制球儿\n估摸着要1天的时间。\011到时候您再来拿吧。",
  ["55:4b37"] = "钢铁：这样吗……\n还挺失望。",
  ["55:4b53"] = "钢铁：我在制作呢，\n别碍事儿！",
  ["55:4b76"] = "钢铁：哦，{PLAYER}吗？\n这会儿球刚做好，\011拿去！",
  ["55:4ba5"] = "钢铁：这可是优良成品！\012试着去和宝可梦对战，\n看看能不能用它捕捉！",
  ["55:4bde"] = "呆呆兽都不见了……\n怎么办……\011是不是被坏人带走了？",
  ["55:4c1a"] = "爷爷你在哪啊……？\n我一个人好孤单……",
  ["55:4c38"] = "爸爸送给我的\n呆呆兽回来了！\011尾巴也会再长出来的！",
  ["55:4c7e"] = "爸爸在一家叫西尔佛的公司\n进行新型精灵球的\011研究工作。\012这段时间，就由我和爷爷\n还有呆呆兽一起看家。",
  ["55:4cdb"] = "呆呆兽： ……\n…… …… 呀呆？",
  ["55:4cee"] = "……年轻时的大木博士？",
  ["55:4d03"] = "供奉着森林之神。",
  ["55:4e83"] = "我是阿笔！\n虫宝可梦的相关知识，\011我不会输给任何人！\012毕竟我将来打算\n靠虫宝可梦的研究\011去成为伟大的博士！\012所以，我就让你见识见识\n我的研究成果吧。",
  ["55:4f26"] = "哇，好强！\n你很懂宝可梦啊！\012啊啊——\n我的研究还差得远呢！\012嗯！我知道了。\n这个徽章拿去吧！",
  ["55:4f8c"] = "{PLAYER}从阿笔那里\n得到了昆虫徽章！",
  ["55:4fa3"] = "你知道昆虫徽章的\n特殊效果吗？\012只要带上昆虫徽章，\n就算是别人送的宝可梦，\011只要等级在30以内\011都会乖乖听话哦！\012还有，学会了居合斩的\n宝可梦也可以在对战外\011使用那个招式了哦！\012另外，这个也拿去吧！",
  ["55:5060"] = "招式学习器49里面\n含有“连斩”哦！\012只要没有打偏，\n威力就会变得越来越大！\012战斗拖得越久，\n形势就会越有利！\012怎么样，很厉害吧！？\n这可是我的发现哦！",
  ["55:50fe"] = "虫宝可梦非常深奥，\n仍然还有很多东西\011需要不断地进行研究。\012你也试着钻研钻研\n自己喜欢的宝可梦吧？",
  ["55:515e"] = "虫宝可梦进化得特别快！\n知道吗？这就意味着它们\011变强的速度会更快！",
  ["55:519d"] = "只是进化还不行吗……",
  ["55:51b9"] = "宝可梦进化以后\n是真的会变强哦！",
  ["55:51e7"] = "我要让你知道\n帅气又强大的虫宝可梦\011到底有多迷人！",
  ["55:521a"] = "反而是我明白了你有多强！",
  ["55:5239"] = "明明长得这么酷，\n怎么会有这么多女孩子\011讨厌虫宝可梦啊，\011真是莫名其妙。",
  ["55:527e"] = "你说你拯救了呆呆兽？\n那可真有你的。\012不过我培养的宝可梦\n也很强哦！",
  ["55:52da"] = "呜呜呜……",
  ["55:52e4"] = "不学点更强的招式\n就赢不了呢……",
  ["55:530f"] = "久美：哎！\n你是来挑战馆主的吗？\011那种事情别想别想——",
  ["55:5341"] = "久美和留美：哎哟哟——",
  ["55:5362"] = "久美：好强——好厉害——",
  ["55:537d"] = "留美：哎！你是来\n挑战馆主的吗？\011那就赶快开战吧——",
  ["55:53ae"] = "久美和留美：哎哟哟——",
  ["55:53cf"] = "留美：虫宝可梦输掉了，\n好难过啊——",
  ["55:53fc"] = "嗨，\n挑战者！\012虽然阿笔年纪不大，\n但是虫宝可梦的相关知识\011不会输给大人！\012没有提示，心里没底吧？\n好嘞，那就交给我吧！\012没错！\n虫宝可梦讨厌火！\012飞行属性的招式\n也是效果绝佳！",
  ["55:54bf"] = "太厉害了吧！\n年轻训练家之间的\011激烈对战……\012宝可梦世界的未来\n充满光明！",
  ["56:400f"] = "宝可梦刚捉来或许很弱，\n但只要好好培养，\011总有一天会变强的。\012我觉得最重要的\n还是对宝可梦的爱。",
  ["56:4090"] = "虽然宝可梦可以携带道具，\n但是像伤药或解毒药这种\011人工制造的道具，\011它们好像用不来呢。",
  ["56:41e0"] = "我就是桔梗道馆的\n道馆馆主阿速！\012世人都说\n飞行属性宝可梦没什么，\011来一发电击就完蛋……\012他们如此小瞧鸟宝可梦，\n我无法原谅！\012我一定要让他们明白\n能在空中翩翩飞舞的\011鸟宝可梦到底有多厉害！",
  ["56:42b7"] = "……可恶，\n父亲宝贵的宝可梦居然……\012好吧，\n这个拿去吧！\012这是宝可梦联盟认可的\n飞翼徽章！",
  ["56:431c"] = "{PLAYER}从阿速那里\n得到了飞翼徽章！",
  ["56:4335"] = "有了飞翼徽章，\n你的宝可梦的\011攻击力就会上升！\012另外，如果有宝可梦\n记住了叫做闪光的招式，\011那么它在对战之外\011也可以使用闪光了。\012这个也拿去吧。",
  ["56:43b5"] = "使用招式学习器，\n宝可梦就能立刻\011学会招式了！\012不过是一次性的，\n用之前要好好考虑一下。\012顺带一提，招式学习器31\n里面含有“掷泥”。\012降低对方命中率的同时\n会给予对方伤害，\012换句话说，\n这是一个攻守兼备的招式。",
  ["56:44a2"] = "接下来，\n有道馆的城市还有很多，\011你不妨去试试身手。\012而我，为了成为最强的\n鸟宝可梦专家，\011要和宝可梦一起变强！",
  ["56:453a"] = "我们的口号是永不言败！！\012聚集在这里的人都希望用\n鸟宝可梦来成为最强，\011所以从早到晚都在特训！\012你尽管来吧——！",
  ["56:459c"] = "哐——当！！",
  ["56:45a4"] = "阿速先生\n可不是吃素的！\012你也就只能打赢我而已，\n不要太得意忘形！",
  ["56:45ec"] = "让我确认一下你有没有资格\n去挑战阿速先生吧。",
  ["56:4620"] = "真的假的——！？",
  ["56:4634"] = "居然输给了菜鸟训练家，\n我真是太丢人了……",
  ["56:4666"] = "嗨～！\n虽然我不是训练家，\011但是建议还是能给几个的！\012相信我吧！\n只要信任我说的话，\011成为冠军也不再是梦！\012是吗，你愿意听我说的！\n真的吗！\012草属性面对飞行属性\n非常不利，\011要多加小心！",
  ["56:4735"] = "真是精彩的对战！\n保持这个势头，\012一路成为宝可梦冠军！",
  ["56:48a8"] = "我叫初始～！\n宝可梦很～不错吧！\012想要变强的话，\n我会教你各种知～识。\012想了解什么？\n想知道怎么做\011才会变强噜？",
  ["56:492a"] = "那么～\n我就来指导你吧～！\012对战的时候\n同行宝可梦之中\011首位的那只宝可梦\011会头一个出场～！\012调整一下列表的排序，\n对战会变得更顺利噜～！\012还有什么想问的噜？",
  ["56:49be"] = "那么～\n你想知道怎么做\011才能成功培育宝可梦？",
  ["56:49e8"] = "那么～\n我就来指导你吧～！\012对战的时候，\n只要宝可梦露过一次脸\011就能分享到经验值～！\012把弱小的宝可梦放到\n同行宝可梦的首位，\011对战的时候立刻替换掉！\012这样弱小的宝可梦\n也能得到成长噜～！",
  ["56:4a9e"] = "哇～你是好学生！\n已经没东西可以教你了噜～\012请你和捕捉到的宝可梦\n好好相处哦～！",
  ["56:4aed"] = "我把老师说的话\n写在笔记本上背下来了！\012黑板上写的东西，\n也要抄到笔记本上才行……",
  ["56:4b47"] = "我把自己喜欢的宝可梦\n送给了旁边的小朋友！",
  ["56:4b74"] = "哎呀？传送过来的宝可梦\n携带了道具！？",
  ["56:4ba6"] = "……让宝可梦携带树果，\n它就会自动回复体力。\012还有很多可以\n让宝可梦携带的道具……\012老老实实做笔记\n可真辛苦……",
  ["56:4c1f"] = "黑板上写着：\n宝可梦对战时\011可能会出现的\011异常身体状况。",
  ["56:4c6b"] = "中毒的话，\n体力会不断地减少。\012对战之后毒素不会消退，\n每走几步体力就会减少。\011用解毒药来治疗吧。",
  ["56:4ced"] = "麻痹的话，速度会降低，\n有时还会使不出招式。\012即使战斗结束了，\n也会一直处于麻痹状态。\011用解麻药来治疗吧。",
  ["56:4d4f"] = "睡着了的话，\n这段时间会无法攻击。\012即使战斗结束了，\n也会一直处于睡眠状态。\011用解眠药来治疗吧。",
  ["56:4dc2"] = "灼伤时体力会不断减少，\n攻击力也会降低。\012即使战斗结束了，\n也会一直处于灼伤状态。\011用灼伤药来治疗吧。",
  ["56:4e38"] = "冻住了的话，\n会变得无法行动。\012即使战斗结束了，\n也会一直处于冰冻状态。\011用解冻药来治疗吧。",
  ["56:4ea3"] = "是这个孩子的笔记本……\012用精灵球\n捕捉到宝可梦之后，\011一次可以带6只同行。\012还要往下看吗？",
  ["56:4f04"] = "投出精灵球之前，\n用宝可梦的招式\011使对手陷入中毒、灼伤\011等状态，会好捉很多！\012还要往下看吗？",
  ["56:4f74"] = "另外，有些宝可梦的招式\n能让对手陷入混乱。\012一旦陷入混乱状态，\n有时会不小心\011误伤到自己。\012只要脱离一次战斗，\n就能恢复原样……\012还要往下看吗？",
  ["56:4ff4"] = "像这样培育捕捉的宝可梦，\n并让它们进行对战的人\011就是宝可梦训练家。\012训练家的目标是\n战胜各个道馆中\011那些强大的训练家！\012然后就是……\n一片空白！\012少年：哎嘿嘿……\n接下来就啥也没写了……",
  ["56:5167"] = "她总是把自己喜欢的食物\n拿来取名字。\012我是在说我女儿\n给宝可梦取的昵称哦。",
  ["56:51cb"] = "我的波波\n名字是小草莓！",
  ["56:51e9"] = "小草莓：波波～！",
  ["56:52c2"] = "{PLAYER}，好久不见。\n空木博士之前\011委托我来找你哦。\012其实呢……\012他希望你能\n带上这个宝可梦蛋！",
  ["56:5332"] = "根据空木博士的调查，\n宝可梦好像要在蛋中\011培育一段时间\011才会孵化出来！\012而且边上还要时常有\n健康的宝可梦陪着，\011否则也不行。\012这种事情只有\n{PLAYER}能办得到，\011所以就拜托你了！\012等它孵化出来，\n记得联系空木博士哦！",
  ["56:5400"] = "你身上带了很多宝可梦，\n已经带不下了。\011那么，我就在这里等你。",
  ["56:545f"] = "别、别这样……\n这可是空木博士的请求啊！",
  ["56:547f"] = "{PLAYER}，\n你愿意带上这个蛋吗？",
  ["56:549a"] = "将捉到的宝可梦\n寄放进电脑的系统，\011好像是叫正辉的人创建的。",
  ["56:54cd"] = "大概是3年前的事情了。\012有一帮叫做火箭队的人，\n他们捕捉宝可梦，\011到处为非作歹。\012但是，邪不压正！\n在一位少年的奋战之下，\011他们最后被迫解散了！",
  ["56:5549"] = "宝可梦相当聪明呢。\n如果训练家不值得尊敬，\011他们就不会听话。\012如果没有道馆徽章，\n他们会无视命令擅自行动！",
  ["56:5628"] = "和别人交换过来的宝可梦\n会获得更快的成长！\012……但是如果没有徽章，\n它就会变得不听话。",
  ["56:56c7"] = "欢迎来到能看又能摸的\n阿露福遗迹！\012请您务必亲手摸摸\n能移动的石板哦！",
  ["56:5712"] = "哦，你是来遗迹学习的？\n将来一定能当博士啊！",
  ["56:574e"] = "石板上有画，而且还能推！\n那到底是什么东西呢？",
  ["56:5814"] = "这一带可是垂钓名胜哦。\n看着大家都在垂钓，\011你也跃跃欲试吧？\012要是愿意的话，\n我就把我的钓竿给你吧？",
  ["56:5879"] = "我很开心！这样一来，\n你也能加入垂钓者的行列！",
  ["56:58ac"] = "垂钓是最好的！\012只要是有水，\n管他是大海还是小河，\011要尽情使用钓竿哦！",
  ["56:58fd"] = "哎哟哟，\n那就很遗憾了……",
  ["56:591e"] = "哟，少年！\n垂钓的状态如何？",
  ["56:5943"] = "嗯，我好困扰啊……\n该让宝可梦携带什么呢？\012还是携带可以\n强化攻击力的道具吧。",
  ["56:5a70"] = "喂——说你呢！\012能拜托你把这只\n持有信件的宝可梦\011交给我的朋友吗？\011他在31号道路。",
  ["56:5adb"] = "谢谢！\012我的朋友是个胖胖的男人，\n他总是在打瞌睡，\011应该是很好找的！",
  ["56:5b4b"] = "{PLAYER}收下了\n持有信件的宝可梦！",
  ["56:5b69"] = "信件可以随便读，\n但千万别弄丢了！\011是31号道路哦！拜托了！\012……哎呀！\n我听别人说，\011有棵奇怪的树堵在路中间。\011现在已经能通行了吗？",
  ["56:5be9"] = "你好像带不下\n更多宝可梦了……",
  ["56:5c07"] = "是吗……\n没办法啊……",
  ["56:5c1e"] = "谢谢！\n你顺利地完成了寄送任务！\011我要给你谢礼！",
  ["56:5c6c"] = "我的朋友当时在睡觉吧？\n他这人就知道睡觉！",
  ["56:5c9d"] = "我听说有棵树把路堵住了，\n和它搭话，它还会扭起来。\012我还听说，用杰尼龟喷壶\n给它浇水，它就会发狂。",
  ["56:5d2d"] = "我喜欢收音机播放的\n宝可梦摇篮曲。",
  ["56:5ef2"] = "今天是星期{STRBUF}。\n将举办捕虫大赛！\012规则很简单！\012就是比一下\n谁能只带一只同行宝可梦\011捕捉到最强的虫宝可梦。\012要参加吗？",
  ["56:5fa4"] = "这是大赛专用球，\n请拿好！",
  ["56:5fce"] = "{PLAYER}得到了\n20个公园球！",
  ["56:5fe9"] = "谁捉到的宝可梦最强，\n谁就是第一名！\012限制时间是20分钟！\012另外，公园球用完时\n比赛会强制结束！\012捕捉到的最后一只宝可梦\n会归参赛者所有！\012请努力捕捉\n强大的宝可梦吧！",
  ["56:60cd"] = "哎呀？\n你带的宝可梦不止1只！\012那就用排头的宝可梦……\n{STRBUF}\011参加本次比赛？\011这样可以吗？",
  ["56:613e"] = "那么剩下的宝可梦\n将会暂时寄放在此处！",
  ["56:6172"] = "{PLAYER}将宝可梦\n寄放在了工作人员那里！",
  ["56:619e"] = "决定好在大赛\n出战的宝可梦之后，\011再来找我吧。",
  ["56:61e3"] = "这样吗，\n请下次再来参加！",
  ["56:620f"] = "哎呀？\n排头的宝可梦\011好像无法战斗呢。\012请替换宝可梦之后\n再来吧。",
  ["56:6283"] = "哎呀？\n无论同行还是电脑的盒子\011好像都已经满了。\012现在这个状况，\n无法带走捉到的虫宝可梦。\012请对同行与电脑的盒子\n进行整理，之后再过来吧。",
  ["56:6326"] = "哎呀？\n排头的宝可梦\011好像是颗蛋呢。\012请替换宝可梦之后\n再来吧。",
  ["56:63a1"] = "剩余的时间\n还有{STRBUF}分钟。\011已经要结束了吗？",
  ["56:63e2"] = "这样吗，\n那就请你\011去上面的闸口\011等待结果公布吧。",
  ["56:642a"] = "这样吗，\n那就请你\011好好利用剩下的时间！",
  ["56:6456"] = "今天的比赛\n已经结束了，\011请下次再来参加！",
  ["56:649b"] = "公园里有时会\n举办捕虫大赛。\011到时候你也来参加吧？",
  ["56:64df"] = "下次捕虫大赛\n是在什么时候举行呢？",
  ["56:6515"] = "捕虫大赛的\n举办日是……\011周二、周四、周六。\012参赛者能获得奖品，\n而且捕捉的虫宝可梦\011也会变成自己的宝可梦。",
  ["56:660d"] = "遗迹的建造者是谁？\n又是为什么而建造的呢？",
  ["56:6648"] = "路上有棵奇怪的树对吧？\n可能就是因为这东西，\011来遗迹的游客变少了。",
  ["56:69c0"] = "今天是星期{STRBUF}。\n将举办捕虫大赛！\012规则很简单！\012就是比一下\n谁能只带一只同行宝可梦\011捕捉到最强的虫宝可梦。\012要参加吗？",
  ["56:6a70"] = "这是大赛专用球，\n请拿好！",
  ["56:6a9a"] = "{PLAYER}得到了\n20个公园球！",
  ["56:6ab5"] = "谁捉到的宝可梦最强，\n谁就是第一名！\012限制时间是20分钟！\012另外，公园球用完时\n比赛会强制结束！\012捕捉到的最后一只宝可梦\n会归参赛者所有！\012请努力捕捉\n强大的宝可梦吧！",
  ["56:6b99"] = "哎呀？\n你带的宝可梦不止1只！\012那就用排头的宝可梦……\n{STRBUF}\011参加本次比赛？\011这样可以吗？",
  ["56:6c0a"] = "那么剩下的宝可梦\n将会暂时寄放在此处！",
  ["56:6c3e"] = "{PLAYER}将宝可梦\n寄放在了工作人员那里！",
  ["56:6c6a"] = "决定好在大赛\n出战的宝可梦之后，\011再来找我吧。",
  ["56:6caf"] = "这样吗，\n请下次再来参加！",
  ["56:6cdb"] = "哎呀？\n排头的宝可梦\011好像无法战斗呢。\012请替换宝可梦之后\n再来吧。",
  ["56:6d4f"] = "哎呀？\n无论同行还是电脑的盒子\011好像都已经满了。\012现在这个状况，\n无法带走捉到的虫宝可梦。\012请对同行与电脑的盒子\n进行整理，之后再过来吧。",
  ["56:6df2"] = "哎呀？\n排头的宝可梦\011好像是颗蛋呢。\012请替换宝可梦之后\n再来吧。",
  ["56:6e6d"] = "剩余的时间\n还有{STRBUF}分钟。\011已经要结束了吗？",
  ["56:6eac"] = "这样吗，\n那就请你在这里\011等待结果公布吧。",
  ["56:6ee7"] = "这样吗，\n那就请你\011好好利用剩下的时间！",
  ["56:6f12"] = "今天的比赛\n已经结束了，\011请下次再来参加！",
  ["56:6f57"] = "有些宝可梦\n只能在公园里找到哦！",
  ["56:6f80"] = "干泰：居然能赢过我……\n你很有本事啊！",
  ["56:6fab"] = "干泰：能不能遇见宝可梦，\n也是要看运气的。",
  ["56:6ff6"] = "辉奇：哇，羡慕嫉妒恨！\n我这次状态不佳！",
  ["56:7027"] = "辉奇：难道说宝可梦越大\n越容易获得第一名？",
  ["56:7049"] = "小建：真是精彩！\n我要重新培育宝可梦！",
  ["56:707d"] = "小建：如果是特殊颜色的\n宝可梦，得分会更高！",
  ["56:70c1"] = "彰宏：第一名是你啊！\n你捉的是什么宝可梦啊？",
  ["56:70f1"] = "彰宏：只要能找到想要的\n宝可梦，我就满足了。",
  ["56:7135"] = "贞夫：恭喜！\n我开始尊敬你了！",
  ["56:7163"] = "贞夫：之前\n连飞天螳螂都捉到了，\011结果却没成为第一名……",
  ["56:7197"] = "雄一：你捉到的宝可梦\n真是太酷了！",
  ["56:71c4"] = "雄一：等级越高\n越容易被评为第一名……\011不过得分点也不只这一个。",
  ["56:7232"] = "里美：你是第一名！？\n太厉害了吧！！\012下次要不要和我一起\n去捕捉虫宝可梦？",
  ["56:727f"] = "里美：我超级喜欢\n虫宝可梦哦！",
  ["56:729f"] = "友道：在捉虫宝可梦方面\n我居然输给了别人……",
  ["56:72d0"] = "友道：我听说曾经有人\n靠绿毛虫当上第一名！",
  ["56:7302"] = "康太：下次我一定会赢！",
  ["56:7327"] = "康太：嗯？我的得分\n不应该只有这么点啊……",
  ["56:7356"] = "智行：请你教我秘诀！\n我真的很想学！",
  ["56:7396"] = "智行：虽然学了很多……\n但光靠学习还是赢不了的。",
  ["56:74dd"] = "哎呀？\n您的行李好像装满了……\012我们可以先帮您保管，\n但仅限今天一天。\011请整理好行李再来！",
  ["56:754c"] = "您是{PLAYER}吧？\012给，\n这是帮您保管的奖品。",
  ["57:4122"] = "嘿～！\n我是小茜！！\012大家都在玩宝可梦，\n所以我也跟着玩起来了。\011宝可梦真是越看越可爱！\012哎～你是来挑战的？\n那你必须清楚，\011我可是强得不得了哦！",
  ["57:41a5"] = "呜呜……\012……哇——！！\n过分，过分！！\012我才没使小性儿呢！！\n像你这种小孩儿……",
  ["57:41f5"] = "哇——！！\012哇——！！\012呜呜呜……\n太过分了！！",
  ["57:4223"] = "呜……\012怎么了？你还想怎么样？\n啊，徽章？\012抱歉，我忘了。\n给，这是标准徽章，\011你很想要，对吧！",
  ["57:4278"] = "{PLAYER}从小茜那里\n得到了标准徽章！",
  ["57:4290"] = "如果持有标准徽章，\n即使不在战斗中，\011也可以使用怪力了。\011宝可梦的速度也会上升。\012然后还有这个！",
  ["57:4307"] = "这是叫做迷人的招式，\n可以让宝可梦最大限度地\011发挥出自个儿的魅力，\011特适合我这种可爱的姑娘！",
  ["57:4365"] = "哼！\n哭出来以后舒服多了！\012下次再来玩儿吧！\n拜拜！",
  ["57:43a0"] = "别因为我是女孩\n就掉以轻心哦！",
  ["57:43bb"] = "输掉了……\n好像是我太不小心了。",
  ["57:43db"] = "在宝可梦的世界中，\n是雌性宝可梦厉害\011还是雄性宝可梦厉害呢？",
  ["57:441b"] = "比起强大的宝可梦，\n我更喜欢可爱的宝可梦！\012不过我的宝可梦，\n既强大又可爱！",
  ["57:4469"] = "啊，不行不行！",
  ["57:447a"] = "我一直都在努力练习，\n希望有一天能打败小茜。\011看来现在还差很远呢……\012骗你的啦！\n这次输了，下次就要努力！",
  ["57:44de"] = "哎呀，\n你把小茜弄哭了啊……\012没事啦！\n过一会儿就好了，\011她每次输了都会哭。",
  ["57:4537"] = "哎呀，这个训练家真可爱！\n姐姐我很中意你！\011不过我可不会手下留情哦！",
  ["57:457e"] = "呃……\n哎呀，结束了？",
  ["57:4599"] = "居然把姐姐打败了，\n了不起，了不起！\011就这样继续努力吧。",
  ["57:45c8"] = "如果不认真一点，\n可没有好果子吃哦！",
  ["57:45f7"] = "讨厌～！！\n抱歉啊，我的小喵喵。",
  ["57:4615"] = "为了能应付\n各种属性的宝可梦，\011我特地让它们学会了招式。",
  ["57:4644"] = "嗨～！\n未来的冠军！\012这个道馆中\n聚集了很多使用一般属性\011宝可梦的高手哦！\012如果你想和她们对战，\n我建议你使用\011格斗属性的宝可梦！",
  ["57:46b1"] = "赢了吗？那太好了！\n我光顾着看这些姑娘了。",
  ["57:4791"] = "唉……\n特地搬到满金市，\011车子却一辆也卖不出去。\012你愿意帮忙吗？\n就是骑着自行车闲逛，\011到处帮我们做宣传。",
  ["57:4802"] = "真、真的吗？\012那就请你告诉我\n你的名字和电话号码。\011我会借你自行车的。",
  ["57:4852"] = "{PLAYER}\n借到了自行车！",
  ["57:4869"] = "奇迹自行车店的自行车\n性能绝佳！\011什么路况都能悠游自如！",
  ["57:48a2"] = "唉……\n就没有好心人吗。",
  ["57:48f7"] = "有辆锃亮锃亮的自行车！",
  ["57:49ad"] = "只要对宝可梦好，\n宝可梦就会亲近你。\012哎呀？\n你的{STRBUF}……",
  ["57:4a06"] = "真是无比幸福啊！\n它一定和你极其亲密呢！",
  ["57:4a36"] = "对你非常信赖，\n我是这么感觉的。",
  ["57:4a64"] = "正在和你亲密起来，\n它好像很幸福呢。",
  ["57:4a98"] = "相当可爱呢。",
  ["57:4aa9"] = "你对它多付出一点关爱吧？\n感觉它还没有适应你。",
  ["57:4adb"] = "对你完全没有亲密感，\n它的眼神似乎不太友善。",
  ["57:4b0e"] = "在宝可梦对战中总是打输，\n让宝可梦陷入濒死状态……\012或许就是因为这样，才会\n和宝可梦亲密不起来的。",
  ["57:4b71"] = "如果给宝可梦使用道具\n它就会变得非常开心哦！",
  ["57:4c7e"] = "正辉：哎哟，{PLAYER}，\n正好有事儿想拜托您，\011我刚取出来一只伊布。\012这小家伙儿是我调整\n时光胶囊的时候\011别人突然送来的。\012必须得有人照料它才行，\n偏偏我又爱在家闷着，\011{PLAYER}，\011您带它玩儿吧。",
  ["57:4d49"] = "正辉：您瞧瞧您，\n哎呀……真是大帅哥！\011看您多仗义，\011不愧是干大事儿的！\012那就仰仗您了，\n要好好疼爱它哦！",
  ["57:4db5"] = "{PLAYER}获得了\n伊布！",
  ["57:4dc8"] = "正辉：伊布身上发现了\n新的进化可能性，\011空木博士之前好像发表过。",
  ["57:4e09"] = "这可不行啊，\n不能带更多的宝可梦了。",
  ["57:4e34"] = "这样啊……",
  ["57:4e49"] = "正辉：我之前\n一直在测试传送装置哟。\011要不要做个后续版本儿呢？",
  ["57:4e93"] = "哎呀，你在收集宝可梦啊。\n我的儿子也很懂宝可梦哦。\012他叫做正辉，\n现在在缘朱市的\011宝可梦中心有点事情。",
  ["57:4efa"] = "作为母亲最大的幸福\n就是看到儿子的脸。",
  ["57:4f1d"] = "你是宝可梦训练家？\012那我告诉你一个\n很棒的电话号码吧？",
  ["57:4f58"] = "{PLAYER}添加了\n正辉的电话号码！",
  ["57:4f72"] = "在电脑里\n寄放宝可梦的系统就是由\011我哥哥制作出来的哦。\012我本来想把\n正辉哥哥的电话号码\011告诉你的……",
  ["57:4fc5"] = "啊！\n不能再添加更多号码了。",
  ["57:4fe8"] = "在电脑里\n寄放宝可梦的系统就是由\011正辉哥哥制作出来的哦。",
  ["57:50d7"] = "电车没有入站！\012作为对乘客的补偿\n只好由我背着各位……\012好像不太现实。",
  ["57:512e"] = "开往金黄市的列车\n马上就要出发了，\011请问您要乘坐吗？",
  ["57:5164"] = "请出示一下车票！\012好了！\n请走这边！",
  ["57:51a0"] = "啊呀，这位乘客\n您没有带车票呢。",
  ["57:51c3"] = "衷心期待\n您下次乘坐我们的列车！",
  ["57:51de"] = "路上辛苦了。\n列车已经到达满金市。\012衷心期待\n您下次乘坐我们的列车！",
  ["57:5217"] = "我是这儿的老板！\012我的梦想是建设\n比宝可梦还快的铁路！\012那样一来，城都和关都的\n距离一下子就缩短了！",
  ["57:5311"] = "哎呀？你居然\n比小茜还要厉害啊。\012知道那棵会动的树吗？\012用杰尼龟喷壶浇水的话，\n它就会向你扑过来的。\011不过你有这么多徽章，\011应该没什么好担心的！",
  ["57:53b6"] = "啦啦啦～啦啦啦啦～\n浇水浇得饱饱哒～",
  ["57:53e9"] = "我在36号道路\n给那棵会动的树浇了水，\011它居然吓了一跳！\012我感觉它肯定是宝可梦，\n如果没有道馆馆主小茜那样\011的实力，应该赢不了吧……",
  ["57:5485"] = "知道那棵会动的树吗？\012给它浇水之后，\n它居然吓了一跳！",
  ["57:5513"] = "在宝可梦中心\n2楼的竞技场中\011可以进行连接对战。\012墙上可以看到自己的成绩，\n所以不能输太惨啊。",
  ["57:5597"] = "世界上到底有\n多少种宝可梦呢。\012大木博士\n3年前的报告中是说\011总共有150种……",
  ["57:5614"] = "因为有属性相克，\n不论等级多高，\012绝对强大的宝可梦\n也是几乎不存在的。",
  ["57:56fe"] = "我之前进行对战的时候，\n宝可梦使不出招式了。\012因为招式点数\n变成0了啊。",
  ["57:576f"] = "即使宝可梦还有精力，\n也可能会用不出招式！\012这时要去宝可梦中心，\n或者使用道具来治愈！",
  ["57:5a38"] = "欢迎光临！\n这里是满金百货店。",
  ["57:5a5c"] = "在满金市的百货商店里，\n各种商品一应俱全。\012但是呢，在这个城市里\n也有很多东西只能在\011游戏城作为奖品获得。",
  ["57:5abf"] = "那么，\n今天也要大买特买！",
  ["57:5adf"] = "妈妈很会买东西。\012总能用低廉的价格\n买到道具哦。",
  ["57:5b25"] = "1楼 …… 服务柜台\n2楼 …… 训练家广场\0113楼 …… 对战收藏\0114楼 …… 药品专区\0115楼 …… 招式学习器专柜\0116楼 …… 休息广场",
  ["57:5cb7"] = "宝可装置至多可以\n添加十个人的号码。\012到底要添加谁的号码呢，\n真的好难决定啊。",
  ["57:5d0d"] = "我的凯西\n是从游戏城里获得的，\011现在是我重要的同伴。",
  ["57:5d49"] = "一到百货店就会觉得\n满金市不愧是大城市。\012商品琳琅满目，\n其他地方根本没得比。",
  ["57:5dba"] = "伴你同行\n2楼 …… 训练家广场",
  ["57:5e5e"] = "我、我是急、急性子，\n宝、宝可梦对战\011要用速度强化\011提、提升速度！",
  ["57:5ea7"] = "喂，你有没有在对战时\n给宝可梦用过特攻强化？\012特殊能力上升之后，\n感觉超级棒哦！",
  ["57:5f09"] = "一切为了获胜\n3楼 …… 对战收藏",
  ["57:5f9d"] = "我喜欢强大的宝可梦。\n大量使用攻击增强剂之后，\011攻击力也会大量上升哦！",
  ["57:5fe7"] = "防御增强剂可以\n提升宝可梦的防御力哦！",
  ["57:6009"] = "有的宝可梦穿越\n连接线之后会进化。\012比方说：豪力、勇基拉、\n鬼斯通，还有隆隆石。\011不过听说不止这四种。",
  ["57:60a2"] = "提升宝可梦的能力！\n4楼 …… 药品专区",
  ["57:61d8"] = "欢迎光临！\012哎呀，您的宝可梦……",
  ["57:61ef"] = "和你极其亲密呢！\n你们这一对组合\011一定能灵活运用这个招式！",
  ["57:623b"] = "相当可爱呢！\012一定要用招式学习器\n让它多学几个好招式哦！",
  ["57:626d"] = "它的眼神似乎不太友善呢。\n对于这样的宝可梦，\011不妨试试这个招式学习器？",
  ["57:6297"] = "总有一款招式学习器\n适合你的宝可梦。",
  ["57:62d6"] = "神秘礼物\012哔！\012的一声，礼物收到了！",
  ["57:630e"] = "神秘礼物\012您的Game Boy\n无法接收……",
  ["57:6342"] = "有个大姐姐周日会过来。\n让她看看宝可梦的状况，\011有机会得到招式学习器哦。",
  ["57:6388"] = "从别人那获得的宝可梦\n是无法更改名字的。\012因为名字里包含了\n命名者的心意啊。",
  ["57:63f9"] = "打造你专属的宝可梦\n5楼 …… 招式学习器专柜",
  ["57:6560"] = "是自动贩卖机！\n想要的饮料是…………",
  ["57:6584"] = "哐当！\012{STRBUF}已滑落至取物口！",
  ["57:65a7"] = "钱不够！",
  ["57:65c0"] = "已经拿不下了！",
  ["57:65e0"] = "喂，你听过广播里的\n幸运频道吗？\012如果和很多人\n交换过宝可梦，\011收集了很多ID的话，\011中奖的机会比较大哦。",
  ["57:665f"] = "累了困了，就喝\n自动贩卖机里的饮料！\011宝可梦也很爱喝饮料的。",
  ["57:66af"] = "缓解您购物的疲劳\n6楼 …… 休息广场",
  ["57:6ab5"] = "欢迎光临！\012您可以在这里，\n把游戏中积攒的代币\011兑换成精美奖品！",
  ["57:6af0"] = "要哪个呢？",
  ["57:6b0d"] = "{STRBUF}，可以吗？",
  ["57:6b22"] = "给，请收下！",
  ["57:6b30"] = "您的代币不够哦。",
  ["57:6b4d"] = "已经拿不下了。",
  ["57:6b6e"] = "啊，这样吗。\n请多积攒一些代币再来！",
  ["57:6b9a"] = "哎呀？\n你没有代币盒呢。",
  ["57:6bba"] = "我总是玩这台老虎机。\n比起其他的机子，\011这台好像更容易出代币。",
  ["57:6c03"] = "最新款老虎机就是好。\n比起在玉虹市的机子，\011这台更有挑战性！",
  ["57:6c59"] = "人生成败，在此一举！\n翻牌、翻牌，赶紧翻牌！",
  ["57:6c90"] = "翻牌游戏……\012靠自己就能轻松预判，\n虽然赔率不如老虎机，\011但是我更喜欢玩这个。",
  ["57:6cfc"] = "没赢到钱绝不撒手！",
  ["57:6d16"] = "我让我的宝可梦\n记住了“暴风雪”哦。\012积攒代币确实不容易，\n但是也是相当有意义的。",
  ["57:6d72"] = "玩老虎机赢不了钱！\n玩翻牌游戏也赢不了钱！\012一时生气，我就把代币盒\n丢在地下通道了！",
  ["57:6f2c"] = "栎树林非常大，\n千万别走迷路了！",
  ["57:6f5c"] = "据说森林里有神……\n可千万不要干坏事哦。",
  ["57:6ffe"] = "嗯，你是要完成\n宝可梦图鉴吗？\012遇不到宝可梦很头疼吧？\n要不，你用用看\011这个招式学习器吧？",
  ["57:7057"] = "里面含有甜甜香气。\012在能遇见宝可梦的地方\n使用的话……\012就会出现被甜甜香气\n吸引而来的宝可梦哦。",
  ["57:70a2"] = "巴大蝶：大蝶！",
  ["57:70b6"] = "你参拜过\n森林之神的祠堂吗？\012森林之神能超越时间\n为我们守护森林哦。\011它一定是草属性宝可梦吧。",
  ["57:71b8"] = "爷爷\n正在找你哦。",
  ["59:400b"] = "我是垂钓大叔！\n是爱垂钓兄弟中的哥哥！\012你认识44号道路的\n垂钓者秀宪吗？\012那小子会在电话里面透露\n一些惊人的垂钓情报哦。\012我钓到了一堆稀有宝可梦！\n当时简直是满载而归啊！",
  ["59:40fa"] = "照片里\n有人正在垂钓……\011看起来非常开心。",
  ["59:4177"] = "有只瞌睡的宝可梦\n在地鼠洞穴的入口睡觉！\012虽然是捕捉的好机会，\n但是要怎么叫醒它？",
  ["59:41ef"] = "之前有只瞌睡的宝可梦\n在地鼠洞穴的入口睡觉，\011但是突然就不见了！",
  ["59:4255"] = "能与训练家对战\n正是高速船的乐趣所在！",
  ["59:4292"] = "哎呀？你带着一些\n我从没见过的徽章啊。\012啊，我懂了。\n你是城都的居民，对吧！",
  ["59:43d8"] = "宝可梦发烧友俱乐部的会长\n正是老夫！\012老夫手里的宝可梦\n已经超过了150只！\012要老夫说起宝可梦的事，\n那可三天三夜都说不完哇！\012你一定是来倾听老夫炫耀\n那些赞赞的宝可梦的吧？",
  ["59:4468"] = "果然是吧！\n那老夫就开始喽！\012那啥……那就先介绍\n老夫钟爱的烈焰马吧……\012……它呀……就是……\n…… ……可爱的唷……\011了不得哇……唔……\011……而且它啊……已经……\011棒棒…… ……的……\011……你也这么觉得吗……\011……哈——！\012…… ……抱一抱唷……\n它睡觉的时候哇……\011洗澡的时候也……\011……对吧！…… ……\011…… ……艺术品啊……！\011…… 优美到飞天……\011…… ……哎哟！\011已经这个点了！\011老夫说得太多喽！",
  ["59:4594"] = "你听老夫称赞宝可梦\n听得还挺有耐心的哇！\011……收下老夫的一点心意！",
  ["59:45c9"] = "这是能让宝可梦变强的\n神奇糖果哇！\012一起战斗，\n慢慢变强。\011老夫也很喜欢呢。\012那个糖就给你吧！",
  ["59:4637"] = "哎呀，{PLAYER}！\012又想来听老夫介绍\n引以为豪的宝可梦了吧！\012……啥？不是？\n什么嘛……真没意思……",
  ["59:468f"] = "什么嘛，真没意思……\n等你想听的时候再来吧！",
  ["59:46c4"] = "我们会长\n对宝可梦十分讲究！",
  ["59:46f7"] = "只要一想起\n那个挥指的动作……\011呜呜——！\011皮皮太可爱了吧！",
  ["59:4756"] = "我特别喜欢皮皮，\n但是怎么也捉不到。\012实在是很无奈。\n只好先用捡到的皮皮玩偶\011忍耐一下了……",
  ["59:47b1"] = "这样啊，\n遗失这个玩偶的女孩子\011现在很难过吗……\012我明白了！\n请你帮我把皮皮玩偶\011还给那个姑娘吧！\012我要用自己的力量\n与皮皮成为朋友！",
  ["59:4861"] = "{PLAYER}\n暂时保管了皮皮玩偶！",
  ["59:4875"] = "我一定要和真正的皮皮\n成为朋友！",
  ["59:48af"] = "你的背包\n已经装不下了！",
  ["59:48ca"] = "你看、你看！\n我的月桂叶！\012头上的叶子\n真可爱啊！",
  ["59:4908"] = "是皮皮！\n……？\012原来只是皮皮玩偶！",
  ["59:4940"] = "月桂叶：叶，叶！",
  ["59:4953"] = "请静心聆听训练家\n炫耀他们的宝可梦！",
  ["59:4980"] = "如果有人跟你炫耀，\n你就10倍炫耀回去吧！",
  ["59:4a17"] = "知道磁浮列车吗？\012我说的是可以直达\n城都满金市的列车哦。",
  ["59:4a6d"] = "金黄市——！\n我要去金黄市——！\011好想看磁浮列车——！",
  ["59:4ae2"] = "关都没有火箭队，\n只是这样我就觉得很开心！",
  ["59:4b21"] = "我打算去金黄市的商店\n买东西。",
  ["59:4b8b"] = "地鼠花了好几年\n才挖出一条直通\011遥远城镇的地下通路哦。",
  ["59:4c99"] = "马志士：嘿！\n小鬼！\012居然敢向我挑战，\n你真是不知天高地厚！\011我的电属性宝可梦，\011可是天下第一！\012我在战场上\n从来没输过！\012我要让你浑身麻痹，\n就像战场上的敌兵一样！",
  ["59:4d8a"] = "马志士：哦，不！\n你真的很强！\012好！\n橙色徽章就交给你了！",
  ["59:4dc9"] = "{PLAYER}从马志士那里\n得到了橙色徽章！",
  ["59:4de3"] = "马志士：有了橙色徽章，\n宝可梦的速度就会提高！\012这是战胜我的证明！\n你要好好珍惜！",
  ["59:4e55"] = "马志士：嘿，小鬼！\n还在继续努力吧？\012我和宝可梦们\n也在继续努力！",
  ["59:4ea8"] = "你来这里是想要\n打败马志士少校吗！\011别想得逞！",
  ["59:4ede"] = "非常抱歉！\n马志士少校！",
  ["59:4f02"] = "以前在部队的时候……\n我曾经被马志士少校\011救过一命……！",
  ["59:4f3a"] = "我使用电属性的技术\n可是得到马志士认可的！\011你赢得了我吗！？",
  ["59:4f89"] = "咻——！麻掉了！",
  ["59:4f9d"] = "如果道馆的机关还在，\n我肯定能赢你……！",
  ["59:4fd9"] = "由我来打败你！\n做好觉悟吧！",
  ["59:500c"] = "呜哇！\n好强！",
  ["59:5028"] = "你只是赢了我而已，\n别掉以轻心啊……\011马志士少校很强的……",
  ["59:5069"] = "嗨～！\n未来的冠军！\011你很走运！\012平时马志士都会\n小心翼翼地设置陷阱，\011但现在正好坏掉了！\012尽管放心，\n好好和马志士对战吧！",
  ["59:5131"] = "太刺激了！\n真是一场紧张的比赛！",
  ["59:5170"] = "我翻我翻……！\n垃圾箱里只有垃圾！",
  ["59:5250"] = "欢迎来到\n磁浮列车之城——金黄市！\012我是很想这么说……\n但是发电厂好像出事了，\011完全不能输出电力。\011磁浮列车也跟着停运了。",
  ["59:531d"] = "要说金黄市的特色，\n那当然是磁浮列车啦！",
  ["59:53bb"] = "你好！\012赤红一直在外旅行，\n已经有很长时间\011没有联系过家里了。\011他现在在哪里做什么呢……\012虽然俗话说\n没有消息就是好消息，\011但我还是很担心啊。",
  ["59:547c"] = "很担心他有没有伤病，\n男孩子要爱惜身体啊！",
  ["59:54e3"] = "正在播放在城都\n从来没听过的节目……！",
  ["59:554b"] = "{PLAYER}\n正在玩神游机！\011…… …… 好了！\011也该出发了！",
  ["59:5582"] = "……好像有很长的时间\n没有被人使用过了。",
  ["59:562b"] = "奈奈美：我弟弟是\n常青市的道馆馆主。\012但是他常常不在道馆，\n好像给大家添了不少麻烦。",
  ["59:56b1"] = "奈奈美：欢迎光临。\n你来得正好呀！\011现在正是喝茶时间。\012哎呀？你的宝可梦\n好像有点脏啊！\011我来给它们梳毛吧？",
  ["59:573f"] = "奈奈美：要选哪只宝可梦？",
  ["59:5761"] = "奈奈美：那么，\n我要开始梳毛了！",
  ["59:5791"] = "{STRBUF}\n好像非常享受！",
  ["59:57a5"] = "奈奈美：好了！\n现在清爽多了！\012哦呵呵，\n真是可爱的宝可梦呀！",
  ["59:57f5"] = "奈奈美：我每天\n都会在这个点喝茶哦。\011欢迎下次再来！",
  ["59:582f"] = "奈奈美：不要梳毛吗？\n那还是喝茶吧。",
  ["59:5872"] = "奈奈美：哦呵呵！\n我没法给蛋梳毛呀。",
  ["59:5922"] = "大木：哦，{PLAYER}！\n你居然特地来我这里了！\012怎么样？\n关都地区的训练家\011不太好对付吧？",
  ["59:599d"] = "宝可梦图鉴进展如何？\n让我看看吧。\012嗯……",
  ["59:59c3"] = "你下次要是再经过这里，\n一定要进来坐坐啊。",
  ["59:59f7"] = "大木：哦，太了不起了！\n居然能集齐关都的徽章！\011我果然没有看错人啊！\012{PLAYER}！\n我现在帮你办理\011进入白银山的手续吧！\012白银山非常大，\n上面有很多野生宝可梦！\012那里实在是太危险了，\n所以禁止一般训练家进入。\011{PLAYER}另当别论！\012你现在去石英高原看看，\n那里有通往白银山的路。",
  ["59:5b9d"] = "大木：哎呀？\n你好像还没开始\011收集关都的徽章啊。\012关都的道馆训练家们\n绝不比城都逊色，\011其中高手如云！\011你不妨去挑战一下吧。",
  ["59:5c37"] = "大木：你好像正在\n收集关都的徽章吧！\012虽然并不轻松，\n但是，{PLAYER}，\011经验会成为你的力量！\012等你全部集齐以后，\n再来我这里玩吧。\011到时候我有礼物送你！\012{PLAYER}，\n加油吧！",
  ["59:5cf6"] = "博士的宝可梦讲座\n并没有在关都播放。\011真遗憾！我好想听啊。",
  ["59:5d54"] = "多亏了{PLAYER}\n努力地填满图鉴，\011博士的研究工作\011进展得非常顺利！",
  ["59:5da2"] = "……我只告诉你一个人！\012大木博士的宝可梦讲座\n其实并不是现场直播！",
  ["59:5de5"] = "按下START键！\n就能打开菜单。",
  ["59:5e04"] = "想要保存的时候，\n一定要仔细地写下记录。",
  ["59:5e40"] = "里面是空的……",
  ["59:5e59"] = "往电脑屏幕看的时候，\n发现了一封电子邮件！\012…… …… ……\012大木博士，\n您的研究进展顺利吗？\012我这边嘛……\n总之在努力就对了！\012听说{PLAYER}\n现在也非常努力，\011我由衷地感到高兴！\012……若叶镇空木敬上\n…… …… ……",
  ["5a:400f"] = "尼多朗，握手！",
  ["5a:4020"] = "尼多朗：嘎噢，嘎噢！",
  ["5a:40cb"] = "小刚：真少见，\n居然有城都来的挑战者！\012我是深灰宝可梦道馆的\n道馆馆主——小刚！\011我是岩石属性的专家！\012太慢太柔弱的攻击\n对我的宝可梦来说\011完全不痛不痒！\012尽管上吧！",
  ["5a:41b6"] = "小刚：……攻势真猛烈，\n令我防不胜防啊……\011完全超出我的想象……！\012好吧，\n拿走这枚徽章吧！",
  ["5a:4238"] = "{PLAYER}从小刚那里\n得到了灰色徽章！",
  ["5a:4252"] = "小刚：谢谢你，\n{PLAYER}！\011让我痛快地打了一场！\012有了我的灰色徽章，\n你的宝可梦\011会变得更加强大哦。\011让人不太甘心呢！",
  ["5a:42d5"] = "小刚：这个世界很大……\n像你这样强大的训练家\011一定多不胜数。\012我也要成为更更更\n强大的训练家啊！",
  ["5a:435d"] = "这间道馆的训练家\n擅长使用岩石宝可梦！\012因为岩石属性\n拥有惊人的防御力！\012接下来会是持久战哦！\n做好心理准备吧！",
  ["5a:43ec"] = "对战必须获胜……",
  ["5a:440a"] = "小刚很强的！\n一不小心就会让你吃苦头。\011别大意啊，城都训练家！",
  ["5a:4469"] = "嗨～未来的冠军！\n看起来状况不错嘛！\012你正在挑战\n关都的道馆馆主吗？\012他们都不太好对付哦，\n绝不会比城都逊色！",
  ["5a:4502"] = "不愧是未来的冠军！\n这是场有惊无险的对战！\011我好感动啊，真的！",
  ["5a:45d3"] = "看，我的暴鲤龙！\012我从鲤鱼王开始培育的，\n现在已经这么强了！",
  ["5a:4635"] = "以前有个奇怪的大叔\n在兜售宝可梦。\012他说愤怒之湖里的\n鲤鱼王特别好。",
  ["5a:46fc"] = "那个，那个……\n红莲镇的道馆没了呢！\011人家真的超级惊讶哦！\012……干嘛？\n老娘打电话呢，别碍事！",
  ["5a:4758"] = "胖丁：胖～胖胖～～",
  ["5a:4770"] = "只要听到胖丁的歌声……\n大多数的宝可梦都会犯困。\012不过有几种招式\n可以在睡梦中使出哦！",
  ["5a:485a"] = "我喜欢一边听广播\n一边打瞌睡……\011呼……呼噜呼噜……",
  ["5a:4a24"] = "宝可梦联盟\n会对你进行考验，\011看看你能否战胜四天王。\012如果不幸战败了，\n那当然是从头来过！",
  ["5a:4aa1"] = "等一下。\012……这就要去\n挑战宝可梦联盟了？\012别做梦了。\012我那些经历\n千锤百炼的宝可梦\011会把你打倒的。\012{PLAYER}！\n和我对战吧！",
  ["5a:4b41"] = "…… …… ……\012我认输了……",
  ["5a:4b50"] = "……切。\n还是赢不了你……\012也就是说……\n我还需要……\011给予宝可梦\011更多的关爱吗。\012……哼！\n你就苟延残喘吧。",
  ["5a:4ba9"] = "…… …… ……\012呼……\n下一步就是和我的宝可梦\011一起成为冠军！",
  ["5a:4be1"] = "哦，要挑战四天王吗！\n你不觉得应该再\011多修行一会儿吗？\012我的凯西会使出\n瞬间移动，\011马上就能把你送回家哦！\012怎么样呢，\n需要帮你传送吗？",
  ["5a:4c93"] = "这样啊。\n那就请在脑中浮想起\011自己的家吧。",
  ["5a:4cbd"] = "这样啊，\n那就加油吧！",
  ["5a:4cdf"] = "凯西：西……",
  ["5a:4ddd"] = "欢迎来到宝可梦联盟！\012我的名字是一树。\012以前环游世界的时候，\n我日夜不停地锻炼着\011我的超能力宝可梦。\012最后终于成为了\n四天王中的一员。\012我还要变得更强！\n可不会在这里输掉！",
  ["5a:4ed8"] = "……伤脑筋啊。",
  ["5a:4ef0"] = "虽然这次输了，\n但我的计划没有改变。\011为了站上训练家的顶点，\011我还会不断地战斗。\012你就继续前进，\n好好体会一下\011四天王的可怕之处吧！",
  ["5a:503f"] = "……哈！哈！哈！\012在下是四天王阿桔！\n人称“当代活忍者”！\012在下使用的战术\n绝非寻常之法能敌！\012使之乱，使之寐，\n使之中毒……\012在下的招式可以说是\n变换自在，诡计多端！\012……哈！哈！哈！\012宝可梦的深妙之处，\n光靠力量是无法领悟的！\011你就好好感受一下吧！",
  ["5a:5155"] = "哦！\n你有点本事啊！",
  ["5a:5176"] = "我已经使出了浑身解数。\012即便如此还是输了，\n我还需要进一步修行啊。\012你还是前往下一个房间\n去测试自己的实力吧！",
  ["5a:52aa"] = "我是四天王希巴！\012我相信潜藏在\n我们体内的可能性，\011所以在不断地追求极限。\012你有自信能战胜\n如此强大的我们吗？\012哦，你那毫无惧色的\n表情非常不错。\011这才是战斗时该有的姿态。\012你叫{PLAYER}吧？\n来吧！看看你能不能\011承受住我们的神力！\012哼——！哈——！",
  ["5a:53cf"] = "这是怎么了！\n……我们竟然输了！",
  ["5a:53e8"] = "败军之将，\n何以言勇！\011向下一个房间前进吧！",
  ["5a:54d3"] = "我是四天王梨花！\012你是{PLAYER}吧。\n嗯，好像很有意思呢。\012我一直钟爱着\n恶属性的宝可梦！\012那种狂野粗犷的感觉，\n不是很美妙吗？\011而且它们也非常强大哦。\012你要当我的对手吗？\n为了让我尽兴，\011希望你能好好努力吧。\012那就开始吧！",
  ["5a:55a4"] = "嗯，有两下子。\n这点很不错。",
  ["5a:55d5"] = "“强大的宝可梦”\012“弱小的宝可梦”\012都只是人类的一厢情愿。\012真正强大的训练家\n应该靠自己喜欢的宝可梦\011去努力追求胜利。\012你很不错呢，\n能明白孰是孰非。\012继续前进吧。\n冠军在等着你呢。",
  ["5a:5816"] = "阿渡：我等了很久啊！\012{PLAYER}！\012我很清楚，以你的实力，\n到这里只是时间问题。\012无须多言！\012还是通过对战\n来一决高下吧！\012最强训练家、\n联盟冠军——\012龙使者阿渡\n前来讨教！",
  ["5a:5953"] = "……结束了。\012我现在的心情很复杂呢。\012虽然也有失败后的懊恼，\n但是我感到更多的是\011亲眼见证优秀冠军诞生时\011所产生的喜悦感。",
  ["5a:59e1"] = "……呼。\012成长了不少呢，\n{PLAYER}。\011你现在已经这么强了。\012身为训练家，你只要\n怀有一颗正直而强大的心，\011就能获得宝可梦的青睐。\012这样一来，宝可梦就能\n和训练家共同进步……",
  ["5a:5a8c"] = "胡桃：啊——都结束了！\n真是的，都怪博士太慢了！",
  ["5a:5aca"] = "大木：{PLAYER}！\n好久不见啊。\011哎呀，你真是出人头地了！\012能称霸宝可梦联盟\n真的是非常了不起啊！\012你一路上都没有\n忘记对宝可梦的爱与信赖，\011真正做到了砥砺前行。\011所以才能有今天的成果。\012哎呀，宝可梦也很伟大啊！\n它们愿意去相信训练家，\011所以才能那么努力！\012{PLAYER}\n真是恭喜你了！",
  ["5a:5bf6"] = "胡桃：那么，接下来\n我要采访一下新冠军。",
  ["5a:5c26"] = "阿渡：……这里好像\n越来越吵了……\012{PLAYER}！\012能跟我来一下吗？",
  ["5a:5c70"] = "胡桃：啊！\n采访都还没开始啊！",
  ["5a:5d51"] = "阿渡：……我已经很久\n没进过这个房间了。\012建这个房间是为了\n彰显联盟冠军的荣光，\011也是为了让人永远记住\011那些经历了无数恶战的\011宝可梦们！\012此时此刻，\n对宝可梦充满信任与关爱，\012对自己怀有坚毅与严格，\012拥有无数宝贵品质的\n新冠军诞生了！\012来吧，{PLAYER}！\n让我们好好记录\011你与你的伙伴们！",
  ["5b:41b3"] = "马上就要启航了，\n请上船。",
  ["5b:41de"] = "现在无法登船！",
  ["5b:41fa"] = "欢迎来到\n高速船水流号！\011要乘船吗？",
  ["5b:4238"] = "那么，请出示一下船票。",
  ["5b:4259"] = "期待您下次搭乘。",
  ["5b:4274"] = "出示了船票！\012好的！可以了！",
  ["5b:42a9"] = "{PLAYER}\n正想出示船票……\011可是……没有票……！\012……非常抱歉！\012只允许\n持有船票的乘客登船。",
  ["5b:4310"] = "高速船预定\n在下个周一启航。",
  ["5b:4336"] = "高速船预定\n在下个周五启航。",
  ["5b:435c"] = "别的地方很难钓到大舌贝，\n在这里却很容易上钩！",
  ["5b:439d"] = "你有几根\n钓竿？\012钓竿种类不同，\n能钓的宝可梦也不一样！",
  ["5b:43de"] = "高速船水流号\n借喷射机的力量微微悬浮，\011所以才能飞驰于海面哦！",
  ["5b:440a"] = "在关都也有\n许多宝可梦呢！\011我也想去看看。",
  ["5b:443f"] = "要是掉进海里\n可就危险了，\011所以前方禁止通行。",
  ["5b:466e"] = "马上就要启航了，\n请上船。",
  ["5b:4699"] = "现在无法登船！",
  ["5b:46b5"] = "欢迎来到\n高速船水流号！\011要乘船吗？",
  ["5b:46f3"] = "那么，请出示一下船票。",
  ["5b:4714"] = "期待您下次搭乘。",
  ["5b:472f"] = "出示了船票！\012好的！可以了！",
  ["5b:4764"] = "{PLAYER}\n正想出示船票……\011可是……没有票……！\012……非常抱歉！\012只允许\n持有船票的乘客登船。",
  ["5b:47cb"] = "高速船预定\n在下个周三启航。",
  ["5b:47f2"] = "高速船预定\n在下个周日启航。",
  ["5b:4818"] = "你是从城都来的吗？\n听说那里居住着\011许多稀有的宝可梦呢。",
  ["5b:49ad"] = "高速船水流号\n即将前往枯叶市。\012到达枯叶港之后，\n会用广播进行通知。",
  ["5b:4a0d"] = "高速船水流号\n即将前往浅葱市。\012到达浅葱港之后，\n会用广播进行通知。",
  ["5b:4a6b"] = "你的房间在这里。\012宝可梦们受伤的话，\n就在床上好好休息一下，\011这可以让大家恢复健康。",
  ["5b:4ac1"] = "你的房间在这里。\012在床上休息后，\n宝可梦就会变得健康。\012船会在你睡觉的期间，\n到达港口哦。",
  ["5b:4b32"] = "登船的游客\n全都是训练家。\012他们会待在房间里\n等着对战的对手出现。",
  ["5b:4b84"] = "不好意思啊小男孩！\n叔叔我有件急事……！\012我的孙女不见了！\n我现在正在找她！\011是个小个子的女孩！\011看到的话就告诉我！",
  ["5b:4c04"] = "高速船水流号\n已经到达浅葱港！",
  ["5b:4c35"] = "高速船水流号\n已经到达枯叶港！",
  ["5b:4dba"] = "我要到关都去\n试试身手！",
  ["5b:4de0"] = "我想赢啊……！",
  ["5b:4df2"] = "城都的训练家也可以\n与关都的道馆馆主\011交战的哦！",
  ["5b:4e2a"] = "我的目标也是成为冠军！\n我会好好加油的！",
  ["5b:4e4c"] = "我和你\n不一样在哪里……！？",
  ["5b:4e6e"] = "总有一天，\n我会赢你的！",
  ["5b:4e8d"] = "你知道关都的人气主播\n莉莉丝小姐姐吗？",
  ["5b:4eb8"] = "呜哇——！",
  ["5b:4ec2"] = "莉莉丝小姐姐好是好，\n但胡桃小姐姐更棒！\011好想听城都的广播啊！",
  ["5b:4f0e"] = "你就一个人吗！？\n那就来场宝可梦对战吧！",
  ["5b:4f30"] = "太强了吧——！",
  ["5b:4f4b"] = "在关都是不是也有\n能让我感到满意的\011崇山峻岭？",
  ["5b:4f89"] = "如你所见，我是个水手！\n我可没在偷懒！\011我看这个房间没人，\011所以就想睡个午觉……！\012真是的！\n来场宝可梦对战吧！",
  ["5b:500e"] = "对不起！\n是我不对！",
  ["5b:5028"] = "当水手是力气活，\n真的很累人呀……",
  ["5b:5068"] = "哇——糟了！\n我弄丢了很重要的东西！",
  ["5b:509a"] = "找……\n找不到啊……！",
  ["5b:50ae"] = "算了，我还是放弃吧。\n啊，对了对了！\011你就不用特地去找了，\011最好忘了这件事情！",
  ["5b:50ec"] = "耶——！\n真是走运！",
  ["5b:50fc"] = "怎么会输啊！\n真不走运！",
  ["5b:5112"] = "我在房间里捡到了\n一枚漂亮的硬币哦。\012是之前住在这个房间的\n客人掉的吗……？",
  ["5b:5270"] = "我要去关都\n进行一场\011大型焰火表演！",
  ["5b:52a4"] = "嘶——嘶——\n火苗太小了……",
  ["5b:52be"] = "难道是因为火焰\n不适应大海……\012你说没有这回事？\n真的吗？",
  ["5b:52fa"] = "我要去奶奶那\n捉虫子！",
  ["5b:5329"] = "呀——\n好强的大哥哥啊！",
  ["5b:5347"] = "城都的树上\n有很多宝可梦！",
  ["5b:5379"] = "我要用宝可梦对战\n来掩饰我的悲伤！\011请你配合我！",
  ["5b:53a4"] = "我的心在哭泣……",
  ["5b:53b5"] = "虽然乘船旅行很适合用来\n缓解失恋的悲伤……\012但是高速船也太快了，\n一点感觉都没有。",
  ["5b:5418"] = "我要去满金的电台\n推销自己的歌！",
  ["5b:5456"] = "全跑调了！",
  ["5b:5470"] = "说到电台，\n这周幸运频道的\011中奖号码是什么呢……",
  ["5b:54af"] = "有张松软的床！\n好好休息一下吧……",
  ["5b:54cc"] = "完全恢复活力了！",
  ["5b:54e9"] = "高速船水流号\n已到达浅葱港！",
  ["5b:551a"] = "高速船水流号\n已经到达枯叶港！",
  ["5b:570e"] = "啊——得救了！\012刚刚被那个小姑娘\n拉去做她的玩伴，\011可把我给累坏了！",
  ["5b:5760"] = "乘坐我们的水流号\n感觉怎么样！？\011是不是感觉自己\012翱翔在海面上！",
  ["5b:57aa"] = "啊，小男孩你好啊……\n还是找不到我孙女……\012其实我也不是担心她，\n毕竟她离不开这艘船。\011但是我孙女精力旺盛，\011可能会给别人添麻烦。\011这样一想就很担心了……",
  ["5b:585a"] = "你是……{PLAYER}吧。\n听说你陪我孙女一起玩。\011非常感谢！\011我必须表示一下谢意！",
  ["5b:58b2"] = "对了！如果你不嫌弃，\n请收下这个吧！",
  ["5b:58d5"] = "我们现在正在\n环游世界哦。",
  ["5b:58f7"] = "船长先生，\n和我一起玩嘛——！\012好无聊——！\n再陪我玩一会嘛——！",
  ["5b:5936"] = "喂喂，\n你要不要陪我玩会儿？\011……诶！\011爷爷在担心我？\011那我要回去了！\011我要去找爷爷！",
  ["5b:599b"] = "爷爷，我回来了——！\n船长先生——\011还有这个哥哥——\011都愿意陪我玩呢——！",
  ["5b:59dd"] = "刚刚大家都在一起\n愉快地玩耍呢！",
  ["5b:59f9"] = "要陪叔叔我对战吗！",
  ["5b:5a1c"] = "真强哪！",
  ["5b:5a2b"] = "一个人出来旅行？\n你妈妈不担心吗？",
  ["5b:5a5e"] = "你千万不要觉得\n我们是小不点！",
  ["5b:5a84"] = "哎呀，我们输了！",
  ["5b:5a92"] = "叫我们小不点，\n实在是太失礼了！",
  ["5b:5ab9"] = "我们才不是小不点呢，\n那样可对女士不礼貌。",
  ["5b:5aea"] = "哎呀，我们输了！",
  ["5b:5af8"] = "我相信，有些时候\n小孩子比大人更聪明！",
  ["5b:5b25"] = "嗯嗯！我的大脑\n捕捉到了电波！",
  ["5b:5b51"] = "……我听见了一个声音！",
  ["5b:5b67"] = "是吗，原来高速船里面\n能收听城都的广播啊！",
  ["5b:5b9e"] = "如何？我的宝可梦\n是不是非常漂亮？",
  ["5b:5bce"] = "啊……！\n好不容易才弄漂亮的！",
  ["5b:5bec"] = "我要去宝可梦美发沙龙\n再次把它们弄漂亮！",
  ["5b:5c1f"] = "我要去百货店买东西！\n接下来呢……",
  ["5b:5c4d"] = "要做什么来着……？",
  ["5b:5c66"] = "想起来了，我要去培育屋\n把寄放的宝可梦取出来！",
  ["5b:5c97"] = "你有多少种\n精灵球？",
  ["5b:5cc4"] = "讨厌，真是的！\n你在干什么！",
  ["5b:5cdf"] = "最好还是根据状况\n选出最合适的精灵球。",
  ["5b:5d15"] = "高速船水流号\n已经到达枯叶港！",
  ["5b:5f4b"] = "喂、喂！说你呢！\n能帮我找个朋友吗？\012他翘班溜走了，\n真是受不了……！\012虽然我很想亲自去找他，\n不过我还有工作啊……",
  ["5b:5fd7"] = "真头痛啊……\n要挨船长的骂了。",
  ["5b:5ffe"] = "谢谢！\n我会好好批评他的，\011让他不要再旷工了！",
  ["5b:603d"] = "小女孩？\012说起来，我好像\n看见她经过这里了。",
  ["5b:606d"] = "再往前是食堂哦。\012最里面那个楼梯\n通向船长室。",
  ["5b:60bd"] = "工作间隙的休息时间，\n当然要进行宝可梦对战！",
  ["5b:60ea"] = "赢了也好，输了也好，\n反正休息是结束了！",
  ["5b:6108"] = "不认真以待的话，\n就不能变强吗……！？",
  ["5b:6133"] = "有点无聊呢！\n和我对战吧！",
  ["5b:6151"] = "讨厌，这么强吗！",
  ["5b:6169"] = "金黄市……\n玉虹市……\011我听别人说\011关都也有很多大城市呢！",
  ["5b:61a7"] = "呜呕！\n我好像晕船了！",
  ["5b:61ba"] = "已经动不了了……",
  ["5b:61d2"] = "我很怕坐船……\n下次乘磁浮列车吧……",
  ["5b:6210"] = "这里是我们这些水手\n神圣的工作地点！",
  ["5b:6230"] = "居然在自家主场\n被打败了！",
  ["5b:624a"] = "如果是从枯叶市\n乘到浅葱市的话，\011船上会有另一批乘客哦！",
  ["5b:628c"] = "上了船就不能垂钓了。\n太郁闷了！我们对战吧！",
  ["5b:62d8"] = "郁、\n郁闷的感觉缓解了……",
  ["5b:62f2"] = "我现在很期待\n去枯叶市的栈桥上垂钓！",
  ["5b:6317"] = "好——嘞！\n通过忍受船的摆动\011来锻炼自己的下盘吧！",
  ["5b:6355"] = "好——嘞！\n咕噜咕噜转——！",
  ["5b:636e"] = "空手道大王去城都修行了，\n所以我没见到他。\012现在应该是在某个洞窟里\n进行修行吧……",
  ["5b:63c9"] = "我是水手！\012但是为了成为冠军\n我也在进行宝可梦特训！",
  ["5b:640c"] = "练习不足难以掩饰！",
  ["5b:642f"] = "……那8个徽章莫非是\n打败道馆馆主的凭证？\012难怪会这么强！",
  ["5b:6486"] = "不要对我的学生们\n随便出手啊！",
  ["5b:64a9"] = "呀！",
  ["5b:64b1"] = "我们要去桔梗市\n参观遗迹哦。",
  ["5b:64e4"] = "喂，\n你知道阿露福遗迹吗？",
  ["5b:6504"] = "呀——！",
  ["5b:650d"] = "如果在遗迹里听广播，\n就会听见奇妙的声音哦。",
  ["5b:653f"] = "我听说阿露福遗迹里\n有神奇的石板！",
  ["5b:6576"] = "被打败了——！",
  ["5b:6586"] = "我在书上读到\n石板一共有4块哦！",
  ["5b:667f"] = "高速船水流号\n每逢周一与周五\011都会启航前往关都！",
  ["5b:66ed"] = "高速船的出航日\n是每周的\011周三与周日！",
  ["5b:680b"] = "月见山广场\n……请不要\011乱丢垃圾！",
  ["5b:6882"] = "听说太阳落山之后\n皮皮就会出来玩！",
  ["5b:693b"] = "啸——！！",
  ["5c:400f"] = "本来是想来狩猎地带\n买一点纪念品的，\011没想到休业了。\011也太倒霉了吧！",
  ["5c:4050"] = "园长的孙女\n还留在这个城市哦。",
  ["5c:424f"] = "呵呵呵……\n好遗憾哦……\012才怪！\012我是真的！\n我就是浅红道馆的阿杏！",
  ["5c:42bb"] = "阿杏：很强嘛，你！\n我彻底输了……\012好吧，拿走它吧！\n这是粉红徽章！",
  ["5c:4305"] = "{PLAYER}从阿杏那里\n得到了浅红徽章！",
  ["5c:431c"] = "阿杏：你很强呀！\n这个是特别奖励！\012里面是叫做剧毒的招式！\n可以放出猛烈的毒素\011夺走对方的体力！",
  ["5c:438e"] = "阿杏：我要继续修行，\n让自己变得更更更强！\012我希望将来既不会输给你，\n也不会输给我的父亲！",
  ["5c:4400"] = "呵呵！\n我就是馆主阿杏……\011骗你的！\011你上当啦！",
  ["5c:4440"] = "明明成功骗过去了啊……！",
  ["5c:4453"] = "你能不能看出来\n谁才是真的馆主呢？",
  ["5c:4480"] = "你被我骗了！\n啊哈哈哈哈！",
  ["5c:4495"] = "输了……！\n这个人怎么这么强！",
  ["5c:44b3"] = "怎么样？\n我的伪装是不是\011以假乱真？",
  ["5c:44d5"] = "我就是阿杏！\n你很懂嘛！\011来对战吧！",
  ["5c:450b"] = "……不甘心！\n我也想赢啊！",
  ["5c:4526"] = "你也应该\n感到疲劳了吧！",
  ["5c:4542"] = "哇、哈、哈！\012没错！\n我就是阿杏！",
  ["5c:456a"] = "我觉得我装得很完美啊！\n不甘心！",
  ["5c:458b"] = "我刚刚的伪装\n很可爱对吧！",
  ["5c:45ba"] = "嗨～！\n未来的冠军！\012……哎呀！\n您仔细瞧瞧周围！\011到处都是馆主阿杏，\011对吧！\012那么谁才是真的呢！？",
  ["5c:4646"] = "真是场精彩的对战啊，\n来自城都的训练家！",
  ["5c:46e4"] = "我爷爷\n去小正辉在华蓝海角的\011那个房子里玩了。",
  ["5c:471a"] = "我之前在自行车道\n看见了一种奇怪的宝可梦\011慢悠悠地走来走去！",
  ["5c:47b5"] = "喔！\n这是最新型宝可梦图鉴！\011是大木博士给你的吗？",
  ["5c:47fd"] = "一进道馆，你猜怎么着！\n到处都是\011长相相同的小姑娘！",
  ["5c:484f"] = "我就是阿杏姐姐哦！\n我变！",
  ["5c:486f"] = "看，是不是一模一样？",
  ["5c:4907"] = "我的爷爷是\n狩猎地带的园长！\012……话是这么说，\n他当初就留下一句：\011“我要去旅行了！”\011就一个人跑外国去了！\012那一刻，\n他抛弃了狩猎地带！",
  ["5c:49b2"] = "狩猎地带关门以后，\n很多人都觉得很遗憾。\011这都怪爷爷太顽固了！",
  ["5c:4a0b"] = "照片里有个笑着的老爷爷，\n他的身边都是宝可梦！",
  ["5c:4a47"] = "照片里是一片大草原，\n上面有些稀有的宝可梦！",
  ["5c:4ac2"] = "你的目标大概是\n完成宝可梦图鉴吧？\011加油啊！",
  ["5c:4b31"] = "据说那些一心想要\n变强的训练家们会\011不顾危险爬上白银山……\012这也说明只要值得信赖的\n宝可梦陪伴在身旁，\011训练家哪都愿意去吧……",
  ["5c:4c13"] = "哎呀呀……！\n被你发现了呢！\012能不能不要\n告诉别人我在这里呀？\011这个送给你，\011……拜托帮我保密吧！",
  ["5c:4c81"] = "当热门偶像真是辛苦，\n去哪里都有人跟着。\011我只想过安静的生活……",
  ["5c:4ce3"] = "大嘴雀：大嘴！",
  ["5c:4fa4"] = "欢迎来到宝可梦\n连接俱乐部竞技场！\012您在这里可以与朋友\n一起游玩宝可梦对战。\012要进行对战吗？",
  ["5c:4ffe"] = "欢迎来到宝可梦\n连接俱乐部交换中心！\012您在这里可以与朋友\n一起进行宝可梦交换。\012要进行交换吗？",
  ["5c:5068"] = "欢迎来到宝可梦\n连接俱乐部时光胶囊！\012您在这里可以前往过去的\n世界进行宝可梦交换。\012您需要使用\n时光胶囊吗？",
  ["5c:50e2"] = "您的朋友\n好像还没准备好。",
  ["5c:50fd"] = "进行连接之前\n将写下记录。",
  ["5c:5130"] = "请您耐心等待。",
  ["5c:513e"] = "由于等待时间过长，\n我们将取消本次服务！\012等你联系到了朋友，\n请再次光临！",
  ["5c:519a"] = "那么，欢迎下次再来。",
  ["5c:51f2"] = "这里无法与过去\n进行连接。",
  ["5c:5213"] = "您和您的朋友好像\n选择了不同的房间。",
  ["5c:5238"] = "那么，\n请进房间。",
  ["5c:5258"] = "{STRBUF}\n无法带入！",
  ["5c:5275"] = "携带了{STRBUF}的\n{STRBUF}无法带入！",
  ["5c:529c"] = "携带了信件的\n{STRBUF}无法带入！",
  ["5c:52cd"] = "非常抱歉，\n目前我们正在\011调整时光胶囊。",
  ["5c:52fc"] = "非常抱歉，\n目前我们正在\011调整连接机器。",
  ["5c:532c"] = "非常抱歉，\n目前我们正在\011调整对战机器。",
  ["5c:535d"] = "您就是{PLAYER}吧？\n这里有您的包裹。",
  ["5c:5391"] = "请收下！",
  ["5c:539f"] = "啊，签收就免了。\n希望下次也能为您服务。",
  ["5c:53bc"] = "你带不了更多了呢。\012我们的人遍布在\n全国的宝可梦中心，\011您随时都可以来领取。",
  ["5c:541a"] = "哎呀，好奇怪啊……",
  ["5c:553d"] = "对方完全准备好了！",
  ["5c:55be"] = "对方完全准备好了！",
  ["5d:401f"] = "穿越紫苑镇北边的\n岩山隧道，\011就能看到发电厂哦。",
  ["5d:4072"] = "有个频道可以收听到\n宝可梦之笛吹奏的乐曲哦。\012但是必须要有扩展卡\n才能收到那个频道。",
  ["5d:40db"] = "发电厂无法运作的话\n广播节目好像也会\011无法正常播放！",
  ["5d:411e"] = "因为发电厂修复，\n终于能播放广播节目了。\011台长非常高兴啊。",
  ["5d:4222"] = "虽然这里是富士老人的家，\n但是爷爷他现在不在这里。\012你去灵魂之家\n找找看吧。",
  ["5d:4271"] = "有些人中途放弃了\n对宝可梦的照料。\012于是爷爷就收留了\n这些可怜的宝可梦，\011并且好好培育它们。",
  ["5d:42e7"] = "可达鸭：嘎，呱？",
  ["5d:42fa"] = "尼多力诺：啾嗯！！",
  ["5d:430b"] = "波波：波波～！",
  ["5d:437e"] = "紫苑镇是\n山脚下的安静小镇！\012不过建了播音塔之后，\n就比以前喧闹一些了！",
  ["5d:445a"] = "如果要进行洞窟探险，\n除虫喷雾当然必不可少！\012即使是我这种探险行家，\n至今也没有走遍\011洞窟的每一个角落。",
  ["5d:44dd"] = "我听说城都的桧皮镇\n有一位工匠\011专门制作特制的精灵球！\012我也好想要啊！",
  ["5d:4586"] = "富士：呀，来得正好。\012嗯嗯……你很关爱宝可梦，\n一直都在精心培育它们呢。\012这里是爱宝可梦人士的\n聚集地。\012请你也来祈祷吧。\n宝可梦们一定会很高兴的。",
  ["5d:4680"] = "宝可梦坟墓的\n实际面积应该要大得多。\012听说这里有很多房间\n只有富士老人能进去。",
  ["5d:46e4"] = "我是和妈妈\n一起来扫墓的……",
  ["5d:470e"] = "曾今和我\n共同生活的宝可梦\011就像是我的亲孙子……",
  ["5d:47f2"] = "欢迎光临！\012整个1楼\n都对外开放参观！",
  ["5d:482d"] = "参观仅限于1楼。\012因为之前城都的播音塔\n被不法分子占领了，\011所以这里加强了戒备！",
  ["5d:48c3"] = "据说有很多人\n在播音塔里工作！\012他们一定在努力地\n制作有趣的广播节目！",
  ["5d:492e"] = "啊，大事不妙！\012发电厂无法运作\n叫我怎么放广播啊！\012好不容易才能运营电台，\n要是没法播节目，\011我就完了啊！",
  ["5d:49d4"] = "哦！\n你就是解决发电厂事件的\011{PLAYER}吧！\012多亏了你，\n我才能保住饭碗！\011真是谢天谢地啊！\012这是我的心意！\n你一定要收下！",
  ["5d:4a74"] = "只要有了这个，\n你就能搜索到\011新的广播节目了！\011嘎、哈、哈、哈、哈、哈！",
  ["5d:4ac6"] = "嗨——！\n我是音乐节目的\011超级导播！\012哎呀，你的宝可装置……\n好遗憾啊，你现在\011还收不到我的节目！\012想要收听的话，\n就要有升级版本的广播卡！",
  ["5d:4b83"] = "嗨——！\n我是音乐节目的\011超级导播！\012我正在播放\n优美的旋律哦！\011请多关照哦！",
  ["5d:4c26"] = "1楼 …… 服务柜台\n2楼 …… 营业部\0113楼 …… 总务部\0114楼 …… 制作室\0115楼 …… 台长室",
  ["5d:4c70"] = "用这清脆的笛声\n唤醒宝可梦的活力！\011频道20！",
  ["5d:4d5c"] = "你去过\n紫苑镇吗？\011那里有座大型播音塔哦。",
  ["5d:4df2"] = "我是钓鱼大叔的弟弟！\n你的脸上洋溢着\011对垂钓的爱！\011我肯定没看走眼！\012怎样？\n我猜对了吧？",
  ["5d:4e72"] = "嗯，嗯！\n和我想的一样！\011看你这么喜欢垂钓！\011就把厉害钓竿送给你吧！",
  ["5d:4ebf"] = "一定要去各种地方\n体验一下垂钓的乐趣！\012使用的钓竿不同，\n上钩的宝可梦也会不一样！",
  ["5d:4f2f"] = "哎呀？\n我看走眼了吗……",
  ["5d:4ff8"] = "这、这算什么啊……\012有个和你年纪差不多、\n目光凶狠、\011长发飘飘、\011样子有些可怕的少年\011把我宝贵的宝可梦抢走了！\012我身边只剩1只了，\n要是再次遇袭的话……\012你看起来挺强的啊。\n暂时帮我保管宝可梦吧！",
  ["5d:50e2"] = "那就定了，拜托你了！\n一定要好好对它！",
  ["5d:5110"] = "{PLAYER}从狂热迷\n那里接管了宝可梦！",
  ["5d:5124"] = "你的宝可梦太多了！",
  ["5d:513e"] = "怎、怎么这样……\n下次遇袭该怎么办啊？",
  ["5d:5165"] = "我的宝可梦还好吗？\012好像不会再遇袭了，\n我希望你把宝可梦还给我。",
  ["5d:51a6"] = "感谢！",
  ["5d:51b2"] = "我的宝可梦不在这里啊。",
  ["5d:51d8"] = "我的宝可梦\n和你非常亲近呢。\012好吧！宝可梦就给你了！\n不过你一定要好好对它哦。",
  ["5d:5234"] = "怎、怎么这样……\n这和遇袭有什么区别？",
  ["5d:5261"] = "对宝可梦而言，\n和珍爱自己的训练家同行\011是一件非常幸福的事情吧？",
  ["5d:53ee"] = "不错！\n你居然能到这里！\011先说一句，我非常强！\012我锻炼出的宝可梦\n既能粉碎岩石，\011也能让对手粉身碎骨！\012你瞧好了！",
  ["5d:5464"] = "阿四：呜——\n…… …… ……\012喝呀——！！",
  ["5d:547f"] = "怎么样！怕了吧！\012什么？你问宝可梦在哪？\n我给忘了！\011那就开始对战吧！",
  ["5d:54eb"] = "哎哟？\n我怎么输了……\012这可真难为情啊！\n很好！\011你配得上打击徽章！",
  ["5d:552a"] = "{PLAYER}从阿四那里\n得到了打击徽章！",
  ["5d:5542"] = "有了打击徽章，\n就算是别人送的宝可梦，\011等级低于70就会听你话。\012你也能让宝可梦飞翔了！\012啊，正好，\n把这个也拿去吧！",
  ["5d:55cf"] = "招式学习器01里面是\n爆裂拳！！\012虽然中不中是五五开，\n但只要成功击中，\011就能让对方尝到\011必定陷入混乱的一击！",
  ["5d:5625"] = "哇哈哈！\n我非常开心！\012不过输了就是输了，\n明天开始24小时特训！",
  ["5d:568c"] = "维系我和宝可梦的纽带\n是我们之间的炙热友谊！\011任谁也无法打破它！",
  ["5d:56de"] = "真的吗——！？",
  ["5d:56ef"] = "你和宝可梦之间\n也有一条强韧的纽带！",
  ["5d:5723"] = "我们格斗家，\n从来都是无所畏惧！",
  ["5d:5745"] = "震惊！",
  ["5d:5756"] = "格斗宝可梦\n其实害怕超能力。",
  ["5d:577f"] = "身无长物！\n无需多言，\011以拳会友！",
  ["5d:57b5"] = "身为败者，无话可说！",
  ["5d:57ce"] = "我这对强有力的拳头，\n一定会击碎你的宝可梦！",
  ["5d:57f7"] = "我、我被击碎了……",
  ["5d:5809"] = "引以为豪的宝可梦输了，\n我的自信被击碎了……",
  ["5d:58dd"] = "你见过这里的狂热迷吗？\012他好像有稀有的宝可梦，\n总是在那里显摆。",
  ["5d:5923"] = "这儿的宝可梦道馆里面\n净是一些莽汉！\012要是站在他们旁边，\n我可能也要被打飞。\012我要给你一点建议：\n道馆馆主使用的是\011格斗属性宝可梦！\012所以，你应该用\n超能力宝可梦迷惑它们！\011趁着对方还没发力，\011先发制人！",
  ["5d:5a2a"] = "{PLAYER}！赢了吧？\n你的表情说明了一切！",
  ["5d:5ac9"] = "您的宝可梦\n看起来没受重伤，\011那是有其他病痛吗？\012…… …… ……\012嗨，\n原来是灯塔的宝可梦啊。\012那好说！\n您得用这副药，\011拿好了，您。",
  ["5d:5b52"] = "{PLAYER}\n得到了秘传之药！",
  ["5d:5b6c"] = "我家的秘传之药\n药性有点猛，\011要没事儿可千万不能吃。",
  ["5d:5bf5"] = "你身边的宝可梦不错啊，\n怎么样，要不要给宝可梦\011拍1张纪念照？",
  ["5d:5c3e"] = "好，准备好了吗。",
  ["5d:5c52"] = "这样啊，有点遗憾呢。\n这会是旅行的美好回忆啊。",
  ["5d:5cb8"] = "你从浅葱市过来的？\n途中有4座小岛对吧？\011听说里面住着海神呢。",
  ["5d:5d3b"] = "据说，如果带了银色之羽，\n就可以见到它。\012或许是因为\n它能闻出自己的气味吧。",
  ["5d:5da5"] = "有一个说法是\n岛屿周围的漩涡\011其实是海神造成的。",
  ["5e:4011"] = "欢迎光临！\n玉虹百货公司！\012各楼层指南\n请参看右边的指示牌。",
  ["5e:4057"] = "这家百货公司\n好像和姐妹公司——\011满金百货店\011一起进行过改装哦。",
  ["5e:40cb"] = "我还是第一次来……\n这里真是太大了，\011我都晕了！",
  ["5e:410c"] = "1楼 …… 服务柜台\n2楼 …… 训练家专卖店\0113楼 …… 招式学习器专卖\0114楼 …… 聪明人礼品店\0115楼 …… 药品店\0116楼 …… 休息广场",
  ["5e:41ed"] = "我都这把年纪了，\n还是被儿子带着\011成为了训练家……\012我还收集了一大堆\n方便的道具哦。",
  ["5e:4262"] = "我爸这个人啊，\n怎么也记不住\011道具的名称和作用。",
  ["5e:42c0"] = "训练家必备物品应有尽有！\n2楼 …… 训练家专卖店",
  ["5e:4377"] = "要让哪个宝可梦\n记住招式学习器呢……\011啊，好头疼……",
  ["5e:43aa"] = "哎呀！\n一不小心就交换出了\011携带升级数据的宝可梦！",
  ["5e:43eb"] = "太好了！\n总算得到多边兽了！\012我玩不来老虎机，\n代币一直都攒不够……\012……啊？\012被传送过来的多边兽\n变成别的宝可梦了！？",
  ["5e:4485"] = "招式学习器专卖正在\n出售稀有的招式学习器哦。",
  ["5e:44a9"] = "3楼 …… 招式学习器专卖\n让你的宝可梦变强！",
  ["5e:4545"] = "我要给女朋友写信，\n所以来买冲浪信件！",
  ["5e:4579"] = "可爱信件\n只能在这里买到哦！",
  ["5e:45b0"] = "4楼 …… 诚心诚意送礼！\n聪明人礼品店！",
  ["5e:4647"] = "虽然我很想买提升\n宝可梦能力的道具……\011唔……钱不够啊！",
  ["5e:4696"] = "我想买增加招式点数\n最大值的PP提升剂，\011但听说那是\011不在商店出售的道具！",
  ["5e:46da"] = "如果给宝可梦使用道具，\n它会很高兴的！不过也有\011让宝可梦讨厌的道具……",
  ["5e:4724"] = "5楼 …… 药品店",
  ["5e:486c"] = "是自动贩卖机！\n想要的饮料是 …… ……",
  ["5e:4890"] = "哐当！\012{STRBUF}已滑落至取物口！",
  ["5e:48aa"] = "钱不够！",
  ["5e:48c3"] = "已经拿不下了！",
  ["5e:48e3"] = "带有抽奖功能的\n自动贩卖机……\011最近都找不到了呢。",
  ["5e:492c"] = "喂——喂——！\n这里没有游戏呀——！\011我想玩游戏呀——！",
  ["5e:495a"] = "6楼 …… 休息广场\n……自动贩卖机",
  ["5e:4a32"] = "只要身边有宝可梦陪伴，\n即使是独居生活……\011也不会感到孤寂……\012我家的喵喵啊……\n有时候会捡到钱呢。",
  ["5e:4a8c"] = "喵喵：喵～～呜！",
  ["5e:4a9b"] = "皮皮：皮～皮皮～～！",
  ["5e:4ab2"] = "尼多兰：啾～啾唔～！",
  ["5e:4ac7"] = "玉虹大厦\n…… 管理员室",
  ["5e:4b55"] = "{PLAYER}\n按下了电脑开关！\012…… …… ……\012好像有一封邮件\n正写到一半！\012…… …… ……\012好久不见，\n我很希望你能来关都！\012看到这边的变化，\n你应该会吓一跳吧！\012这里还有很多城都\n看不到的宝可梦。\012……致制作人\012…… …… ……",
  ["5e:4c48"] = "GAME FREAK\n会客室",
  ["5e:4cea"] = "是吗！\012我是游戏设计师。\012你要收集所有宝可梦吗？\n这件事很不容易哦，加油！",
  ["5e:4d41"] = "哇，了不起！\n你终于填满了\011图鉴的所有页面！\012恭喜你！",
  ["5e:4d7f"] = "我们会\n让插画师把奖状\011打印出来送给你！\011拿去给大家看看吧！",
  ["5e:4dd0"] = "我是个插画师！\n你就是我画出来的！",
  ["5e:4df4"] = "我是个插画师！\012哦，你完成图鉴了！\n作为纪念，\011我把奖状打印给你吧？",
  ["5e:4e4c"] = "等你想打印的时候，\n尽管来找我吧！",
  ["5e:4eb1"] = "我吗？我是程序员哦！\n去玩老虎机吧！",
  ["5e:4ee6"] = "双胞胎很可爱吧！\012阿蜜也是，唔……！\012他们真可爱啊！",
  ["5e:4f27"] = "GAME FREAK 开发室",
  ["5e:4f44"] = "有张漂亮的画。\n……是充满魅力的女孩子！",
  ["5e:4f6e"] = "是游戏的程序！\n要是修改了\011这个游戏可能会出错吧。",
  ["5e:4fb2"] = "摆满了各种资料。\n……还有皮皮玩偶！",
  ["5e:50ad"] = "你要不要听听\n我珍藏的恐怖故事……",
  ["5e:50d0"] = "……哎哟！\n这大白天的，\011就算讲了也没意思！\012等太阳下山了再来吧！",
  ["5e:5129"] = "话说有个男孩收到了\n一辆神秘的自行车……\012男孩非常高兴，\n当场就骑车转了几圈……\012其实这时天已经黑了，\n四周伸手不见五指……\011可他太高兴，没意识到……\012突然，自行车的车速\n一下子就变慢了！\011车蹬变得十分沉重！\011他没踩车蹬，\011可自行车却在向后滑！\012难道这是被诅咒的自行车，\n要把男孩拖向地狱吗……\012…… …… ……\012…… …… ……\012呀————！！\012原来是因为\n他身处自行车道的斜坡！\012…… …… ……\n我说完了，谢谢……\012你居然能听到最后，\n我要送你招式学习器03！",
  ["5e:5339"] = "招式学习器03是诅咒！\n这个招式可以一点一点地\011削减对方的体力，\011真的很可怕呢！",
  ["5e:53b4"] = "莉佳小姐\n是草宝可梦的行家！\012你要是小看她，\n会吃苦头的！",
  ["5e:5405"] = "游戏城的地下\n有火箭队的基地……\012哎呀！\n这是三年以前的\011过时情报！",
  ["5e:5571"] = "欢迎光临！\012您可以在隔壁的交换处，\n把游戏中积攒的代币\011兑换成精美奖品！",
  ["5e:55b6"] = "这边的老虎机\n全都是最新型号！\011啊，这也太有乐趣了吧！",
  ["5e:55e3"] = "对了，就是这台！\012昨天没有出过\n一枚代币，\011今天一定会出！",
  ["5e:5636"] = "我有种预感，\n这台一定能出代币……\012好像有的老虎机出的多，\n而有的老虎机不出代币。",
  ["5e:567d"] = "噶、哈、哈！\n源源不断地出代币！\011笑得停不下来！\012……哦！什么？\n你也想玩游戏？\012好吧，\n我就把好运分给你！",
  ["5e:56e6"] = "噶、哈、哈！\012帮助别人\n是快乐之本！",
  ["5e:572b"] = "哎呀！\n你没带代币盒哦！\011那我怎么分给你代币啊？",
  ["5e:577a"] = "哎呀！\n你的代币盒完全满了！\011看啦你也很走运嘛！",
  ["5e:57c6"] = "哎呀！\n未来的冠军！\011你也来玩老虎机？\012我很想兑换\n奖品宝可梦啊……\011但代币就是不够。",
  ["5e:584e"] = "唔……从概率上来说，\n皮卡丘那列更好吧……\011唉，好烦啊……！",
  ["5e:5894"] = "啊！\012在海报的后面……\012什么也没有发现！",
  ["5e:58c2"] = "啊！\012在海报的后面……\012什么也没有发现！",
  ["5e:58f0"] = "放着一个打火机！",
  ["5e:5908"] = "放着一罐果汁。\n这里被别人占了吧……\011哎呀……？里面是空的！",
  ["5e:5c59"] = "我好想要魔墙人偶啊……\n但是代币还差\011100枚……！",
  ["5e:5c8a"] = "呼呜呜呜……\012我要小心一点，\n不能大脑发热啊……\012要是花光了所有钱\n那就真的完了……",
  ["5e:5cdf"] = "欢迎光临！\012在这里，\n可以用游戏中积攒的代币\011兑换成您心仪的奖品！",
  ["5e:5d15"] = "要哪个呢？",
  ["5e:5d32"] = "{STRBUF}，可以吗？",
  ["5e:5d4e"] = "给，请收下！",
  ["5e:5d5c"] = "您的代币不够哦。",
  ["5e:5d79"] = "已经拿不下了。",
  ["5e:5d93"] = "啊，这样吗。\n请多积攒一些代币再来！",
  ["5e:5db5"] = "哎呀？\n您没有代币盒哦。",
  ["5e:5ec9"] = "莉佳：你好……\n天气真好呢。\011……好像随时都会\011感到昏昏欲睡呢……\012我是\n玉虹道馆的莉佳。\012…… …… 是这样啊！\n你从城都远道而来吗。\012……呃，\n你是要申请对战吗？\012是吗……\n我可是不会输的。",
  ["5e:5fdf"] = "莉佳：……！\n是我输了。\012你真的很强呢……\012我要把这个彩虹徽章\n送给你。",
  ["5e:6037"] = "{PLAYER}\n得到了彩虹徽章！",
  ["5e:6051"] = "莉佳：真是场精彩的对战。\n我深受感动，\011这个招式学习机就送你了。\012里面是终极吸取。\n这个优秀的招式能把\011向对方造成的伤害中的一半\011转化为宝可梦的营养。\012如果可以，\n我希望你能用上它。",
  ["5e:6130"] = "莉佳：输了\n可真叫人不甘心呢……\012但是知道世上还有强者，\n也可以激励自己呢。",
  ["5e:619d"] = "这个地方呢！\n只有女生\011才允许进来哦！",
  ["5e:61c1"] = "啊啊，不甘心！",
  ["5e:61cd"] = "倒也不是因为\n我们有多讨厌男生。\012只是有些事情\n只能在女生之间讨论。",
  ["5e:622f"] = "哎——要进行宝可梦对战？\n虽然有点刺激，但我愿意。",
  ["5e:625b"] = "哎——骗人的吧？",
  ["5e:626a"] = "哎——你有这么多徽章啊。\n这怎么可能赢得了啊！",
  ["5e:62a1"] = "哎呀？你看入迷了吗？\n是在看我还是在看花？",
  ["5e:62ce"] = "讨厌，真是的！",
  ["5e:62dd"] = "我要怎么样才能变得\n像莉佳一样温柔贤惠？",
  ["5e:630e"] = "人家要给你展示一下\n小莉佳传授的宝可梦招式！",
  ["5e:633e"] = "人家输了啦……",
  ["5e:634c"] = "人家要让莉佳姐姐\n帮人家报仇！",
  ["5e:636d"] = "莉佳姐姐\n会保护我们的！",
  ["5e:638b"] = "人家赢不了啊……",
  ["5e:639c"] = "莉佳姐姐\n比人家强得多！",
  ["5e:64ba"] = "欢迎光临！\012很不巧，\n本店正在举行大胃王比赛！\011真是抱歉！",
  ["5e:6505"] = "我嚼我嚼……！",
  ["5e:6516"] = "别和我说话啊！\n我无法集中啊！",
  ["5e:6546"] = "我吃我吃……！",
  ["5e:6554"] = "饭好不好吃不重要！\n只要分量管饱就满足了！",
  ["5e:658a"] = "我吞我吞……！",
  ["5e:6599"] = "这里味道很不错，\n但还是满金的食物\011更胜一筹！",
  ["5e:65dd"] = "我咽我咽……！",
  ["5e:65ee"] = "这家店里以前\n有人专门送代币盒，\011想找他，就去城都吧。",
  ["5e:6630"] = "我咽我咽……！\012我还能继续吃！",
  ["5e:6654"] = "再来一碗！老板！",
  ["5e:6661"] = "大胃王大赛！\n无限的时间！\011无尽的战斗！\011第一名不收任何餐费！",
  ["5e:66c3"] = "{PLAYER}找到了\n{STRBUF}！",
  ["5e:66d5"] = "但是，{PLAYER}\n已经带不走更多道具！",
  ["5e:6757"] = "顺着自行车道，\n一直往下冲，\011就能到达浅红市了。",
  ["5e:67e6"] = "前方就是自行车道。\012在这里骑上自行车，\n飞驰的感觉超级棒！\012列车和轮船可不能给你\n带来这种快感！",
  ["5e:6874"] = "嘿，你！停下！\012没带自行车的人\n不允许擅自进入\011自行车道！",
  ["5e:690a"] = "发电厂好像\n发生了什么事故。\012发电厂啊，去对面那侧\n往紫苑镇方向走就是了。",
  ["5e:6970"] = "我是有原则的保安。\n你带着宝可梦图鉴啊！\011那你可以通过了！",
  ["5e:6a0a"] = "自行车道\n前方是上坡路",
  ["5e:6a2b"] = "喂，说你呢！\n你没带自行车吧？\012前方是自行车道！\n没带自行车的人\011谢绝进入！",
  ["5f:4057"] = "青绿：唷，你来啦。\012我在红莲镇的时候\n可能有点小忧伤。\011但是此时此刻，\011我充满了对战的欲望！\012…… …… ……\012我听说你战胜了\n城都地区所有道馆？\012城都的水准该不会\n低得不像话吧？\012算了，\n只要来场对战，\011我就能知道\011你的实力是真是假！\012来吧！\n城都地区的小子！",
  ["5f:4188"] = "青绿：不可能！\012我怎么可能\n输给你这种人！！\012…… …… ……\n……切，没办法。\011这就是绿色徽章，\011归你了！",
  ["5f:41e9"] = "{PLAYER}从青绿那里\n得到了绿色徽章！",
  ["5f:4201"] = "青绿：…… …… ……\012看来我错了，\n你确实是实力非凡的\011强大训练家！\011这点我要老老实实地承认！\012不过，\n别忘了！\012我总有一天\n会把你打败的！",
  ["5f:4285"] = "青绿：听好了！\012在被我打败之前，\n你可不准输啊！",
  ["5f:42c8"] = "嗨～！\n未来的冠军！\011状态如何？\011看起来一切顺利呀！\0123年前与冠军\n展开殊死对决的男人\011正是这家道馆的馆主。\012这关可不好过啊！\n加油吧！",
  ["5f:437a"] = "你果然很强呢！\n我都要哭出来了，\011真是一场令人感动的对战！",
  ["5f:442e"] = "给宝可梦起昵称之前，\n你有没有仔细思考过？\012如果取了昵称，\n和别人交换的时候\011会更有乐趣哦！",
  ["5f:44a5"] = "这只烈雀叫做小烈，\n这只小拉达叫做小拉！",
  ["5f:44d8"] = "小烈：啾啾！",
  ["5f:44ea"] = "小拉：吱吱——！",
  ["5f:4559"] = "这里是常青市的新景点\n——训练家之屋！\011也是训练家的社交场所！\012在地下的练习场\n可以进行对战哦！",
  ["5f:45ff"] = "常青市是距离石英高原\n最近的城市。\012有很多前往石英高原的\n训练家会经过这个城市，\011所以建立了这个设施。",
  ["5f:468f"] = "地下的房间现在\n正在进行练习赛。\012我希望您能展示一下\n城都训练家的实力！",
  ["5f:46f7"] = "如果想要成为冠军，\n就必须去很多地方游历、\011必须与很多人对战啊。\012据说真新镇的那个冠军\n曾经就走遍了关都地区，\011去过所有城市！",
  ["5f:47a3"] = "呼……\n宝可梦对战可真累啊，\011我先休息一会儿……",
  ["5f:47ce"] = "地下的训练场\n正在举行练习赛！\011希望有自信的训练家\011可以积极参赛！",
  ["5f:4837"] = "没有规则，没有限制！\n和道路中的自由对战\011没什么两样！",
  ["5f:489b"] = "……这是什么？\n对战攻略……？\012上面的字难以辨识……\n就像大岩蛇爬过的痕迹！",
  ["5f:49fa"] = "这里是练习场！\n在这里可以和训练家\011进行对战！\011但是每天仅限1次！",
  ["5f:4a44"] = "这次的对战对手是\n{STRBUF}！",
  ["5f:4a61"] = "要进行对战吗？",
  ["5f:4a7c"] = "那就请进吧！\n对战马上开始！",
  ["5f:4ab0"] = "只有正在参加\n练习赛的训练家\011才可以进来！",
  ["5f:4af7"] = "这位客人，\n今天已经参加过一次了！\0121天只能对战1次，\n非常抱歉。",
  ["5f:4b57"] = "我输了……\n好遗憾……！",
  ["5f:4b66"] = "为了和你对战，\n我特地从大老远跑过来！",
  ["5f:4bd3"] = "这个城市的道馆馆主\n超级酷、超级帅气哦！",
  ["5f:4bf9"] = "去过红莲镇吗？\012从这里一直往南有座岛，\n那就是红莲镇！",
  ["5f:4c8c"] = "常青市的道馆馆主\n到底去哪了啊？\011我很想挑战他啊。",
  ["5f:4cd4"] = "常青市的道馆里面\n没有一般的道馆训练家。\012不管有没有跟班都能赢，\n这好像是馆主的基本原则。",
  ["5f:4d4a"] = "红莲镇的道馆\n好像消失不见了。\012那里的道馆馆主夏伯\n现在又在哪里干什么呢？",
  ["5f:4da7"] = "成为道馆馆主\n是我的梦想啊！",
  ["5f:4e44"] = "呀，来得好！\n好久没过游客了！\012大叔真的很高兴哦！\n这个给你！",
  ["5f:4ec4"] = "这是大叔的金珠！\n妥善地去使用它吧！\011这毕竟是大叔的金珠呀！",
  ["5f:4f34"] = "你是{PLAYER}？\012我正在担任\n大木博士的助手。\012没想到你能到这里呢！\n大木博士的研究所\011就在不远处的真新镇！",
  ["5f:5008"] = "前方的道路\n只有真正强大的\011宝可梦训练家才能通行。",
  ["5f:503e"] = "你还没有集齐\n城都的所有徽章呢！\012规定就是规定，\n我不能让你通过！",
  ["5f:5093"] = "哦——！\n那是城都的8个徽章！\011请你过去吧！",
  ["5f:50d0"] = "前方是 …… 白银山！\n里面栖息了很多\011强到可怕的宝可梦！",
  ["5f:5116"] = "要挑战宝可梦联盟吗？\n实力骇人的四天王\011正在等着接受挑战！",
  ["60:43f7"] = "空木：啊，{PLAYER}。\n你总算来了！\012今天叫你来是因为\n有事情要拜托你！\012我认识一个\n叫宝可梦爷爷的人。\012每当他看到奇怪的东西，\n都会兴奋地大喊：\011“这是重大发现！”\012就在刚才呢，\n他寄来了邮件，写着：\011“这次一定是真的！”\012虽然我很好奇，\n但是我和我的助手都\011忙于研究呢。\011我希望你能代替我去一趟。\012当然，\n我会给你伙伴宝可梦。\012它们都是最近新发现的\n稀有宝可梦哦。\011那么，选一个吧！",
  ["60:4590"] = "只要带了宝可梦，\n遇见野生的宝可梦的时候，\011就能让他们进行战斗了！",
  ["60:45c2"] = "空木：等等，等等，\n你要上哪去啊！",
  ["60:45e3"] = "空木：要选火宝可梦\n火球鼠吗！？",
  ["60:460e"] = "空木：水宝可梦\n小锯鳄可以吗！？",
  ["60:463a"] = "空木：你很中意\n草宝可梦菊草叶吗！？",
  ["60:4668"] = "空木：你仔细想好了\n再做决定吧。\011毕竟是重要的伙伴嘛。",
  ["60:46a2"] = "空木：我也觉得\n它是最好的宝可梦！",
  ["60:46c8"] = "{PLAYER}从空木博士那里\n得到了{STRBUF}！",
  ["60:46db"] = "要找宝可梦爷爷的话，\n先到隔壁的吉花市，\011然后再往前走几步。\012去那里基本就是\n一条大直路呢。",
  ["60:472f"] = "还有，如果宝可梦受伤了，\n用那边的机器\011可以给宝可梦回复体力。",
  ["60:476c"] = "哎呀，差点忘了，\n这是我的电话号码，\011有事情就联系我哦！",
  ["60:47a9"] = "{PLAYER}获得了\n空木博士的电话号码。",
  ["60:47c3"] = "宝可梦爷爷这个人啊，\n总是会去各种地方\011寻找一些稀奇古怪的东西。\012那些东西稀奇是很稀奇，\n但是好像没什么用……\012那么，\n{PLAYER}，就拜托你了！",
  ["60:4835"] = "里面装着空木博士\n发现的宝可梦！",
  ["60:485d"] = "这是什么机器呢？",
  ["60:4877"] = "要回复宝可梦吗？",
  ["60:4883"] = "空木：{PLAYER}……\n大事不妙了。\012啊，对了，\n宝可梦爷爷说的\011重大发现是什么东西？",
  ["60:48c8"] = "{PLAYER}把\n神奇蛋交给了空木博士。",
  ["60:48ef"] = "空木：这个……",
  ["60:48fb"] = "……难道是\n宝可梦的蛋！？\012如果是真的，那的确是\n重、重、重大发现啊！",
  ["60:4936"] = "空木：嗯？你从大木博士\n那里得到了宝可梦图鉴！？\012{PLAYER}，真、真的吗？\n那、那可太了不起了！\012不管怎么说，大木博士\n拥有一种可以看出\011训练家才能的能力。\012我懂了，{PLAYER}，\n你或许具备了成为冠军\011所需要的素质。\012宝可梦似乎也很喜欢你，\n要不，你干脆就去挑战\011各地的道馆怎么样？\012离这里最近的是\n桔梗市的宝可梦道馆。",
  ["60:4a85"] = "…… {PLAYER}，\n想要成为冠军，\011今后的路还很长。\012在出发之前\n先和妈妈说一声吧。",
  ["60:4af2"] = "空木：加油吧！\n我会对蛋进行调查，\011只要有发现就会联系你的！",
  ["60:4b33"] = "空木：哎呀，{PLAYER}\n你有没有见到我的助手？\012他要过去给你送蛋，\n现在应该还待在\011桔梗市的宝可梦中心……\012你错过了吗？\n就劳烦你去找找他吧。",
  ["60:4bd1"] = "空木：怎么样，\n蛋有发生什么变化吗？",
  ["60:4bf6"] = "{PLAYER}，\n蛋应已经孵化了吧。\011孵出来的宝可梦在哪里？",
  ["60:4c28"] = "空木：{PLAYER}，\n你很有精神啊！",
  ["60:4c41"] = "什么？\n那只宝可梦是……！",
  ["60:4c55"] = "蛋孵出来了啊！\012所以，宝可梦是\n从蛋中出生的……\012不，或许并不是\n所有宝可梦都这样。\012这里面还有\n许多的研究要做。",
  ["60:4cd2"] = "谢谢你，{PLAYER}！\n你帮助我们解开了\011宝可梦的秘密！\012这是我们的谢礼，\n不要客气，请收下吧。",
  ["60:4d43"] = "这是不变之石。\012有些种类的宝可梦\n培育到一定程度就会进化，\011样子也会随之改变。\012而携带不变之石的宝可梦\n不会进化。\012如果希望宝可梦保持不变，\n那就让宝可梦携带它吧。",
  ["60:4ded"] = "空木：{PLAYER}，\n我有新发现会联系你的。",
  ["60:4e1b"] = "……唉。\n……被偷走的宝可梦\011现在怎么样了啊……\012大家都说如果人品不行，\n培育的宝可梦也会变坏。",
  ["60:4e86"] = "空木：呀，{PLAYER}！\n多亏了你，\011研究取得了很大进展哦。\012这是我的一点心意，\n希望你能用上！",
  ["60:4ee7"] = "这是大师球！！\012是不论什么宝可梦\n都必定能捕捉到的\011终极精灵球！\012听说大师球\n一般只会赠与那些\011被认可的研究者……\012但是我觉得比起我，\n你才能妥善地使用它。\011{PLAYER}，你收下吧！",
  ["60:4fa4"] = "空木：呀，{PLAYER}，\n你总算是来了！\012叫你过来是因为\n有点东西想给你！\012瞧！\n这是船票。\012有了它就可以\n去关都捉宝可梦了哦！",
  ["60:5020"] = "要坐高速船的话，\n就要去浅葱市。\012……不过，{PLAYER}\n你应该比我更懂这些。\012毕竟你和宝可梦一起\n去过了各种地方嘛。\012那么，等你到了关都\n代我向大木博士问好！",
  ["60:50e9"] = "{PLAYER}！\n非常感谢你愿意帮助，\011这个就送你了！",
  ["60:5116"] = "因为这里只有两个人，\n有一点事就顾不过来……\012啊，真是太忙了。",
  ["60:5146"] = "一开始外面有很大动静……\012我和博士就想出去看看，\n这时有人偷走了宝可梦……\012居然会偷别人的东西，\n真是难以置信！\012……唉。\n……被偷走的宝可梦\011现在怎么样了啊……\012大家都说如果人品不行，\n培育的宝可梦也会变坏。",
  ["60:5229"] = "{PLAYER}！\012既然你要完成宝可梦图鉴，\n这个就送你了！",
  ["60:524b"] = "想完成宝可梦图鉴，\n就得多捕捉宝可梦！\012对野生宝可梦\n扔出精灵球，\011就可以对它进行捕捉了！",
  ["60:52a1"] = "我听说这间宝可梦研究所\n有宝可梦失窃了……\012刚才正在向空木博士\n询问事件的详情。\011似乎是一个留着\011红色长发的少年干的。\012什么！\n你和那个训练家交过手？\012他有没有告诉你\n他叫什么名字？",
  ["60:5371"] = "明白了！\n叫{RIVAL}是吧！\012非常感谢\n你的协助！",
  ["60:53ae"] = "窗户开着，\n外面的风好舒服！",
  ["60:53e2"] = "他从这里破窗而入！",
  ["60:53fd"] = "{PLAYER}拿了本书，\012书名是《探险心得1》。\012按下START键！\n就能打开菜单。",
  ["60:543b"] = "{PLAYER}拿了本书，\012书名是《探险心得2》。\012写下宝可梦记录\n就能保存进度！",
  ["60:5477"] = "{PLAYER}拿了本书，\012书名是《探险心得3》。\012打开背包\n按下SELECT键！\011就能调换道具位置！",
  ["60:54c6"] = "{PLAYER}拿了本书，\012书名是《探险心得4》。\012看宝可梦可用招式时，\n按下A键！\011就能调换招式位置！",
  ["60:5521"] = "里面有空木博士扔掉的\n点心包装袋……",
  ["60:5719"] = "喂，{PLAYER}！\n我们的邻居空木博士\011正在找你哦。\012好像是有什么事情\n想要拜托你。\012对了！差点就忘了，\n送去维修的宝可装置\011已经拿回来了。\012给！",
  ["60:57d2"] = "宝可梦装置，\n简称宝可装置。\012想成为成熟的训练家，\n这是必不可少的装备哦。\012哎呀？还没输入星期呢。\n用之前得先输入\011今天是星期几。",
  ["60:5857"] = "那么现在是夏令时\n对吧？",
  ["60:5878"] = "如果要更改时钟的夏令时，\n那就回家调整吧。\012对了，\n你知道怎么使用电话吗？",
  ["60:58e0"] = "打开宝可装置选择\n电话图标就好了，对吧？",
  ["60:591c"] = "那我就念说明书了。\012“打开宝可装置，\n选择电话图标。”",
  ["60:5965"] = "电话号码会\n自动登录在上面，\011只要选择通话对象就好了。\012打电话竟然这么轻松，\n真是太厉害了。",
  ["60:59ca"] = "空木博士在叫你哦，\n赶快过去吧！",
  ["60:59fa"] = "空木博士\n找你有什么事？\012………………\012听起来很了不得啊。\n但是，别人有求于你，\011你要放在心上哦！",
  ["60:5a6c"] = "{PLAYER}，去吧！\n妈妈会给你加油的！",
  ["60:5a92"] = "妈妈的拿手好菜！\n红莲风味火山汉堡！",
  ["60:5abc"] = "亮晶晶的水槽！\n妈妈有点小洁癖。",
  ["60:5ae9"] = "冰箱里头……\012有好多美味之水，\n还有甜～甜的果汁牛奶！",
  ["60:5b28"] = "电视上正在放电影！\n两个男孩结伴旅行，\011火车车窗映着群星……\012……我也该赶紧出发了！",
  ["60:5c5c"] = "大木博士的宝可梦讲座！\n大家一定要好好收听！",
  ["60:5c8d"] = "这是宝可梦频道！",
  ["60:5c9c"] = "我的搭档是——\n胡桃主播！",
  ["60:5cbc"] = "宝可梦\n宝可梦频道……",
  ["60:5d64"] = "皮卡丘竟然是\n进化过一次的宝可梦！\012看了那位空木博士的发表，\n我也非常震撼！\012不愧是研究宝可梦进化的\n著名的博士。\012唉……我也想成为\n像他那样了不起的研究员。",
  ["60:5e09"] = "大木博士的宝可梦讲座！\n大家一定要好好收听！",
  ["60:5e3a"] = "这是宝可梦频道！",
  ["60:5e49"] = "我的搭档是——\n胡桃主播！",
  ["60:5e69"] = "宝可梦\n宝可梦频道……",
  ["60:5eb8"] = "哎呀，{PLAYER}！\012我家的老公啊，\n看起来永远都很忙，\011会不会太辛苦了？\012他沉迷于宝可梦研究，\n真的是废寝忘食了。",
  ["60:5f2c"] = "等我长大了，\n一定要给爸爸帮忙！\012然后，我还要成为\n了不起的宝可梦博士！",
  ["60:5fdc"] = "宝可梦从哪里来？\n又要去往何方？\012为什么从来没人见过\n宝可梦诞生的那个瞬间？\012我想了解这一点！\n我将耗费我的一生\011对此进行研究！\012………………\012这是空木博士写的\n研究报告的一部分！",
  ["60:610b"] = "你的宝可梦\n看起来很累……\012请稍微让它们休息一下吧。",
  ["60:6149"] = "嗯！\n宝可梦变得活力充沛了！\011那么请加油！",
  ["60:61b7"] = "……笔记本上写了字！\n要读吗？",
  ["60:61e0"] = "……能为宝可梦训练家\n提供帮助，\011是我们一家的荣幸。\012如果有训练家搭话，\n那就要送他们方便的道具！\012致我的弟弟和妹妹\n长女星琪一留……\012要读下一页吗？",
  ["60:6277"] = "星期一的星琪一\n……40号水道\012星期二的星琪二\n……29号道路\012星期三的星祺三\n……愤怒之湖\012星期四的星祺四\n……36号道路\012星期五的星琪五\n……32号道路\012星期六的星祺六\n……烟墨市\012星期天的星祺天\n……37号道路",
  ["60:6384"] = "咻咻咻，\n你要带着宝可梦去哪？\012宝可梦联盟吗？\n你们之间的牵绊够强吗？\011能不能战无不胜呢？\012就让我给你看看吧……",
  ["60:63e9"] = "哦哦，你们非常亲密啊。\n碰到优秀的训练家真高兴，\012这是饯别礼，\n请拿去吧！",
  ["60:644d"] = "招式学习器37是沙暴！\012使用后双方都会受到伤害，\n是面向高级训练家的招式。\012总之，请加油吧。",
  ["60:64dd"] = "不稍微改善关系的话，\n想获胜就很难了。\012训练家与宝可梦之间\n要用信赖进行维系。",
  ["60:657f"] = "断坡是不可以逆向攀爬的。\012但是跳下来的时候很快，\n感觉不亏呢。",
  ["60:65cb"] = "再往前走几步，\n出现的宝可梦会略有不同。\012想要收集各种宝可梦，\n就得探索各种地方！",
  ["61:400d"] = "你好！\012格斗道场的师傅\n空手道大王\011现在正在城都的洞窟中\011进行修行！",
  ["61:4061"] = "因果报应",
  ["61:4081"] = "四面楚歌",
  ["61:4180"] = "娜姿：……你果然来了！\012其实我三年前就预感\n你会来到这里。\012你的目标，\n想必是我的徽章吧！\012虽然我这个人\n不喜欢战斗……\011但是馆主的任务就是\011把徽章交给合适的人。\012既然你这么希望了，\n我便让你\011见识一下我的超能力！",
  ["61:4295"] = "娜姿：你的实力……！\n完全超出我的预料……！\011我或许还不能完美地\011做到预测未来吧……\012好吧，\n我的金色徽章\011就送给你了。",
  ["61:4336"] = "{PLAYER}\n得到了金色徽章！",
  ["61:434e"] = "娜姿：金色徽章\n可以发掘出\011你的潜力……\012虽然我没能\n准确地预测你的实力，\011但这点我还是很清楚的……\012你的未来一片光明，\n大家都会拥戴\011你这个优秀的冠军！",
  ["61:440d"] = "娜姿：……\n你对宝可梦的那份爱，\011似乎胜过了\011我的超能力……\012我觉得，\n这份爱的力量\011也是一种超能力……",
  ["61:448a"] = "你所战胜的一切\n都化作了力量\011在我体内流淌！",
  ["61:44bc"] = "好强，强过头了！",
  ["61:44d5"] = "你的力量之源\n到底是什么啊！",
  ["61:44f8"] = "超能力是\n心灵的力量！",
  ["61:4522"] = "我的心灵力量\n不如你！",
  ["61:4547"] = "你在有意无意之中\n锻炼过自己的心灵！",
  ["61:457e"] = "呵呵呵……\n我看见了，看见了……！\012你的心灵\n我已经完全看透了！",
  ["61:45b5"] = "虽然看穿了你的心灵，\n输了就是输了！",
  ["61:45d7"] = "糟糕！\n我之前明明已经\011预测到我会输给你，\011结果却忘了！",
  ["61:460d"] = "隔壁的格斗道场\n过去也担任过\011这个城市的道馆！",
  ["61:4643"] = "打不过啊……",
  ["61:4654"] = "道场里的师傅——\n空手道大王，\012曾经被娜姿\n打了个落花流水！",
  ["61:46a2"] = "嗨～！\n未来的冠军！\012像你这种水平的训练家，\n肯定很清楚\011该怎么攻略超能力属性吧！\012我很期待哦！\n祝你好运！",
  ["61:4741"] = "真是场精彩的战斗！",
  ["61:486d"] = "紫苑镇上\n有一座巨大的播音塔。",
  ["61:4894"] = "我想变得更强，\n不过现在还差得远……\012有机会的话，\n一定要教我变强的秘诀哦。",
  ["61:493b"] = "巨大的发电厂\n在紫苑镇的北面！",
  ["61:496e"] = "我刚刚穿过岩山隧道\n来到这里。\011发电厂那边\011好像不是很太平啊……",
  ["61:49c9"] = "洞窟容易坍塌！\012已经有好几个洞窟\n完全坍塌了，\011就像华蓝洞窟那样！\012作为专业登山人，\n这是应有的常识！",
  ["61:4a60"] = "西尔佛公司总部\n以及磁浮列车车站！\012这两个地方\n是金黄市的名胜！",
  ["61:4b33"] = "…… …… ……\012…… …… ……\012…… …… ……\012…… …… 知道了！\012你想要这个对吧！",
  ["61:4b56"] = "招式学习器29是精神强念\n……你知道吗？\012……如果运气好，\n说不定就可以\011降低对手的特殊能力！",
  ["61:4c45"] = "非常抱歉，磁浮列车\n现在暂停运营。",
  ["61:4c79"] = "开往满金市的列车\n马上就要出发了。\011请问您要乘坐吗？",
  ["61:4cb3"] = "请出示一下车票！\012好了！\n请走这边！",
  ["61:4cef"] = "哎呀，这位乘客\n您没有带车票呢。",
  ["61:4d11"] = "衷心期待\n您下次乘坐我们的列车！",
  ["61:4d2c"] = "路上辛苦了。\n列车已经到达金黄市。\012衷心期待\n您下次乘坐我们的列车！",
  ["61:4d63"] = "磁浮列车是\n凭借电力与磁力运行，\011梦幻般的超特快列车！\012但是没有电的话……",
  ["61:4dfa"] = "呼……\012从关都到城都\n来回往返了多少趟了？",
  ["61:4e44"] = "磁浮列车站建成之前，\n这块地方本来是\011模仿少女的家。",
  ["61:4eb9"] = "喂喂，你有定期月票吗？\n我有哦！\012金黄市的所有人\n都会用定期月票\011来乘磁浮列车的哦！",
  ["61:4f9c"] = "欢迎光临！\n这里是西尔佛公司\011总部大楼！",
  ["61:4fcf"] = "2楼以上的楼层\n仅限员工入内。\012不过\n看你从大老远跑到这里，\011就送你这个吧！",
  ["61:5041"] = "这是\n西尔佛公司的全新产品！\011目前任何地方都买不到哦！",
  ["61:50cd"] = "我女儿喜欢模仿这一点\n真的让我非常头疼……！\012因为她没事就去捉弄别人，\n周围的人都叫她\011“模仿少女”！",
  ["61:512e"] = "我家闺女啊，\n真的是从小给惯坏了……\011朋友也没几个。",
  ["61:516c"] = "她把皮皮玩偶弄丢了，\n那是一个男孩三年前送的。\012从那以后，\n她就沉浸在模仿练习中……",
  ["61:51e4"] = "幸福蛋：幸～福～！",
  ["61:52f1"] = "{PLAYER}：呀，你好啊！\n你喜欢宝可梦嘛？\012{PLAYER}：不是说我\n我是在问你啊！\012{PLAYER}：……算了，\n你这人真奇怪！",
  ["61:533f"] = "模仿少女：……干嘛？\n你叫我不要随便模仿别人？\012可惜我的兴趣爱好\n就是模仿别人呀！",
  ["61:537b"] = "{PLAYER}：呀，你好啊！\n你弄丢了皮皮玩偶，\011一定很难过吧！\012{PLAYER}：找到的话，\n你会送我定期月票？\012{PLAYER}：那么，\n我就帮你去找吧！\012好像是当初\n去枯叶市的时候不见的！",
  ["61:542d"] = "模仿少女：……干嘛？\n你叫我不要自作主张？\012可是我真的很难过啊……\n大概被别人捡走了吧……？",
  ["61:5496"] = "模仿少女：哇——！\n我的皮皮玩偶！\011它的右腿有道伤痕！\011这就是证据！",
  ["61:54f9"] = "之前说好的，拿去！\n这是定期月票哦！",
  ["61:552b"] = "模仿少女：想乘磁浮列车\n就要用定期月票！\012之前住的家被改建成\n磁浮列车车站的时候，\011铁路公司的人\011就把这个送给我了。",
  ["61:55af"] = "{PLAYER}：呀！\n谢谢你送我定期月票！\012{PLAYER}：……干～嘛？\012{PLAYER}：模仿别人\n有那么愉快吗？",
  ["61:560c"] = "模仿少女：嗯……！\n非～常愉快哦！",
  ["61:562d"] = "嘟嘟利：叽～叽～！",
  ["61:5640"] = "……魔镜啊魔镜！\n告诉我这个世界上\011最美丽的女孩是谁？",
  ["61:567b"] = "这是稀有的宝可梦！？\n……哎呀？只是布偶。",
  ["61:5702"] = "我听说城都有很多\n历史悠久的城市。\011真想去看一次！",
  ["61:5766"] = "你是城都的人吧？\n第一次来关都感觉如何？\011是个好地方吧。",
  ["61:57ff"] = "消失——吧！\012有个不吉利的影子\n附在施主身上！\011请你带上这个！",
  ["61:5851"] = "真是好险啊！\n这下就能放心了！",
  ["61:5888"] = "我家的奶奶呀，\n一直很热衷于驱邪。\011抱歉啊，让你受惊了。",
  ["62:402c"] = "据说精灵球售罄了！\n要什么时候才有货啊！",
  ["62:406b"] = "可以买精灵球了！\n这下就能捕捉宝可梦了！",
  ["62:4098"] = "在草丛里走的时候，\n中了虫宝可梦的毒！\012然后走着走着，\n宝可梦就倒下了！\012还是带点解毒药比较好。",
  ["62:4182"] = "不管寄放多少宝可梦\n都不用交钱，好开心啊。",
  ["62:41c0"] = "放在那里的电脑，\n只要是宝可梦训练家\011就可以随意使用！",
  ["62:41e9"] = "2楼的连接俱乐部是\n前不久才建好的。\012不过，我听说\n目前还在进行调整。",
  ["62:423e"] = "2楼的连接俱乐部是\n前不久才建好的。\012我老早就去体验了\n宝可梦交换！",
  ["62:42e2"] = "作为一个宝可梦训练家，\n你想要检测自己的实力吧？\012那么你可以\n去收集城都地区\011各地的道馆徽章！",
  ["62:435d"] = "等我长大了，\n我要努力成为道馆馆主！\012为此我要和朋友进行\n宝可梦对战来磨练自己！",
  ["62:4405"] = "我年轻的时候\n也是个充满干劲的训练家！\012那么，我给你一个建议！\n多捉宝可梦！\012然后要温柔地\n对待宝可梦！",
  ["62:44bb"] = "宝可梦啊，\n一直战斗积累经验之后\011外形也会发生变化哦！",
  ["62:44f4"] = "宝可梦的外形会变吗？\012如果是突然产生变化，\n那我一定会吓一跳呢！",
  ["62:457a"] = "你知道吗，\n宝可梦会主动吃树果。\012我家的宝可梦吃了树果后\n就变得有活力了。\011对了！也分给你一些吧！",
  ["62:45e4"] = "如果你去调查树，\n就会有树果掉下来哦。",
  ["62:4755"] = "哎呀哎呀，\n你就是{PLAYER}吧。\012空木博士已经联系过我了，\n我在等着你过来。",
  ["62:4797"] = "这个就是我想委托\n空木博士调查的东西！",
  ["62:47c1"] = "{PLAYER}从宝可梦爷爷\n那里拿到了神奇蛋！",
  ["62:47da"] = "有一对夫妇专门负责\n培育别人寄放的宝可梦。\011这个就是从他们那得到的。\012我觉得这或许是大事件，\n就给空木博士发了邮件。\012在宝可梦进化方面的研究，\n空木博士可是第一人！",
  ["62:4881"] = "毕竟得到了这位\n大木博士的认可嘛。",
  ["62:48a6"] = "我的想法究竟是对是错，\n空木博士肯定能给我答案！",
  ["62:48dc"] = "你差不多也要\n回空木博士那里了吧？\012不妨先让宝可梦\n休息一下吧！",
  ["62:4923"] = "那么就拜托你了！",
  ["62:4939"] = "这个世界太有趣了！\n总会有很多新发现！",
  ["62:4974"] = "大木：呵呵！\n你就是{PLAYER}吗！\012我是大木，\n是个宝可梦研究员！\012宝可梦爷爷是我多年好友，\n我拜访他的时候，\011听说空木那边\011正好有事让你过来一趟，\011所以一直都在等你！\012呵呵！\n你带着很少见的宝可梦嘛！\012而且…… ……\012嗯嗯，我明白了！\012也难怪空木会\n把宝可梦交给你，\011并委托你帮忙！\012对于我或者空木\n这样的研究者而言，\011宝可梦是重要的伙伴！\012我相信你一定可以\n精心地去培育宝可梦。\012……对了！\012毕竟我很看好你嘛，\n就拜托你一件事情吧！\012其实呢……\012瞧！\n这是宝可梦图鉴！\012它可以自动记录\n你发现的宝可梦数据，\011页面也会随之增加，\011是一部高科技的图鉴哦！",
  ["62:4bbb"] = "{PLAYER}从大木那里\n得到了宝可梦图鉴！",
  ["62:4bcd"] = "我希望\n你能多与宝可梦相遇，\011将这个图鉴彻底填满！\012哎呀！\n我的话好像太长了！\012接下来我必须得去\n满金市录制那个\011我经常做客的广播节目！\012那么，{PLAYER}！\n就拜托你了！",
  ["62:4c65"] = "嗯？那个鳞片是？\n什么！红色暴鲤龙？\012真、真是太稀有了！\n我、我好想要……\012{PLAYER}，\n要不要和我交换一下？\011我可以给你从大木博士\011那里拿来的学习装置。",
  ["62:4cfc"] = "真是太遗憾了！\n那真是非常少见的宝贝……",
  ["62:4d32"] = "上面摆满了\n世界各地的杂志！\012…… ……\n看不懂是什么标题……",
  ["62:4d73"] = "有台大型计算机！\n……好像坏掉了。",
  ["62:4d9b"] = "上面散落着一堆\n从没见过的硬币！\011是外国的货币吗？",
  ["62:4e29"] = "哟，你去喇叭芽之塔\n参观过了吗？",
  ["62:4e4f"] = "已经走了相当远了！\n要给家里打个电话呀！",
  ["64:558e"] = "我是培育屋爷爷，\n希望我帮你培育宝可梦吗？",
  ["64:55bd"] = "我是培育屋爷爷。\n想要了解蛋吗？\012我和奶奶培育宝可梦时\n………你猜怎么着！\012竟然出现了蛋！\n这可太神奇了。\012怎么样？\n要不要培育宝可梦？",
  ["64:566a"] = "我是培育屋奶奶，\n希望我帮你培育宝可梦吗？",
  ["64:56a0"] = "我是培育屋奶奶，\n想要了解蛋吗？\012我和爷爷培育宝可梦时，\n………你猜怎么着！\012竟然出现了蛋！\n这可太神奇了。\012如何？\n要不要培育宝可梦？",
  ["64:575e"] = "那么，\n要培育哪只宝可梦？",
  ["64:577c"] = "哎呀？\n你只带了1只宝可梦！",
  ["64:579d"] = "不好意思，\n蛋是不能寄放的。",
  ["64:57bf"] = "在此之前，\n先把信件取掉。",
  ["64:57e4"] = "如果你要寄放它，\n接下来就无法战斗了。",
  ["64:5815"] = "好的，\n{STRBUF}交给我吧。",
  ["64:5830"] = "过一段时间之后，\n你再过来吧。",
  ["64:5849"] = "我们真是天才啊！要看看\n你的{STRBUF}吗？",
  ["64:587b"] = "你的{STRBUF}\n成长了许多。\012要说等级的话，\n现在提高了{NUM}级。\012……如果想领回宝可梦，\n费用是¥{NUM}哦。",
  ["64:58e9"] = "好，收到了！\n请把宝可梦带回去吧。",
  ["64:5904"] = "{PLAYER}从培育屋爷爷那\n领回了{STRBUF}！",
  ["64:5917"] = "哎呀，这么快就回来了？\n你的{STRBUF}……\012还需要\n更多时间才行。\012……如果想领回宝可梦，\n费用是¥100哦。",
  ["64:5987"] = "拿不下更多了。",
  ["64:59a1"] = "钱好像不够呢。",
  ["64:59be"] = "这样啊。",
  ["64:59ce"] = "那么以后再来吧。",
  ["64:59db"] = "还不够呢。",
  ["64:59e5"] = "啊，你来了啊！\012培养寄放的宝可梦的时候\n……突然发现！\012宝可梦不知怎么地\n就有了蛋！\012也不知道蛋是从哪来的。\n毕竟来自你的宝可梦，\011你很想要这颗蛋，对吧？",
  ["64:5a8a"] = "{PLAYER}从培育屋爷爷\n那得到了蛋！",
  ["64:5a9f"] = "要用心培育哦！",
  ["64:5ab6"] = "那么老夫就收下了哦。\n谢谢。",
  ["64:5ad7"] = "拿不下更多了，\n下次再来吧。",
  ["65:4751"] = "哦…………？",
  ["65:475b"] = "蛋孵化成\n{STRBUF}了！",
  ["65:4778"] = "要给孵化出的\n{STRBUF}起昵称吗？",
  ["65:4793"] = "是寄放在培育屋奶奶那的\n{STRBUF}。",
  ["65:47c4"] = "是寄放在培育屋爷爷那的\n{STRBUF}。",
  ["65:47f4"] = "活力满满！",
  ["65:480f"] = "对{STRBUF}\n完全没有兴趣。",
  ["65:482d"] = "好像十分中意\n{STRBUF}！",
  ["65:484c"] = "好像和{STRBUF}\n关系很好。",
  ["65:4866"] = "好像有点在意\n{STRBUF}。",
  ["65:4883"] = "信件1封\n也没有。",
  ["65:4899"] = "将清除了内容的信件\n放进背包里了。",
  ["65:48b9"] = "背包已满，\n无法收纳信件！",
  ["65:48cc"] = "文本即将被清除，\n可以吗？",
  ["65:48f1"] = "已经携带了其他道具，\n无法再携带信件了。",
  ["65:4911"] = "无法让蛋携带！",
  ["65:492d"] = "从信箱里取出了信件。",
  ["65:4993"] = "有携带了信件\n的宝可梦。\011请取下信件。",
  ["65:544a"] = "请取下信件\n再携带道具！",
  ["65:54fd"] = "取出信件的话，\n信息将会消失，可以吗？",
  ["65:5522"] = "从{STRBUF}那取出了\n信件！",
  ["65:553d"] = "道具已满，\n信件无法取出！",
  ["65:5561"] = "要将取出的信件\n传送到电脑吗？",
  ["65:5584"] = "电脑的信箱\n已满！",
  ["65:559f"] = "已将信件\n传送到电脑里。",
  ["65:5624"] = "哎呀，久等了！\012欢迎来到\n精灵宝可梦的世界！\012我叫大木，\012大家都亲切地称我为\n宝可梦博士。",
  ["65:5693"] = "精灵宝可梦，简称宝可梦。\012在这个世界里，\n到处都生活着一种叫做\011精灵宝可梦的生物！",
  ["65:56d3"] = "人们与宝可梦愉快地玩耍，\n或者一同战斗…………\011互帮互助，\011共同生活。",
  ["65:573f"] = "但是，我们并没有了解\n宝可梦的一切。\012宝可梦身上还有很多\n秘密等待我们解决！\012为了弄清这些谜团，\n我每天都要进行\011宝可梦的相关研究！",
  ["65:57b7"] = "说起来……\n我也该知道\011你叫什么名字了吧！",
  ["65:57dd"] = "{PLAYER}！\n准备好了吗？\012属于你的故事\n马上就要开始了！\012或许还有很多开心或者\n痛苦的事情在等着你！\012向着梦想与冒险！\n向着宝可梦的世界！\011出发吧！\012我们待会儿见！",
  ["65:5c61"] = "要买多少个呢？",
  ["65:5c6c"] = "是{STRBUF}啊，{NUM}个\n一共¥{NUM}，要买吗？",
  ["65:5c8c"] = "……欢迎光临。\012这里是物美价廉、\n童叟无欺的中药店！\012正所谓良药苦口，\n宝可梦可能不喜欢中药味。\011嘻嘻嘻嘻……",
  ["65:5d07"] = "要多少个？",
  ["65:5d12"] = "是{STRBUF}啊。{NUM}个\n一共¥{NUM}，行吗？",
  ["65:5d32"] = "多谢惠顾！\n谢谢哟……嘻嘻嘻。",
  ["65:5d4e"] = "哦？\n背包好像装满了呢！",
  ["65:5d6c"] = "嘻嘻嘻嘻……！\n您的钱不够呢！",
  ["65:5d8e"] = "下次再来！\n嘻嘻嘻……",
  ["65:5dab"] = "欢迎光临！\n这里是廉价道具店。\012店里卖的都是\n其他店买不到的稀有商品。\011但是每样都只有1个呢。",
  ["65:5e14"] = "{STRBUF}要¥{NUM}，\n想要吗？",
  ["65:5e31"] = "谢谢哟。",
  ["65:5e3a"] = "哎呀，哎呀。\n背包已满呢。",
  ["65:5e5b"] = "那个刚才你买过了，\n已经断货了。",
  ["65:5e8c"] = "哎呀哎呀，\n钱看起来不够呀。",
  ["65:5eaa"] = "下次再来买哦。",
  ["65:5ec3"] = "嗯？有什么事吗？\n要买药吗？",
  ["65:5ee2"] = "要买多少？",
  ["65:5eed"] = "是{STRBUF}啊。{NUM}个\n一共要¥{NUM}。",
  ["65:5f0f"] = "谢谢惠顾！",
  ["65:5f1d"] = "行李已满了呀。",
  ["65:5f3c"] = "嗯？你的钱不够。",
  ["65:5f5a"] = "这样吗？\n那就下次再会。",
  ["65:5f76"] = "你明明\n没带任何道具啊！",
  ["65:5f97"] = "要卖出多少个？",
  ["65:5fa2"] = "那么，我退您\n¥{NUM}吧。\012可以吗？",
  ["65:5fc6"] = "欢迎！\n是来买东西的吗！",
  ["65:5fe4"] = "请拿好！\n非常感谢您的光临。",
  ["65:5ffe"] = "你的钱不够呢！",
  ["65:601b"] = "您已经\n拿不下了呢！",
  ["65:603b"] = "那个道具\n无法收购！",
  ["65:605d"] = "欢迎再次光临！",
  ["65:6071"] = "除此之外，还有什么\n需要我帮忙的吗？",
  ["65:6092"] = "给出{STRBUF}。\n拿到了¥{NUM}！",
}
